node Person {
    has name: str,
        visited: bool = False;
}

edge FriendsWith {}

# This walker will greet every person it meets
walker GreetFriends {
    can greet with Person entry {
        if not here.visited {
            here.visited = True;
            print(f"Hello, {here.name}!");
            # Now, tell the walker to go to all connected friends
            visit [->:FriendsWith:->];
        }
    }
}

