"""mobUI primitives demo — one source, two platforms.

Exercises every @jac/mobui primitive (View, Text, Pressable, TextInput, Image,
ScrollView) plus StyleSheet.create. There is no div/span/button here on
purpose — mobUI apps import portable primitives from @jac/mobui and never touch
raw HTML tags. The bundler aliases @jac/mobui to the compiled client_mobui.js and
(on web only) rewrites react-native -> react-native-web.

    jac start main.jac                       # web   -> View=<div>, Text=<span> (via react-native-web)
    jac start main.jac --client react-native # native -> real RN components
"""

cl {
    import from "@jac/mobui" {
        View,
        Text,
        Pressable,
        TextInput,
        Image,
        ScrollView,
        StyleSheet
    }

    # NOTE: ``Animated`` (entrance fades via ``createAnimatedValue``) lives in
    # ``client_mobui.shims.js`` but is not yet surfaced through the core
    # ``@jac/mobui`` module surface, so the Animated entrance is omitted here.
    glob color = {
             bg: "#1e1e2f",
             surface: "#2a2a40",
             text: "#ffffff",
             muted: "#c9c9e0",
             accent: "#6c5ce7",
             field: "#ffffff"
         };
    glob space = {xs: 4, sm: 8, md: 12, lg: 16, xl: 24};
    glob radius = {md: 8, pill: 12, round: 32};
    glob size = {sm: 14, md: 18, lg: 22};
    glob weight = {semibold: "600", bold: "bold"};

    glob styles = StyleSheet.create(
             {
                 screen: {flex: 1, backgroundColor: color.bg},
                 content: {padding: space.xl, gap: space.lg},
                 title: {fontSize: size.lg, fontWeight: weight.bold, color: color.text},
                 card: {
                     padding: space.lg,
                     borderRadius: radius.pill,
                     backgroundColor: color.surface,
                     gap: space.sm
                 },
                 label: {fontSize: size.sm, color: color.muted},
                 value: {
                     fontSize: size.md,
                     fontWeight: weight.semibold,
                     color: color.text
                 },
                 input: {
                     padding: space.md,
                     borderRadius: radius.md,
                     backgroundColor: color.field,
                     color: color.bg
                 },
                 button: {
                     padding: space.md,
                     borderRadius: radius.md,
                     backgroundColor: color.accent,
                     alignItems: "center"
                 },
                 buttonLabel: {color: color.text, fontWeight: weight.bold},
                 avatar: {width: 64, height: 64, borderRadius: radius.round}
             }
         );

    def:pub app -> JsxElement {
        has count: int = 0,
            name: str = "";

        return
            <ScrollView style={styles.screen} contentContainerStyle={styles.content}>
                <View style={styles.card}>
                    <Text style={styles.title}>mobUI primitives</Text>
                </View>
                <View style={styles.card}>
                    <Text style={styles.label}>Image</Text>
                    <Image
                        source={{uri: "https://reactnative.dev/img/tiny_logo.png"}}
                        style={styles.avatar}
                    />
                </View>
                <View style={styles.card}>
                    <Text style={styles.label}>Pressable + state</Text>
                    <Text style={styles.value}>Count: {count}</Text>
                    <Pressable
                        style={styles.button}
                        onPress={lambda { count = count + 1; }}
                    >
                        <Text style={styles.buttonLabel}>Increment</Text>
                    </Pressable>
                </View>
                <View style={styles.card}>
                    <Text style={styles.label}>TextInput (controlled)</Text>
                    <TextInput
                        style={styles.input}
                        value={name}
                        placeholder="Type your name"
                        onChangeText={lambda (t: str) { name = t; }}
                    />
                    <Text style={styles.value}>Hello, {name}</Text>
                </View>
            </ScrollView>;
    }
}

# path: jac/jac/examples/notes-app/main.jac
"""Notes app UI for the CEF desktop target.

A small but real notes app that doubles as the CEF desktop smoke test. It
exercises jac-desktop infrastructure end-to-end:
  - window.__JAC_DESKTOP__ / window.__JAC_BROKER__ bootstrap injection
  - loopback broker routes at /__jac/* (health + session)
  - localStorage on a stable loopback origin (notes persist across restarts)

The bootstrap/broker diagnostics live behind a collapsible "Diagnostics"
drawer in the footer so they keep working as a smoke probe without dominating
the UI.
"""
cl {
    def:pub app -> JsxElement {
        has notes: list = [],
            activeId: str = "",
            query: str = "",
            diagnosticsOpen: bool = False,
            desktopFlag: any = None,
            brokerPrefix: str = "",
            origin: str = "",
            health: any = None,
            session: any = None,
            brokerError: str = "",
            tick: int = 0;

        # ---- persistence -------------------------------------------------
        STORAGE_KEY = "notes_app_notes_v2";

        def loadNotes -> any {
            raw = localStorage.getItem(STORAGE_KEY);
            if not raw {
                return [];
            }
            try {
                return JSON.parse(raw);
            } except Exception { }
            return [];
        }

        def persist {
            localStorage.setItem(STORAGE_KEY, JSON.stringify(notes));
        }

        # ---- note operations --------------------------------------------
        def newNote {
            id = "n_" + str(Date.now()) + "_" + str(tick);
            note = {
                "id": id,
                "title": "Untitled note",
                "body": "",
                "updatedAt": Date.now()
            };
            notes = [note] + notes;
            activeId = id;
            persist();
        }

        def selectNote(id: str) {
            activeId = id;
        }

        def deleteNote(id: str) {
            notes = [
                n
                for n in notes
                if n["id"] != id
            ];
            if activeId == id {
                activeId = notes[0]["id"] if len(notes) > 0 else "";
            }
            persist();
        }

        def patchActive(title: str, body: str) {
            if activeId == "" {
                return;
            }
            now = Date.now();
            rebuilt = [];
            for n in notes {
                if n["id"] == activeId {
                    rebuilt.append(
                        {"id": n["id"], "title": title, "body": body, "updatedAt": now}
                    );
                } else {
                    rebuilt.append(n);
                }
            }
            notes = rebuilt;
            persist();
        }

        # ---- derived helpers --------------------------------------------
        def activeNote -> any {
            if activeId == "" {
                return None;
            }
            for n in notes {
                if n["id"] == activeId {
                    return n;
                }
            }
            return None;
        }

        def filteredNotes -> list {
            q = query.strip().lower();
            if q == "" {
                return notes;
            }
            return [
                n
                for n in notes
                if q in str(n["title"]).lower() or q in str(n["body"]).lower()
            ];
        }

        def preview(body: str) -> str {
            flat = str(body).replace("\n", " ").strip();
            if len(flat) > 70 {
                return flat[:70] + "...";
            }
            return flat;
        }

        def relTime(ts: any) -> str {
            try {
                ms = int(ts);
            } except Exception {
                return "";
            }
            diff = Date.now() - ms;
            s = int(diff / 1000);
            if s < 60 {
                return "just now";
            }
            m = int(s / 60);
            if m < 60 {
                return str(m) + "m ago";
            }
            h = int(m / 60);
            if h < 24 {
                return str(h) + "h ago";
            }
            d = int(h / 24);
            if d < 7 {
                return str(d) + "d ago";
            }
            return Date(ms).toLocaleDateString();
        }

        def wordCount(body: str) -> int {
            t = str(body).strip();
            if t == "" {
                return 0;
            }
            return len(t.split());
        }

        # ---- broker probe (kept for the CEF smoke test) -----------------
        async def refreshBroker {
            prefix = window.__JAC_BROKER__ or "/__jac";
            brokerPrefix = str(prefix);
            try {
                healthRes = await fetch(brokerPrefix + "/health");
                health = await healthRes.json();
