                "dest_id": dest_id,
                "dest_type": dest_type,
                "checkin_date": checkin.isoformat(),
                "checkout_date": checkout.isoformat(),
                "adults_number": 1,
                "room_number": 1,
                "order_by": "popularity",
                "filter_by_currency": "USD",
                "locale": "en-gb",
                "units": "metric",
                "page_number": 0,
                "include_adjacency": "true",
            },
        );
        search_resp.raise_for_status();
        data = search_resp.json();

        results = data.get("result", []);
        hotels = [];

        for h in results {
            price = h.get("min_total_price");
            if price is None {
                continue;
            }

            if price > budget {
                continue;
            }

            hotels.append({
                "name": h.get("hotel_name"),
                "address": h.get("address"),
                "min_total_price": price,
                "currency": h.get("currencycode"),
                "url": h.get("url"),
            });
        }

        if not hotels {
            return [];
        }

        hotels = sorted(
            hotels,
            key=lambda x: float : abs(x.get("min_total_price") - budget)
        );

        return hotels[:3];

    } except Exception as e {
        return "Could not retrieve hotel info";
    }
}

def get_tools() {
    return {
        "search_flights_tool": search_flights,
        "search_attractions_tool": search_attractions,
        "search_hotels_tool": search_hotels
    };
}

