# path: Agentic-AI/jac-gpt-fullstack/components/ErrorAlert.cl.jac
import from "@mantine/core" { Alert, Group, Text, Button }
import from "@tabler/icons-react" { IconAlertCircle }

"""Reusable error alert for consistent user-facing error display."""
def:pub ErrorAlert(
    error: any = None,
    onClose: any = None,
    onRetry: any = None
) -> JsxElement {
    if not error {
        return <></>;
    }

    code = error.code or "ERR_UNKNOWN_FRONTEND";
    message = error.message or "Something went wrong. Please try again.";
    retryable = error.retryable or False;

    return <Alert
        icon={<IconAlertCircle size={16} />}
        color="red"
        variant="light"
        withCloseButton
        onClose={onClose}
        styles={{
            "root": {
                "background": "rgba(239, 68, 68, 0.08)",
                "border": "1px solid rgba(239, 68, 68, 0.25)"
            },
            "message": {"color": "#fecaca"}
        }}
    >
        <Group justify="space-between" align="center" wrap="nowrap">
            <Text size="sm">
                {"[" + code + "] " + message}
            </Text>
            {(
                <Button
                    size="xs"
                    variant="outline"
                    color="red"
                    onClick={onRetry}
                >
                    Retry
                </Button>
                if retryable and onRetry
                else None
            )}
        </Group>
    </Alert>;
}

# path: Agentic-AI/jac-gpt-fullstack/hooks/useAuth.cl.jac
"""Authentication hook for managing user login/register state."""

import from "@jac/runtime" { useNavigate, jacLogin, jacSignup, jacLogout, jacIsLoggedIn }

"""Hook for managing authentication state and actions."""
def:pub useAuth() -> any {
    navigate = useNavigate();

    has username: str = "";
    has password: str = "";
    has confirmPassword: str = "";
    has email: str = "";
    has error: str = "";
    has loading: bool = False;

    def handleUsernameChange(e: any) -> None {
        username = e.target.value;
    }

    def handlePasswordChange(e: any) -> None {
        password = e.target.value;
    }

    def handleConfirmPasswordChange(e: any) -> None {
        confirmPassword = e.target.value;
    }

    def handleEmailChange(e: any) -> None {
        email = e.target.value;
    }

    async def handleLogin(e: any) -> None {
        e.preventDefault();
        error = "";

        if not username or not password {
            error = "[ERR_AUTH_INPUT] Please fill in all fields";
            return;
        }

        loading = True;

        try {
            success = await jacLogin(username, password);
            if success {
                navigate("/");
            } else {
                error = "[ERR_AUTH_INVALID] Invalid username or password";
            }
        } except Exception as ex {
            console.error("Login error:", ex);
            error = "[ERR_AUTH_LOGIN] An error occurred during login";
        } finally {
            loading = False;
        }
    }

    async def handleRegister(e: any) -> None {
        e.preventDefault();
        error = "";

        if not username or not password or not email {
            error = "[ERR_AUTH_INPUT] Please fill in all fields";
            return;
        }

        if password != confirmPassword {
            error = "[ERR_AUTH_PASSWORD_MISMATCH] Passwords do not match";
            return;
        }

        if password.length < 6 {
            error = "[ERR_AUTH_WEAK_PASSWORD] Password must be at least 6 characters";
            return;
        }

        loading = True;

        try {
            success = await jacSignup(username, password);
            if success {
                # Auto-login after successful registration
                loginSuccess = await jacLogin(username, password);
                if loginSuccess {
                    navigate("/");
                } else {
                    navigate("/login");
                }
            } else {
                error = "[ERR_AUTH_REGISTER] Registration failed. Username may already exist.";
            }
        } except Exception as ex {
            console.error("Registration error:", ex);
            error = "[ERR_AUTH_REGISTER] An error occurred during registration";
        } finally {
            loading = False;
        }
    }

    def handleLogout() -> None {
        jacLogout();
        navigate("/login");
    }

    return {
        "username": username,
        "password": password,
        "confirmPassword": confirmPassword,
        "email": email,
        "error": error,
        "loading": loading,
        "handleUsernameChange": handleUsernameChange,
        "handlePasswordChange": handlePasswordChange,
        "handleConfirmPasswordChange": handleConfirmPasswordChange,
        "handleEmailChange": handleEmailChange,
        "handleLogin": handleLogin,
        "handleRegister": handleRegister,
        "handleLogout": handleLogout
    };
}

"""Get username from JWT token stored in localStorage."""
def:pub getUsernameFromToken() -> str {
    token = localStorage.getItem("jac_token");
    result = "Guest";

    if token {
        try {
            parts = token.split(".");
            if parts.length > 1 {
                payload = JSON.parse(atob(parts[1]));
                result = payload.username or payload.email or "User";
            }
        } except Exception as decode_error {
            console.error("Failed to decode token:", decode_error);
            localStorage.setItem("jac_auth_error", "[ERR_AUTH_TOKEN_DECODE] Could not read your login token. Please sign in again.");
        }
    }

    return result;
}

"""Check if user is authenticated."""
def:pub isUserAuthenticated() -> bool {
    return jacIsLoggedIn();
}

