"""MCP client singleton using Streamable HTTP transport.

Spawns a local MCP server via:
    jac mcp --transport streamable-http --port 3001
then connects to it at http://localhost:3001/mcp.
"""

import json;
import requests;
import subprocess;
import time;

obj McpClient {
    has _base_url: str = "http://localhost:3001";
    has _tools: list = [];
    has _initialized: bool = False;
    has _rpc_id: int = 0;
    has _session_id: str = "";
    has _server_process: any = None;

    def postinit() {
        try {
            self._start_server();
            self._initialize();
            self._list_tools();
            print(f"[MCP] Client ready — {len(self._tools)} tool(s) discovered.");
        } except Exception as e {
            print(f"[MCP] Startup warning: {e}. MCP tools will be unavailable.");
        }
    }

    # ── Private helpers ────────────────────────────────────────────────────────

    """Launch `jac mcp --transport streamable-http --port 3001` as a background
    subprocess and wait until the server is accepting connections."""
    def _start_server() {
        self._server_process = subprocess.Popen(
            ["jac", "mcp", "--transport", "streamable-http", "--port", "3001"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        );

        # Poll until the server is ready (up to 10 seconds)
        max_retries = 20;
        retry_delay = 0.5;
        for _ in range(max_retries) {
            # Check if process exited early (e.g. command not found)
            exit_code = self._server_process.poll();
            if exit_code is not None {
                stderr_out = self._server_process.stderr.read().decode("utf-8", errors="ignore");
                print(f"[MCP] Server process exited with code {exit_code}: {stderr_out.strip()}");
                return;
            }
            try {
                resp = requests.get(f"{self._base_url}/", timeout=1);
                print("[MCP] Server is up.");
                return;
            } except Exception {
                time.sleep(retry_delay);
            }
        }
        print("[MCP] Warning: server may not be ready yet, proceeding anyway.");
    }

    def _make_id() -> str {
        self._rpc_id += 1;
        return str(self._rpc_id);
    }

    def _build_headers(accept_sse: bool = True) -> dict {
        headers = {"Content-Type": "application/json"};
        if accept_sse {
            headers["Accept"] = "application/json, text/event-stream";
        } else {
            headers["Accept"] = "application/json";
        }
        if self._session_id {
            headers["Mcp-Session-Id"] = self._session_id;
        }
        return headers;
    }

    def _capture_session(resp: any) -> None {
        sid = resp.headers.get("Mcp-Session-Id");
        if sid {
            self._session_id = sid;
        }
    }

    """Extract the last JSON-RPC response from an SSE text stream."""
    def _parse_sse_response(text: str) -> dict {
        last_data = {};
        for line in text.strip().split("\n") {
            if line.startswith("data: ") {
                try {
                    last_data = json.loads(line[6:]);
                } except Exception {
                    print(f"[MCP] Warning: Failed to parse SSE line as JSON: {line[6:]}");
                }
            }
        }
        return last_data;
    }

    def _send_rpc(method: str, params: dict = None) -> dict {
        req = {"jsonrpc": "2.0", "id": self._make_id(), "method": method};
        if params {
            req["params"] = params;
        }
        resp = requests.post(
            f"{self._base_url}/mcp",
            data=json.dumps(req),
            headers=self._build_headers(),
            timeout=60
        );
        resp.raise_for_status();
        self._capture_session(resp);

        content_type = resp.headers.get("Content-Type", "");
        if "text/event-stream" in content_type {
            return self._parse_sse_response(resp.text);
        }
        return resp.json();
    }

    def _send_notification(method: str, params: dict = None) -> None {
        body = {"jsonrpc": "2.0", "method": method};
        if params {
            body["params"] = params;
        }
        resp = requests.post(
            f"{self._base_url}/mcp",
            data=json.dumps(body),
            headers=self._build_headers(accept_sse=False),
            timeout=10
        );
        self._capture_session(resp);
    }

    def _initialize() {
        self._send_rpc("initialize", {
            "protocolVersion": "2024-11-05",
            "capabilities": {},
            "clientInfo": {"name": "jac-mcp-server-bridge", "version": "1.0.0"}
        });
        self._send_notification("notifications/initialized");
        self._initialized = True;
    }

    def _list_tools() {
        resp = self._send_rpc("tools/list");
        self._tools = resp.get("result", {}).get("tools", []);
    }

    # ── Public API ─────────────────────────────────────────────────────────────

    """Return a human-readable list of all available MCP tools with their
    descriptions and parameter names so the LLM can decide which to call."""
    def get_tool_descriptions() -> str {
        if not self._tools {
            return "No MCP tools are currently available.";
        }
        lines = [];
        for tool in self._tools {
            name = tool.get("name", "unknown");
            desc = tool.get("description", "");
            props = list(tool.get("inputSchema", {}).get("properties", {}).keys());
            lines.append(f"- {name}: {desc} (params: {props})");
        }
        return "\n".join(lines);
    }

    """Call an MCP tool by name with the given arguments dict.
    Returns the tool's text output as a string, or an error description."""
    def call_tool(name: str, args: dict) -> str {
        if not self._initialized {
            try {
                self._initialize();
                self._list_tools();
            } except Exception as e {
                return f"MCP client unavailable: {e}. Try again or use search_docs instead.";
            }
        }

        try {
            resp = self._send_rpc("tools/call", {"name": name, "arguments": args});
            content = resp.get("result", {}).get("content", []);
            if content {
                parts = [];
                for item in content {
                    if item.get("type") == "text" {
                        parts.append(item.get("text", ""));
                    } else {
                        parts.append(str(item));
                    }
                }
                return "\n".join(parts);
            }
            error = resp.get("error");
            if error {
                return f"MCP tool error: {error}";
            }
            return "MCP tool returned no content.";
        } except Exception as e {
            return f"MCP call failed: {e}";
        }
    }

    """Terminate the background MCP server subprocess if it is running."""
    def stop_server() -> None {
        if self._server_process {
            self._server_process.terminate();
            self._server_process.wait();
            print("[MCP] Server process terminated.");
            self._server_process = None;
        }
    }

    def get_tools_length() -> int {
        return len(self._tools);
    }
}

# path: Agentic-AI/jac-gpt-fullstack/services/rag_engine.jac
import os;
import json;
import time;
import requests;
import from langchain_community.document_loaders {PyPDFDirectoryLoader, PyPDFLoader, DirectoryLoader}
import from langchain_community.document_loaders.text {TextLoader}
import from langchain_text_splitters {RecursiveCharacterTextSplitter}
import from langchain_core.documents {Document}
import from langchain_openai {OpenAIEmbeddings}
import from langchain_community.vectorstores {FAISS}
import from sentence_transformers {CrossEncoder}

glob SERPER_API_KEY: str = os.getenv('SERPER_API_KEY', '');

"""Load configuration from JSON file"""
def load_config(config_name: str) -> dict {
    try {
        config_path = os.path.join(os.path.dirname(__file__), "config", f"{config_name}.json");
        with open(config_path, 'r', encoding='utf-8') as f {
            return json.load(f);
        }
    } except Exception as e {
        print(f"Error loading config {config_name}: {e}");
        # Return default baseline config
        return {
            "rag_engine": {
                "chunk_size": 800,
                "chunk_overlap": 80,
                "similarity_search": {"k": 5}
            },
            "paths": {
                "file_path": "docs",
                "chroma_path": "chroma"
            }
        };
    }
}

obj RagEngine {
    has file_path: str;
    has faiss_path: str;
    has chunk_size: int;
    has chunk_overlap: int;
    has chunk_nos: int;
    has cross_encoder_model: str;
    has top_n: int;
    has vectorstore: FAISS = None;
    has cross_encoder: CrossEncoder = None;
    has use_reranking: bool = True;

    def postinit {
        # Initialize CrossEncoder reranker
        try {
            self.cross_encoder = CrossEncoder(self.cross_encoder_model);
            print(f"CrossEncoder reranking enabled with model: {self.cross_encoder_model}");
        } except Exception as e {
            print(f"Warning: Failed to load CrossEncoder model: {e}");
            print("Reranking will be disabled.");
            self.use_reranking = False;
        }
        print(f"RAG Engine initialized");
        print(f"Chunk size: {self.chunk_size}, Overlap: {self.chunk_overlap}, Chunk Nos: {self.chunk_nos}");

        if not os.path.exists(self.file_path) {
            os.makedirs(self.file_path);
        }

        # Load or create FAISS index
        embeddings = self.get_embedding_function();
        if os.path.exists(self.faiss_path) and os.path.isdir(self.faiss_path) {
            if embeddings is not None {
                print(f"Loading existing FAISS index from {self.faiss_path}");
                self.vectorstore = FAISS.load_local(
                    self.faiss_path,
                    embeddings,
                    allow_dangerous_deserialization=True
                );
            } else {
                print("FAISS index exists but embeddings unavailable. RAG search disabled.");
            }
        } elif embeddings is not None {
            print("Creating new FAISS index");
            documents: list = self.load_documents();
            chunks: list = self.split_documents(documents);
            self.create_faiss_index(chunks);
        } else {
            print("No FAISS index and no API key. RAG search disabled.");
        }
    }

    def load_documents {
        documents = [];

        # Load PDF files
        try {
            pdf_loader = PyPDFDirectoryLoader(self.file_path);
            pdf_docs = pdf_loader.load();
            documents.extend(pdf_docs);
            print(f"Loaded {len(pdf_docs)} PDF documents");
        } except Exception as e {
            print(f"No PDF files found or error loading PDFs: {e}");
        }

        # Load Markdown files
        try {
            md_loader = DirectoryLoader(
                self.file_path,
                glob="**/*.md",
                loader_cls=TextLoader,
                loader_kwargs={"encoding": "utf-8"}
            );
            md_docs = md_loader.load();
            documents.extend(md_docs);
            print(f"Loaded {len(md_docs)} Markdown documents");
        } except Exception as e {
            print(f"No Markdown files found or error loading Markdown: {e}");
        }

        print(f"Total documents loaded: {len(documents)}");
        return documents;
    }

    def load_document(file_path: str) {
        if file_path.endswith('.pdf') {
            loader = PyPDFLoader(file_path);
        } elif file_path.endswith('.md') {
            loader = TextLoader(file_path, encoding="utf-8");
        } else {
            raise ValueError(f"Unsupported file type: {file_path}");
        }
        return loader.load();
    }

    def add_file(file_path: str) {
        documents = self.load_document(file_path);
        chunks = self.split_documents(documents);
        self.add_to_faiss(chunks);
    }

    def split_documents(documents: list[Document]) {
        text_splitter = RecursiveCharacterTextSplitter(
            chunk_size=self.chunk_size,
            chunk_overlap=self.chunk_overlap,
            length_function=len,
            is_separator_regex=False
        );
        return text_splitter.split_documents(documents);
    }

    def get_embedding_function {
        api_key = os.getenv('OPENAI_API_KEY', '');
        if not api_key {
            print("Warning: OPENAI_API_KEY not set. Embeddings unavailable.");
            return None;
        }
        return OpenAIEmbeddings();
    }

    """Create content string enriched with metadata for better semantic matching"""
    def enrich_content_with_metadata(chunk: Document) -> str {
        source = chunk.metadata.get('source', 'unknown');
        page = chunk.metadata.get('page');
        chunk_id = chunk.metadata.get('id', '');

        metadata_prefix = f"Source: {source}";
        if page is not None {
            metadata_prefix += f", Page: {page}";
        }
        if chunk_id {
            metadata_prefix += f", ChunkID: {chunk_id}";
        }

        return f"{metadata_prefix}\n\n{chunk.page_content}";
    }

    def add_chunk_id(chunks: list[Document]) {
        last_page_id = None;
        current_chunk_index = 0;

        for chunk in chunks {
            source = chunk.metadata.get('source');
            page = chunk.metadata.get('page');

            # Handle markdown files (no page numbers)
            if page is None {
                current_page_id = f'{source}:0';
            } else {
                current_page_id = f'{source}:{page}';
            }

            if current_page_id == last_page_id {
                current_chunk_index +=1;
            } else {
                current_chunk_index = 0;
            }

            chunk_id = f'{current_page_id}:{current_chunk_index}';
            last_page_id = current_page_id;

            chunk.metadata['id'] = chunk_id;
            # Store original content and set enriched content for embedding
            chunk.metadata['original_content'] = chunk.page_content;
            chunk.page_content = self.enrich_content_with_metadata(chunk);
        }

        return chunks;
    }

    def create_faiss_index(chunks: list[Document]) {
        if len(chunks) > 0 {
            # Filter out release notes
            filtered_chunks = [
                chunk for chunk in chunks 
                if "release_notes" not in chunk.metadata.get('source', '').lower()
            ];

            if len(filtered_chunks) == 0 {
                print("No documents to index after filtering");
                return;
            }

            print(f"Creating FAISS index with {len(filtered_chunks)} chunks (with metadata enrichment)");
            filtered_chunks = self.add_chunk_id(filtered_chunks);
            self.vectorstore = FAISS.from_documents(
                filtered_chunks,
                self.get_embedding_function()
            );
            self.vectorstore.save_local(self.faiss_path);
            print(f"FAISS index saved to {self.faiss_path}");
        } else {
            print("No documents to index");
        }
    }

    def add_to_faiss(chunks: list[Document]) {
        if self.vectorstore is None {
            self.create_faiss_index(chunks);
        } else {
            if len(chunks) > 0 {
                print(f"Adding {len(chunks)} new documents to FAISS index");
                self.vectorstore.add_documents(chunks);
                self.vectorstore.save_local(self.faiss_path);
                print("FAISS index updated");
            } else {
                print("No new documents to add");
            }
        }
    }

    def rerank_results(query: str, documents: list, top_n: int = None) {

        if not self.use_reranking or self.cross_encoder is None {
            return documents;
        }

        try {
            rerank_start = time.perf_counter();
            # Extract documents and prepare query-document pairs
            docs_only = [doc for (doc, _) in documents];

            # reranked_query = """Query: ${query}
            #         Evaluate how well this document directly answers the query.
            #         Rank higher if it contains specific, relevant information that satisfies the query intent, such as clear explanations, correct syntax, concrete details, or code examples when appropriate.
            #         Rank lower if it only mentions related concepts, is overly general, or does not meaningfully address the query.
            #         Focus on semantic relevance and answer completeness rather than keyword overlap.""";

            pairs = [
                (query, doc.metadata.get('original_content', doc.page_content))
                for doc in docs_only
            ];

            # Get reranking scores
            scores = self.cross_encoder.predict(
                pairs,
                show_progress_bar=False,
                batch_size=30,              
                convert_to_numpy=True,      
                convert_to_tensor=False    
            );

            # Combine documents with their new scores
            doc_score_pairs = list(zip(docs_only, scores));

            # Sort by score in descending order
            results = sorted(doc_score_pairs, key=lambda x: float: -x[1]);

            # Filter to only include documents with score > 0.5
            # results = [(doc, float(score)) for (doc, score) in doc_score_pairs if score > 0.5];

            # Limit to top_n results
            if top_n is not None {
                results = results[:top_n];
            }

            rerank_elapsed = time.perf_counter() - rerank_start;
            print(f"Reranking time: {rerank_elapsed:.4f}s");
            print(f"Reranked {len(results)} documents using CrossEncoder (filtered to score > 0.5)");
            return results;
        } except Exception as e {
            print(f"Error during reranking: {e}");
            print("Falling back to original FAISS results");
            return documents;
        }
    }

    def get_from_faiss(query: str) {

        if self.vectorstore is None {
            print("FAISS index not initialized");
            return [];
        }
        search_start = time.perf_counter();
        results = self.vectorstore.similarity_search_with_score(query, k=self.chunk_nos);
        search_elapsed = time.perf_counter() - search_start;
        print(f"Search time: {search_elapsed:.4f}s");

        # Apply CrossEncoder reranking if enabled
        if self.use_reranking and len(results) > 0 {
            results = self.rerank_results(query, results, top_n=self.top_n);
        }

        return results;
    }

    def search(query: str) {
        print(f'Searching RAG Engine with query: {query}');
        rag_start = time.perf_counter();
        results = self.get_from_faiss(query=query);

        print(f"\n{'='*60}");
        print(f"Retrieved {len(results)} chunks for query: {query}");
        print(f"{'='*60}");

        summary = "";
        for (idx, (doc, score)) in enumerate(results, 1) {
            page = doc.metadata.get('page');
            source = doc.metadata.get('source');
            id = doc.metadata.get('id');
            chunk_txt = doc.page_content;


            # Print chunk details with score
            print(f"\nChunk {idx}:");
            print(f"  Score: {score:.4f}");
            print(f"  Source: {source}");
            print(f"  ID: {id}");
            if page is not None {
                print(f"  Page: {page}");
            }
            print(f"  Content preview: {chunk_txt[:100]}...");

            # Get original content if available (for enriched indexes)
            original_content = doc.metadata.get('original_content', chunk_txt);

            summary += f"{source} (Relevance Score: {score:.4f}) : {original_content}\n";
        }

        print(f"\n{'='*60}\n");
        rag_elapsed = time.perf_counter() - rag_start;
        print(f"RAG time: {rag_elapsed:.4f}s");
        return summary;
    }
}


obj WebSearch {
    has api_key: str = SERPER_API_KEY;
    has base_url: str = "https://google.serper.dev/search";

    def search(query: str) {
        headers = {"X-API-KEY": self.api_key, "Content-Type": "application/json"};
        payload = {"q": query};
        resp = requests.post(self.base_url, headers=headers, json=payload);
        if resp.status_code == 200 {
            data = resp.json();
            summary = "";
            results = data.get("organic", []) if isinstance(data, dict) else [];
            for r in results[:3] {
                summary += f"{r.get('title', '')}: {r.get('link', '')}\n";
                if r.get('snippet') {
                    summary += f"{r['snippet']}\n";
                }
            }
            return summary;
        }
        return f"Serper request failed: {resp.status_code}";
    }
