        }, []);

        wrapperClass = isMobile
            and "flex flex-col h-full"
            or "sticky top-0 z-30 hidden pl-2 h-[calc(100vh-4.5rem)] w-56 shrink-0 flex-col border-l border-border/50 lg:flex";

