"""
DesignSystemProvider — manages design system config in React context.
Style/base-color classes are applied to body for component style variants.
CSS vars (colors, radius) and font are computed and passed via context
for the preview panel to apply as scoped inline styles.
"""
cl import from react { createContext, useContext, useMemo, useLayoutEffect, useEffect }
cl import from .config { getDefaultConfig, getFontsData, buildRegistryTheme }

glob _DesignSystemContext: Any = createContext(None);

cl {
    def:pub DesignSystemProvider(props: Any) -> Any {
        has config: dict = props.initialConfig or getDefaultConfig();

        styleName = config["style"] or "nova";
        baseColorName = config["baseColor"] or "neutral";
        themeName = config["theme"] or "neutral";
        fontValue = config["font"] or "figtree";
        menuAccent = config["menuAccent"] or "subtle";
        menuColor = config["menuColor"] or "default";
        radiusName = config["radius"] or "default";

        registryTheme = useMemo(lambda -> Any {
            return buildRegistryTheme({
                "baseColor": baseColorName,
                "theme": themeName,
                "menuAccent": menuAccent,
                "radius": radiusName
            });
        }, [baseColorName, themeName, menuAccent, radiusName]);

        # Default theme (orange) — static, never changes with customizer
        defaultRegistryTheme = useMemo(lambda -> Any {
            dc = getDefaultConfig();
            return buildRegistryTheme({
                "baseColor": dc["baseColor"] or "neutral",
                "theme": dc["theme"] or "neutral",
                "menuAccent": dc["menuAccent"] or "subtle",
                "radius": dc["radius"] or "default"
            });
        }, []);

        themeClassName = "style-" + styleName + " base-color-" + baseColorName;

        # Default body classes — pinned to default config so header/landing never change
        defaultThemeClassName = useMemo(lambda -> Any {
            dc = getDefaultConfig();
            return "style-" + (dc["style"] or "nova") + " base-color-" + (dc["baseColor"] or "neutral");
        }, []);

        useEffect(lambda -> Any {
            if not menuColor {
                return;
            }
            menuElements = document.querySelectorAll(".cn-menu-target");
            menuElements.forEach(lambda(element: Any) -> None {
                if menuColor == "inverted" {
                    element.classList.add("dark");
                } else {
                    element.classList.remove("dark");
                }
            });
            observer = Reflect.construct(MutationObserver, [lambda -> None {
                newElements = document.querySelectorAll(".cn-menu-target");
                newElements.forEach(lambda(el: Any) -> None {
                    if menuColor == "inverted" {
                        el.classList.add("dark");
                    } else {
                        el.classList.remove("dark");
                    }
                });
            }]);
            observer.observe(document.body, {"childList": True, "subtree": True});
            return lambda -> None {
                observer.disconnect();
            };
        }, [menuColor]);

        themeStyle = useMemo(lambda -> Any {
            styleObj = {};
            selectedFont = None;
            allFonts = getFontsData();
            for f in allFonts {
                if f["value"] == fontValue {
                    selectedFont = f;
                }
            }
            if selectedFont {
                styleObj["--font-sans"] = selectedFont["family"];
                styleObj["fontFamily"] = selectedFont["family"];
            }
            return styleObj;
        }, [fontValue]);

        useLayoutEffect(lambda -> Any {
            styleEl = document.getElementById("ds-theme-vars");
            if not styleEl {
                styleEl = document.createElement("style");
                styleEl.id = "ds-theme-vars";
                document.head.appendChild(styleEl);
            }

            # Helper: extract light/dark CSS lines from a registry theme + optional font
            extractLines = lambda(rt: Any, fontVar: Any) -> Any {
                light = [];
                dark = [];
                if rt and rt["cssVars"] {
                    lv = rt["cssVars"]["light"] or {};
                    lk = Object.keys(lv);
                    for i in range(lk.length) {
                        k = lk[i];
                        v = lv[k];
                        if v { light.push("--" + k + ": " + v + ";"); }
                    }
                    dv = rt["cssVars"]["dark"] or {};
                    dk = Object.keys(dv);
                    for i in range(dk.length) {
                        k = dk[i];
                        v = dv[k];
                        if v { dark.push("--" + k + ": " + v + ";"); }
                    }
                    rv = (rt["cssVars"]["light"] or {})["radius"];
                    if rv {
                        rl = [
                            "--radius: " + rv + ";",
                            "--radius-sm: calc(" + rv + " - 4px);",
                            "--radius-md: calc(" + rv + " - 2px);",
                            "--radius-lg: " + rv + ";",
                            "--radius-xl: calc(" + rv + " + 4px);",
                            "--radius-2xl: calc(" + rv + " + 8px);",
                            "--radius-3xl: calc(" + rv + " + 12px);",
                            "--radius-4xl: calc(" + rv + " + 16px);"
                        ];
                        light = light.concat(rl);
                        dark = dark.concat(rl);
                    }
                }
                if fontVar {
                    light.push("--font-sans: " + fontVar + ";");
                    dark.push("--font-sans: " + fontVar + ";");
                }
                return {"light": light, "dark": dark};
            };

            # Default theme font
            defaultFontFamily = None;
            dc = getDefaultConfig();
            allFonts = getFontsData();
            for f in allFonts {
                if f["value"] == (dc["font"] or "figtree") {
                    defaultFontFamily = f["family"];
                }
            }

            # Body: default theme (static orange)
            bodyVars = extractLines(defaultRegistryTheme, defaultFontFamily);
            # Preview: current customized theme
            previewVars = extractLines(registryTheme, themeStyle["--font-sans"]);

            css = "body { " + bodyVars["light"].join(" ") + " } .dark body, body.dark { " + bodyVars["dark"].join(" ") + " } .ds-preview { font-family: var(--font-sans); " + previewVars["light"].join(" ") + " } .dark .ds-preview { font-family: var(--font-sans); " + previewVars["dark"].join(" ") + " }";
            styleEl.textContent = css;
            return lambda -> None {
                existing = document.getElementById("ds-theme-vars");
                if existing {
                    existing.remove();
                }
            };
        }, [registryTheme, themeStyle, defaultRegistryTheme]);

        useLayoutEffect(lambda -> Any {
            # Apply default style classes to body (pinned, never changes with customizer)
            defClasses = defaultThemeClassName.split(" ");
            for i in range(defClasses.length) {
                if defClasses[i] {
                    document.body.classList.add(defClasses[i]);
                }
            }
            return lambda -> None {
                for i in range(defClasses.length) {
                    if defClasses[i] {
                        document.body.classList.remove(defClasses[i]);
                    }
                }
            };
        }, [defaultThemeClassName]);

        contextValue = useMemo(lambda -> Any {
            return {"config": config, "setConfig": setConfig, "themeStyle": {}, "themeClassName": themeClassName};
        }, [config, themeClassName]);

        return <_DesignSystemContext.Provider value={contextValue}>
            {props.children}
        </_DesignSystemContext.Provider>;
    }

    def:pub useDesignSystem() -> Any {
        return useContext(_DesignSystemContext);
    }
}

# path: jac-shadcn/lib/export_service.jac
"""Export service — builds themed jacpack files for download.
Parses style CSS, resolves cn-* tokens in components, generates global.css,
and assembles the complete jacpack JSON.
Also provides server-side theme resolution from config params (for GET endpoint)."""

import os;
import re;
import json as json_mod;

glob BASE_COLOR_NAMES: list = ["neutral", "stone", "zinc", "gray"];

glob RADII_MAP: dict = {
    "none": "0",
    "small": "0.45rem",
    "medium": "0.625rem",
    "large": "0.875rem"
};

"""Load themes data from data/themes.json at module init."""
def _load_themes_data() -> list {
    themes_path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data", "themes.json");
    if os.path.isfile(themes_path) {
        with open(themes_path, "r") as f {
            return json_mod.load(f);
        }
    }
    return [];
}

glob _THEMES_DATA: list = _load_themes_data();

"""Find a theme by name from the loaded themes data."""
def _find_theme(name: str) -> Any {
    for theme in _THEMES_DATA {
        if theme["name"] == name {
            return theme;
        }
    }
    return None;
}

"""Resolve CSS variables from shadcn config params (server-side equivalent of buildRegistryTheme).
Returns dict with 'light' and 'dark' keys containing CSS variable mappings."""
def resolve_css_vars(shadcn_config: dict) -> dict {
    base_color_name = shadcn_config.get("baseColor", "neutral");
    theme_name = shadcn_config.get("theme", "neutral");

    base_color = _find_theme(base_color_name);
    theme = _find_theme(theme_name);

    if not base_color or not theme {
        return {"light": {}, "dark": {}};
    }

    base_css = base_color.get("cssVars", {});
    theme_css = theme.get("cssVars", {});

    light_vars: dict = {};
    light_vars.update(base_css.get("light", {}));
    light_vars.update(theme_css.get("light", {}));

    dark_vars: dict = {};
    dark_vars.update(base_css.get("dark", {}));
    dark_vars.update(theme_css.get("dark", {}));

    menu_accent = shadcn_config.get("menuAccent", "subtle");
    if menu_accent == "bold" {
        if light_vars.get("primary") {
            light_vars["accent"] = light_vars["primary"];
            light_vars["accent-foreground"] = light_vars.get("primary-foreground", "");
            light_vars["sidebar-accent"] = light_vars["primary"];
            light_vars["sidebar-accent-foreground"] = light_vars.get("primary-foreground", "");
        }
        if dark_vars.get("primary") {
            dark_vars["accent"] = dark_vars["primary"];
            dark_vars["accent-foreground"] = dark_vars.get("primary-foreground", "");
            dark_vars["sidebar-accent"] = dark_vars["primary"];
            dark_vars["sidebar-accent-foreground"] = dark_vars.get("primary-foreground", "");
        }
    }

    radius_name = shadcn_config.get("radius", "default");
    if radius_name and radius_name != "default" {
        radius_value = RADII_MAP.get(radius_name);
        if radius_value {
            light_vars["radius"] = radius_value;
            dark_vars["radius"] = radius_value;
        }
    }

    return {"light": light_vars, "dark": dark_vars};
}

"""Build jacpack from just config params (no pre-computed CSS vars needed).
Used by the GET endpoint for URL-based jac create."""
def build_jacpack_from_config(shadcn_config: dict) -> dict {
    css_vars = resolve_css_vars(shadcn_config);
    return build_jacpack(shadcn_config, css_vars);
}

"""Load the component registry manifest."""
def load_registry() -> dict {
    registry_path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "data", "registry.json");
    if os.path.isfile(registry_path) {
        with open(registry_path, "r") as f {
            return json_mod.load(f);
        }
    }
    return {"version": "1.0.0", "components": {}, "sharedDeps": {}};
}

"""Resolve a single component with its style applied.
Returns dict with name, content, npmDeps, peerComponents."""
def resolve_single_component(component_name: str, style: str) -> dict {
    registry = load_registry();
    components = registry.get("components", {});

    comp_meta = components.get(component_name);
    if not comp_meta {
        return {"error": "Component not found: " + component_name};
    }

    filename = comp_meta["file"];
    filepath = os.path.join("components", "ui", filename);

    if not os.path.isfile(filepath) {
        return {"error": "Component file not found: " + filename};
    }

    resolution_map = parse_style_css(style);

    with open(filepath, "r") as f {
        source = f.read();
    }

    resolved = resolve_component(source, resolution_map);

    return {
        "name": component_name,
        "file": filename,
        "content": resolved,
        "npmDeps": comp_meta.get("npmDeps", []),
        "peerComponents": comp_meta.get("peerComponents", [])
    };
}

