# path: this_is_jac/littlex/social_graph.jac
"""Little X - Social graph backend in idiomatic object-spatial style.

The graph holds the data: `Profile` / `Tweet` / `Channel` nodes wired by
typed edges. Walkers are the mobile agents the client spawns - each one
declares where it starts (`with Root entry`) and what to do at every node
type it lands on (`with Tweet entry`, ...). Traversal is `visit`, never a
hand-rolled loop, and shared fan-out lives in small base walkers.
"""

import datetime;

def _now -> str {
    return datetime.datetime.now(datetime.UTC).replace(tzinfo=None).isoformat() + "Z";
}

# --- View models: the typed contract returned to the client ---
obj UserView {
    has id: str,
        username: str,
        bio: str = "";
}

obj TweetView {
    has id: str,
        content: str,
        author_username: str,
        created_at: str,
        likes: list[str],
        comments: list[dict[str, str]],
        is_mine: bool = False;
}

obj ProfileView {
    has id: str,
        username: str,
        bio: str,
        followers: list[UserView],
        following: list[UserView],
        tweets: list[TweetView];
}

obj ChannelView {
    has id: str,
        name: str,
        description: str,
        creator_username: str,
        created_at: str,
        member_count: int,
        is_member: bool,
        posts: list[TweetView] = [];
}

obj TrendingTag {
    has tag: str,
        count: int;
}

# --- Edges: the relationships in the social graph ---
edge Follow {}
edge Post {}
edge Member {}
edge ChannelPost {}

# --- Graph nodes: data, plus the methods that present it as a view.
#     A node knows how to describe itself; walkers decide when to ask. ---
node Profile {
    has username: str = "",
        bio: str = "",
        created_at: str = "";

    def to_user_view -> UserView {
        return UserView(id=jid(self), username=self.username, bio=self.bio);
    }

    # Followers / following fall straight out of the edges - no graph scan.
    def to_profile_view -> ProfileView {
        followers = [p.to_user_view() for p in [self<-:Follow:<-[?:Profile]]];
        following = [p.to_user_view() for p in [self->:Follow:->[?:Profile]]];
        tweets = [t.to_view() for t in [self-->[?:Tweet]]];
        tweets.sort(key=lambda (t: TweetView) { t.created_at; }, reverse=True);
        return ProfileView(
            id=jid(self),
            username=self.username,
            bio=self.bio,
            followers=followers,
            following=following,
            tweets=tweets
        );
    }
}

node Tweet {
    has content: str = "",
        author_username: str = "",
        created_at: str = "",
        likes: list[str] = [],
        comments: list[dict[str, str]] = [];

    def to_view -> TweetView {
        mine = [root-->[?:Profile]];
        is_mine: bool = len(mine) > 0 and self.author_username == mine[0].username;
        return TweetView(
            id=jid(self),
            content=self.content,
            author_username=self.author_username,
            created_at=self.created_at,
            likes=self.likes,
            comments=self.comments,
            is_mine=is_mine
        );
    }
}

node Channel {
    has name: str = "",
        description: str = "",
        creator_username: str = "",
        created_at: str = "";

    def to_view(with_posts: bool) -> ChannelView {
        mine = [root-->[?:Profile]];
        is_member: bool = len(mine) > 0 and len([edge mine[0]->:Member:->self]) > 0;
        posts: list[TweetView] = [];
        if with_posts {
            posts = [t.to_view() for t in [self-->[?:Tweet]]];
            posts.sort(key=lambda (t: TweetView) { t.created_at; }, reverse=True);
        }
        return ChannelView(
            id=jid(self),
            name=self.name,
            description=self.description,
            creator_username=self.creator_username,
            created_at=self.created_at,
            member_count=len([self<-:Member:<-[?:Profile]]),
            is_member=is_member,
            posts=posts
        );
    }
}

# --- Profile walkers: spawn at the caller's root, act on their profile ---
walker setup_profile {
    has username: str = "",
        bio: str = "",
        reports: list[ProfileView] = [];

    can run with Root entry {
        # The `else` fires when `visit` enqueues nothing - i.e. no profile
        # exists yet - so we create one and walk into it instead.
        visit [-->[?:Profile]] else {
            fresh = here ++> Profile(created_at=_now());
            grant(fresh, level=ConnectPerm);
            visit fresh;
        }
    }

    can apply with Profile entry {
        if self.username {
            here.username = self.username;
        }
        if self.bio {
            here.bio = self.bio;
        }
        report here.to_profile_view();
    }
}

walker get_profile {
    has reports: list[ProfileView] = [];

    can run with Root entry {
        visit [-->[?:Profile]];
    }

    can give with Profile entry {
        report here.to_profile_view();
    }
}

# --- Accumulator walkers: fan out, gather at each node, report once at exit ---
walker:pub get_all_profiles {
    has results: list[UserView] = [],
        reports: list[list[UserView]] = [];

    can run with Root entry {
        for r in allroots() {
            visit [r-->[?:Profile]];
        }
    }

    can gather with Profile entry {
        self.results.append(here.to_user_view());
    }

    can deliver with Root exit {
        report self.results;
    }
}

walker get_trending {
    # `allroots()` can surface the same Tweet through more than one
    # path (e.g. via the system root and the user's own root), so a
    # bare per-visit tally would double-count. Dedupe by tweet jid.
    has counts: dict[str, int] = {},
        seen: dict[str, bool] = {},
        reports: list[list[TrendingTag]] = [];

    can run with Root entry {
        for r in allroots() {
            visit [r-->[?:Profile]-->[?:Tweet]];
        }
    }

    can tally with Tweet entry {
        tid = jid(here);
        if tid in self.seen {
            return;
        }
        self.seen[tid] = True;
        for word in here.content.split() {
            if word.startswith("#") and len(word) > 1 {
                tag = word.lower().rstrip(".,!?;:");
                self.counts[tag] = self.counts.get(tag, 0) + 1;
            }
        }
    }

    can deliver with Root exit {
        tags = [TrendingTag(tag=t, count=self.counts[t]) for t in self.counts];
        tags.sort(key=lambda (x: TrendingTag) { x.count; }, reverse=True);
        report tags[:8];
    }
}

walker load_feed {
    has search_query: str = "",
        feed: list[TweetView] = [],
        reports: list[list[TweetView]] = [];

    can run with Root entry {
        mine = [-->[?:Profile]];
        if mine {
            me = mine[0];
            visit [me-->[?:Tweet]];
            visit [me->:Follow:->[?:Profile]-->[?:Tweet]];
        }
    }

    can gather with Tweet entry {
        self.feed.append(here.to_view());
    }

    can deliver with Root exit {
        result = self.feed;
        if self.search_query {
            q = self.search_query.lower().strip();
            result = [
                t
                for t in result
                if q in t.content.lower()
            ];
        }
        result.sort(key=lambda (t: TweetView) { t.created_at; }, reverse=True);
        report result;
    }
}

walker get_channels {
    has seen: dict[str, bool] = {},
        results: list[ChannelView] = [],
        reports: list[list[ChannelView]] = [];

    can run with Root entry {
        for r in allroots() {
            visit [r-->[?:Profile]-->[?:Channel]];
        }
    }

    # A channel links to every member, so it can be reached more than once.
    can gather with Channel entry {
        cid = jid(here);
        if cid not in self.seen {
            self.seen[cid] = True;
            self.results.append(here.to_view(False));
        }
    }

    can deliver with Root exit {
        self.results.sort(key=lambda (c: ChannelView) { c.created_at; }, reverse=True);
        report self.results;
    }
}

# --- Create walkers: navigate to the caller's profile, then attach a node ---
walker create_tweet {
    has content: str;

    can run with Root entry {
        visit [-->[?:Profile]];
    }

    can make with Profile entry {
        new = here +>: Post() :+> Tweet(
            content=self.content, author_username=here.username, created_at=_now()
        );
        grant(new, level=WritePerm);
        report new.to_view();
    }
}

walker create_channel {
    has name: str,
        description: str = "";

    can run with Root entry {
        visit [-->[?:Profile]];
    }

    can make with Profile entry {
        new = here +>: Member() :+> Channel(
            name=self.name,
            description=self.description,
            creator_username=here.username,
            created_at=_now()
        );
        grant(new, level=ConnectPerm);
        report new.to_view(False);
    }
}

# --- Lookup base walkers: resolve the target node by jid via `& (id)`
#     and visit it directly. Action subclasses just react on entry. ---
walker find_profile {
    has target_id: str = "";

    can run with Root entry {
        if self.target_id {
            target = jobj(self.target_id);
            if isinstance(target, Profile) {
                visit [target];
            }
        }
    }
}

walker follow_user(find_profile) {
    can act with Profile entry {
        if jid(here) == self.target_id {
            me = [root-->[?:Profile]][0];
            me +>: Follow() :+> here;
            report {"success": True};
            disengage;
        }
    }
}

walker unfollow_user(find_profile) {
    can act with Profile entry {
        if jid(here) == self.target_id {
            me = [root-->[?:Profile]][0];
            edges = [edge me->:Follow:->here];
            if edges {
                del edges[0];
            }
            report {"success": True};
            disengage;
        }
    }
}

# `actor` is resolved once on entry so Tweet abilities need no extra lookup.
walker find_tweet {
    has tweet_id: str = "",
        actor: str = "";

    can run with Root entry {
        mine = [-->[?:Profile]];
        if mine {
            self.actor = mine[0].username;
        }
        if self.tweet_id {
            target = jobj(self.tweet_id);
            if isinstance(target, Tweet) {
                visit [target];
            }
        }
    }
}

walker like_tweet(find_tweet) {
    can act with Tweet entry {
        if jid(here) == self.tweet_id {
            if self.actor in here.likes {
                here.likes = [
                    u
                    for u in here.likes
                    if u != self.actor
                ];
                report {"liked": False, "likes": here.likes};
            } else {
                here.likes = here.likes + [self.actor];
                report {"liked": True, "likes": here.likes};
            }
            disengage;
        }
    }
}

walker delete_tweet(find_tweet) {
    can act with Tweet entry {
        if jid(here) == self.tweet_id and here.author_username == self.actor {
            del here;
            report {"success": True};
            disengage;
        }
    }
}

walker add_comment(find_tweet) {
    has content: str = "";

    can act with Tweet entry {
        if jid(here) == self.tweet_id {
            comment = {
                "username": self.actor,
                "content": self.content,
                "created_at": _now()
            };
            here.comments = here.comments + [comment];
            report {"success": True, "comment": comment};
            disengage;
        }
    }
}

walker find_channel {
    has channel_id: str = "";

    can run with Root entry {
        if self.channel_id {
            target = jobj(self.channel_id);
            if isinstance(target, Channel) {
                visit [target];
            }
        }
    }
}

walker join_channel(find_channel) {
    can act with Channel entry {
        if jid(here) == self.channel_id {
            me = [root-->[?:Profile]][0];
            if not [edge me->:Member:->here] {
                me +>: Member() :+> here;
            }
            report {"success": True};
            disengage;
        }
    }
}

walker leave_channel(find_channel) {
    can act with Channel entry {
        if jid(here) == self.channel_id {
            me = [root-->[?:Profile]][0];
            edges = [edge me->:Member:->here];
            if edges {
                del edges[0];
            }
            report {"success": True};
            disengage;
        }
    }
}

walker get_channel_detail(find_channel) {
    has reports: list[ChannelView] = [];

    can act with Channel entry {
        if jid(here) == self.channel_id {
            report here.to_view(True);
            disengage;
        }
    }
}

walker create_channel_tweet(find_channel) {
    has content: str = "";

    can act with Channel entry {
        if jid(here) == self.channel_id {
            me = [root-->[?:Profile]][0];
            if [edge me->:Member:->here] {
                new = here +>: ChannelPost() :+> Tweet(
                    content=self.content, author_username=me.username, created_at=_now()
                );
                grant(new, level=WritePerm);
                report new.to_view();
            }
            disengage;
        }
    }
}

# path: this_is_jac/source_index.jac
"""This is Jac - source-index + syntax-highlight helper for the "Browse the
source" section.

Enumerates the showcase repo's own source files (via git, so build artifacts and
node_modules are excluded for free) and highlights any one of them with Pygments
- using Jac's *own* canonical lexer (`source_lexer.JacLexer`) for every `.jac`
variant, and Pygments' built-in lexers for Python/CSS/TOML/Markdown/JSON/etc. The
client just drops the returned HTML into a <pre> via `unsafe_html`.
"""

import os;
import subprocess;
import from functools { lru_cache }
import from pygments { highlight }
import from pygments.formatters { HtmlFormatter }
import from pygments.lexers { get_lexer_by_name, get_lexer_for_filename }
import from pygments.lexers.special { TextLexer }
import from pygments.util { ClassNotFound }
import from source_lexer { JacLexer }

glob ROOT: str = os.path.dirname(os.path.abspath(__file__));
glob MAX_BYTES: int = 260000;  # cap a single file so a huge generated file can't wedge the UI

# Files git tracks (or that are untracked-but-not-ignored) we still don't want to
# render as text.
glob _BINARY_EXTS: set = {
    ".png", ".jpg", ".jpeg", ".gif", ".ico", ".webp", ".bmp",
    ".woff", ".woff2", ".ttf", ".otf", ".eot",
    ".wasm", ".so", ".dylib", ".dll", ".a", ".o", ".bin",
    ".zip", ".gz", ".tar", ".pdf", ".mp4", ".mov", ".jbc", ".pyc"
};

# Human-facing language label for the file badge.
glob _LANG: dict = {
    "jac": "Jac", "py": "Python", "css": "CSS", "toml": "TOML",
    "md": "Markdown", "json": "JSON", "svg": "SVG", "sh": "Shell",
    "ts": "TypeScript", "tsx": "TSX", "js": "JavaScript", "jsx": "JSX",
    "zig": "Zig", "html": "HTML", "txt": "Text", "yml": "YAML", "yaml": "YAML"
};

"""Pretty language label for a file path's badge."""
def _lang_label(rel: str) -> str {
    if rel.endswith(".jac") {
        return "Jac";
    }
    ext = rel.rsplit(".", 1)[-1].lower() if "." in os.path.basename(rel) else "";
    return _LANG.get(ext, ext.upper() or "Text");
}

"""The canonical Jac lexer for any `*.jac`; Pygments' best guess otherwise."""
def _lexer_for(path: str) -> any {
    if path.endswith(".jac") {
        return JacLexer(stripnl=False);
    }
    try {
        return get_lexer_for_filename(path, stripnl=False);
    } except ClassNotFound {
        if path.endswith(".svg") {
            return get_lexer_by_name("xml", stripnl=False);
        }
        return TextLexer(stripnl=False);
    }
}

"""Directory names that never hold viewable source (VCS, build output, deps).
The filesystem-walk fallback prunes these so it mirrors what git's
`--exclude-standard` drops for free."""
glob _SKIP_DIRS: set = {
    ".git", ".jac", "node_modules", "__pycache__", ".venv", "venv",
    "dist", "build", ".pytest_cache", ".mypy_cache", ".idea", ".vscode"
};

# NOTE: the per-tree parameter is `base_dir`, never `root` -- `root` is a
# reserved Jac keyword (the graph root) and using it as a param name ICEs the
# compiler (PyastGenPass "Empty py_ast on ParamVar"). See jaseci-labs#7010.
"""Candidate paths relative to `base_dir`. Prefer git (so `.gitignore` is
honored in dev and freshly-added files show up via `--others`); fall back to a
filesystem walk when git is unavailable -- e.g. a deploy pod that ships the
source tree without a `.git` dir or the `git` binary. Without the fallback the
source viewer lists nothing in-cluster while working locally."""
def _raw_files(base_dir: str) -> list {
    git_rels: list = [];
    try {
        out = subprocess.run(
            ["git", "ls-files", "--cached", "--others", "--exclude-standard"],
            cwd=base_dir, capture_output=True, text=True, timeout=15
        );
        git_rels = [r.strip() for r in out.stdout.splitlines() if r.strip()];
    } except Exception {
        git_rels = [];
    }
    if git_rels {
        return git_rels;
    }
    rels: list = [];
    for (dirpath, dirnames, filenames) in os.walk(base_dir) {
        dirnames[:] = [
            d for d in dirnames if (d not in _SKIP_DIRS) and (not d.startswith("."))
        ];
        for fn in filenames {
            rels.append(os.path.relpath(os.path.join(dirpath, fn), base_dir));
        }
    }
    return rels;
}

"""Viewable source files relative to `base_dir`, filtered + sorted. Cached per-dir."""
@lru_cache(maxsize=8)
def _source_files(base_dir: str) -> tuple {
    keep: list = [];
    for raw in _raw_files(base_dir) {
        rel = raw.strip();
        if not rel {
            continue;
        }
        if "__pycache__" in rel or os.path.basename(rel).startswith(".") {
            continue;
        }
        ext = os.path.splitext(rel)[1].lower();
        if ext in _BINARY_EXTS {
            continue;
        }
        if not os.path.isfile(os.path.join(base_dir, rel)) {
            continue;
        }
        keep.append(rel);
    }
    return tuple(sorted(keep));
}

"""Flat, sorted list of viewable source files with light metadata."""
def list_files(base_dir: str = "") -> list {
    base = base_dir or ROOT;
    files: list = [];
    for rel in _source_files(base) {
        try {
            size = os.path.getsize(os.path.join(base, rel));
        } except OSError {
            continue;
        }
        files.append({
            "path": rel,
            "name": os.path.basename(rel),
            "dir": os.path.dirname(rel),
            "lang": _lang_label(rel),
            "size": size
        });
    }
    return files;
}

"""Empty file payload carrying an error message."""
def _blank(rel: str, err: str) -> dict {
    return {
        "path": rel, "lang": "", "html": "", "lines": 0,
        "raw": "", "truncated": False, "error": err
    };
}

"""Read + highlight one file. Sandboxed to the repo's own file set."""
def get_file(rel: str, base_dir: str = "") -> dict {
    base = base_dir or ROOT;
    path = rel.lstrip("/").replace("\\", "/");
    if path not in _source_files(base) {
        return _blank(path, "File not found.");
    }
    full = os.path.realpath(os.path.join(base, path));
    if os.path.commonpath([full, os.path.realpath(base)]) != os.path.realpath(base) {
        return _blank(path, "Invalid path.");
    }
    try {
        data = open(full, encoding="utf-8", errors="replace").read();
    } except OSError {
        return _blank(path, "Could not read file.");
    }
    truncated = len(data) > MAX_BYTES;
    if truncated {
        data = data[:MAX_BYTES] + "\n... (truncated)\n";
    }
    data = data.rstrip("\n");
    # Count from the rendered HTML so the client's line gutter lines up exactly
    # (newlines render as line breaks inside <pre> regardless of span nesting).
    html = highlight(data, _lexer_for(path), HtmlFormatter(nowrap=True)).rstrip("\n");
    return {
        "path": path,
        "lang": _lang_label(path),
        "html": html,
        "lines": html.count("\n") + 1,
        "raw": data,
        "truncated": truncated,
        "error": ""
    };
}

