"""

# path: jac-load-test/jac_loadtest_web/web/services/file_walkers.sv.jac
"""File upload and proxy recorder walkers.

Phase 6 walkers to implement:
  - upload_har(workspace_id, har_file: multipart)
        -> {entries: list, security_warning: bool}
  - update_har_entries(workspace_id, enabled_entries: list[int]) -> {ok}
  - upload_credentials_csv(workspace_id, csv_file: multipart)
        -> {row_count, preview: list}
  - start_proxy(workspace_id, port: int, scope_url: str) -> {ok}
  - stop_proxy(workspace_id) -> {entries: list}

The proxy walker spins up a local aiohttp HTTP proxy on the given port.
Captured traffic is accumulated in-memory in the sv codespace until
stop_proxy is called.
"""

# path: jac-load-test/jac_loadtest_cli/jac_loadtest_cli/bridge/auth.jac
import aiohttp;
import from ..config { LoadTestConfig }

class AuthenticationError(Exception) { }

obj Credential {
    has username: str;
    has password: str;
}

obj AuthProvider {
    has _credential: Credential;
    has _login_path: str = "/user/login";

    class def from_config(config: LoadTestConfig) -> AuthProvider | None {
        if config.username and config.password {
            return AuthProvider(
                _credential=Credential(username=config.username, password=config.password),
                _login_path=config.login_path
            );
        }
        return None;
    }

    async def authenticate(vu_id: int, session: aiohttp.ClientSession, base_url: str) -> str {
        cred = self._credential;
        identity_type = "email" if "@" in cred.username else "username";
        payload = {
            "identity": {"type": identity_type, "value": cred.username},
            "credential": {"type": "password", "password": cred.password},
        };
        url = base_url.rstrip("/") + self._login_path;
        try {
            async with session.post(url, json=payload) as resp {
                if resp.status == 401 {
                    raise AuthenticationError(
                        f"Login failed for VU {vu_id} ({identity_type}={cred.username!r}): "
                        "401 Unauthorized — check credentials."
                    );
                }
                if not resp.ok {
                    raise AuthenticationError(
                        f"Login failed for VU {vu_id} ({identity_type}={cred.username!r}): "
                        f"server returned {resp.status}."
                    );
                }
                body = await resp.json();
            }
        } except aiohttp.ClientConnectorError as exc {
            raise AuthenticationError(
                f"Cannot reach login endpoint {url!r}: {exc}"
            ) from exc;
        }
        try {
            return body["data"]["token"];
        } except (KeyError, TypeError) as exc {
            raise AuthenticationError(
                f"Unexpected login response shape from {url!r}: {body!r}"
            ) from exc;
        }
    }
}

# path: jac-load-test/jac_loadtest_cli/jac_loadtest_cli/bridge/topology.jac
import json;
import os;
import from urllib.parse { urlparse, urlunparse }
import from ..config { LoadTestConfig }

obj ServiceRoute {
    has name: str;
    has prefix: str;
    has url: str;
}

obj TopologyRouter {
    has _routes: list;
    has _fallback_url: str | None = None;

    def __post_init__() {
        self._routes = sorted(self._routes, key=lambda r: len(r.prefix), reverse=True);
    }

    def resolve(entry_url: str) -> tuple {
        parsed = urlparse(entry_url);
        path = parsed.path;

        for route in self._routes {
            if _prefix_matches(path, route.prefix) {
                t = urlparse(route.url);
                if route.prefix {
                    service_path = path[len(route.prefix):] or "/";
                } else {
                    service_path = path;
                }
                base_path = t.path.rstrip("/") if t.path else "";
                routed_path = f"{base_path}{service_path}" if base_path else service_path;
                routed = urlunparse((
                    t.scheme, t.netloc,
                    routed_path, parsed.params, parsed.query, "",
                ));
                return (routed, route.name);
            }
        }

        if self._fallback_url {
            t = urlparse(self._fallback_url);
            base_path = t.path.rstrip("/") if t.path else "";
            routed_path = f"{base_path}{path}" if base_path else path;
            routed = urlunparse((
                t.scheme, t.netloc,
                routed_path, parsed.params, parsed.query, "",
            ));
            return (routed, "gateway");
        }

        raise ValueError(
            f"No route for path '{path}' and no --url fallback provided. "
            "Use --services-map or add [plugins.scale.microservices.routes] to jac.toml."
        );
    }

    class def from_config(config: LoadTestConfig) -> TopologyRouter {
        if config.mode != "microservice" {
            return TopologyRouter(
                _routes=[ServiceRoute(name="monolith", prefix="", url=config.url or "")],
                _fallback_url=None,
            );
        }
        return _build_microservice_topology(config);
    }
}

def _build_microservice_topology(config: LoadTestConfig) -> TopologyRouter {
    toml_routes = _load_toml_routes();

    if config.services_map {
        try {
            services_json = json.loads(config.services_map);
        } except json.JSONDecodeError as exc {
            raise ValueError(f"--services-map is not valid JSON: {exc}") from exc;
        }

        routes = [];
        for item in services_json.items() {
            name = item[0];
            url = item[1];
            prefix = toml_routes.get(name);
            if prefix is None {
                if name.startswith("/") {
                    prefix = name;
                } else {
                    raise ValueError(
                        f"--services-map key '{name}' has no matching route in jac.toml "
                        "and does not start with '/'. "
                        "Use a path prefix as the key or add '[plugins.scale.microservices.routes]' to jac.toml."
                    );
                }
            }
            routes.append(ServiceRoute(
                name=name.lstrip("/") if name.startswith("/") else name,
                prefix=prefix,
                url=url.rstrip("/"),
            ));
        }
        return TopologyRouter(_routes=routes, _fallback_url=config.url);
    }

    if not toml_routes {
        raise ValueError(
            "Microservice mode requires either --services-map or "
            "[plugins.scale.microservices.routes] in jac.toml. Neither was found."
        );
    }

    routes = [];
    missing = [];
    for item in toml_routes.items() {
        name = item[0];
        prefix = item[1];
        env_var = f"JAC_SV_{name.upper()}_URL";
        url = os.environ.get(env_var);
        if not url {
            missing.append(env_var);
        } else {
            routes.append(ServiceRoute(name=name, prefix=prefix, url=url.rstrip("/")));
        }
    }

    if missing {
        raise ValueError(
            f"Microservice mode: missing environment variable(s): {', '.join(missing)}. "
            "Expected format: JAC_SV_<SERVICE_NAME>_URL=http://host:port"
        );
    }

    return TopologyRouter(_routes=routes, _fallback_url=config.url);
}

def _prefix_matches(path: str, prefix: str) -> bool {
    if not prefix {
        return True;
    }
    return path == prefix or path.startswith(prefix + "/");
}

def _load_toml_routes -> dict {
    try {
        import from pathlib { Path }
        import from jac_scale.config_loader { get_scale_config, reset_scale_config }
        reset_scale_config();
        ms_config = get_scale_config(project_dir=Path.cwd()).get_microservices_config();
        return dict(ms_config.get("routes", {}));
    } except Exception {
        return {};
    }
}

def resolve_url(path: str, routing_table: dict, fallback_url: str | None) -> str {
    for prefix in sorted(routing_table, key=len, reverse=True) {
        if path.startswith(prefix) {
            return routing_table[prefix];
        }
    }
    if fallback_url {
        return fallback_url;
    }
    raise ValueError(f"No route for path '{path}' and no --url fallback provided.");
}

# path: jac-load-test/jac_loadtest_cli/tests/unit/test_config.jac
"""Unit tests for config.jac — three-layer resolution: CLI > jac.toml > built-in defaults."""

import types;
import from unittest { mock }
import from jac_loadtest_cli.config { BUILT_IN_DEFAULTS, from_args, parse_duration, _load_toml_defaults }
import jac_loadtest_cli.config as _cfg_mod;


# ---------------------------------------------------------------------------
# parse_duration
# ---------------------------------------------------------------------------

test "parse duration seconds" {
    assert parse_duration("30s") == 30.0;
}

test "parse duration minutes" {
    assert parse_duration("2m") == 120.0;
}

test "parse duration hours" {
    assert parse_duration("1h") == 3600.0;
}


# ---------------------------------------------------------------------------
# CLI wins over toml and defaults
# ---------------------------------------------------------------------------

test "cli overrides toml" {
    with mock.patch("jac_loadtest_cli.config._load_toml_defaults", return_value={"vus": 50}) {
        cfg = from_args(types.SimpleNamespace(har_file="x.har", url="http://localhost", vus=10));
    }
    assert cfg.vus == 10;
}

test "cli overrides defaults" {
    with mock.patch("jac_loadtest_cli.config._load_toml_defaults", return_value={}) {
        cfg = from_args(types.SimpleNamespace(har_file="x.har", url="http://localhost", iterations=5));
    }
    assert cfg.iterations == 5;
}


# ---------------------------------------------------------------------------
# Toml wins over defaults when CLI not set
# ---------------------------------------------------------------------------

test "toml overrides defaults" {
    with mock.patch.object(_cfg_mod, "_load_toml_defaults", return_value={"vus": 50, "ramp_up": "10s"}) {
        cfg = from_args(types.SimpleNamespace(har_file="x.har", url="http://localhost"));
    }
    assert cfg.vus == 50;
    assert cfg.ramp_up == "10s";
}

test "toml login path override" {
    with mock.patch.object(_cfg_mod, "_load_toml_defaults", return_value={"login_path": "/auth/login"}) {
        cfg = from_args(types.SimpleNamespace(har_file="x.har", url="http://localhost"));
    }
    assert cfg.login_path == "/auth/login";
}


# ---------------------------------------------------------------------------
# Missing / empty toml falls back to built-in defaults
# ---------------------------------------------------------------------------

test "missing toml uses defaults" {
    with mock.patch("jac_loadtest_cli.config._load_toml_defaults", return_value={}) {
        cfg = from_args(types.SimpleNamespace(har_file="x.har", url="http://localhost"));
    }
    assert cfg.vus == BUILT_IN_DEFAULTS["vus"];
    assert cfg.think_time == BUILT_IN_DEFAULTS["think_time"];
}

test "load toml defaults swallows exceptions" {
    with mock.patch("jac_scale.config_loader.get_scale_config", side_effect=Exception("unavailable")) {
        result = _load_toml_defaults();
    }
    assert result == {};
}


# ---------------------------------------------------------------------------
# CLI-only fields are never sourced from toml
# ---------------------------------------------------------------------------

test "cli only fields not from toml" {
    with mock.patch("jac_loadtest_cli.config._load_toml_defaults", return_value={"url": "http://toml-host", "username": "toml-user"}) {
        cfg = from_args(types.SimpleNamespace(har_file="x.har"));
    }
    assert cfg.url is None;
    assert cfg.username is None;
}

test "iterations defaults to one" {
    with mock.patch("jac_loadtest_cli.config._load_toml_defaults", return_value={}) {
        cfg = from_args(types.SimpleNamespace(har_file="x.har", url="http://localhost"));
    }
    assert cfg.iterations == 1;
}

# path: jac-load-test/jac_loadtest_cli/tests/unit/test_har_parser.jac
"""Unit tests for core/har_parser.jac — no network, no external file I/O except temp HAR files."""

import json;
import io;
import os;
import sys;
import shutil;
import tempfile;
import from pathlib { Path }
import from jac_loadtest_cli.core.har_parser { parse_har }

glob _FIXTURES_DIR: str = str(Path(__file__).parent.parent / "fixtures");


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def make_har(entries: list | None = None) -> dict {
    default_entries = [
        {
            "request": {
                "method": "POST",
                "url": "http://recorded-host:8000/user/login",
                "headers": [],
                "postData": {
                    "mimeType": "application/json",
                    "text": '{"identity":{"type":"username","value":"u"},"credential":{"type":"password","password":"p"}}',
                },
                "queryString": [],
            },
            "response": {"status": 200, "content": {"mimeType": "application/json"}},
            "timings": {"send": 1, "wait": 50, "receive": 5},
        },
        {
            "request": {
                "method": "POST",
                "url": "http://recorded-host:8000/walker/search",
                "headers": [],
                "postData": {"mimeType": "application/json", "text": '{"query":"test"}'},
                "queryString": [],
            },
            "response": {"status": 200, "content": {"mimeType": "application/json"}},
            "timings": {"send": 1, "wait": 42, "receive": 8},
        },
    ];
    return {
        "log": {
            "version": "1.2",
            "entries": entries if entries is not None else default_entries,
        }
    };
}

def _entry(
    method: str = "POST",
    url: str = "http://recorded-host:8000/walker/search",
    headers: list | None = None,
    mime: str = "application/json",
    body: str | None = None,
    wait_s: int = 42,
) -> dict {
    return {
        "request": {
            "method": method,
            "url": url,
            "headers": headers if headers is not None else [],
            "postData": {"mimeType": mime, "text": body} if body is not None else None,
            "queryString": [],
        },
        "response": {"status": 200, "content": {"mimeType": mime}},
        "timings": {"send": 1, "wait": wait_s, "receive": 5},
    };
}

def _entry_with_resource_type(resource_type: str, url: str = "http://h:8000/endpoint") -> dict {
    e = _entry(url=url);
    e["_resourceType"] = resource_type;
    return e;
}

def _entry_missing_body(method: str = "POST", url: str = "http://h:8000/walker/create") -> dict {
    return {
        "request": {
            "method": method,
            "url": url,
            "headers": [{"name": "Content-Length", "value": "42"}],
            "postData": None,
            "queryString": [],
        },
        "response": {"status": 200, "content": {"mimeType": "application/json"}},
        "timings": {"send": 1, "wait": 10, "receive": 2},
    };
}

def _write_har(data: dict) -> str {
    tmp = tempfile.NamedTemporaryFile(mode="w", suffix=".har", delete=False);
    json.dump(data, tmp);
    tmp.close();
    return tmp.name;
}

def _capture_stderr(fn: object) -> str {
    old = sys.stderr;
    buf = io.StringIO();
    sys.stderr = buf;
    fn();
    captured = buf.getvalue();
    sys.stderr = old;
    return captured;
}


# ---------------------------------------------------------------------------
# Basic parsing
# ---------------------------------------------------------------------------

test "parse minimal" {
    har = make_har();
    path = _write_har(har);
    entries = parse_har(path, target_url="http://target:9000");
    assert len(entries) == 2;
    assert entries[0].method == "POST";
    assert entries[0].url.startswith("http://target:9000");
    assert entries[0].think_time_ms == 50;
    assert entries[1].think_time_ms == 42;
}

test "mime filter default" {
    har = make_har(entries=[
        _entry(url="http://h:8000/api/data", mime="application/json"),
        _entry(url="http://h:8000/img.png",  mime="image/png"),
        _entry(url="http://h:8000/style.css", mime="text/css"),
        _entry(url="http://h:8000/font.woff2", mime="font/woff2"),
    ]);
    path = _write_har(har);
    entries = parse_har(path, target_url="http://target:9000");
    assert len(entries) == 1;
    assert "/api/data" in entries[0].url;
}

test "include static flag" {
    har = make_har(entries=[
        _entry(url="http://h:8000/api",       mime="application/json"),
        _entry(url="http://h:8000/img.png",   mime="image/png"),
        _entry(url="http://h:8000/style.css", mime="text/css"),
    ]);
    path = _write_har(har);
    entries = parse_har(path, target_url="http://target:9000", include_static=True);
    assert len(entries) == 3;
}

test "url rewriting origin" {
    har = make_har(entries=[_entry(url="http://recorded-host:8000/walker/search?q=hello")]);
    path = _write_har(har);
    entries = parse_har(path, target_url="http://staging.app.com:9000");
    assert entries[0].url == "http://staging.app.com:9000/walker/search?q=hello";
}

test "url rewriting port" {
    har = make_har(entries=[_entry(url="http://localhost:8000/user/login")]);
    path = _write_har(har);
    entries = parse_har(path, target_url="http://localhost:9999");
    assert entries[0].url.startswith("http://localhost:9999");
    assert "/user/login" in entries[0].url;
}

test "header sanitization" {
    headers = [
        {"name": "Authorization",  "value": "Bearer secret"},
        {"name": "Cookie",         "value": "session=abc"},
        {"name": "Host",           "value": "recorded-host:8000"},
        {"name": "Content-Length", "value": "42"},
        {"name": "Content-Type",   "value": "application/json"},
        {"name": "X-Custom",       "value": "keep-me"},
    ];
    har = make_har(entries=[_entry(headers=headers, body='{"key": "val"}')]);
    path = _write_har(har);
    entries = parse_har(path, target_url="http://target:9000");
    hdrs = entries[0].headers;
    assert "Authorization"  not in hdrs;
    assert "Cookie"         not in hdrs;
    assert "Host"           not in hdrs;
    assert "Content-Length" not in hdrs;
    assert hdrs.get("Content-Type") == "application/json";
    assert hdrs.get("X-Custom") == "keep-me";
}

test "login detection default" {
    har = make_har(entries=[
        _entry(url="http://h:8000/user/login"),
        _entry(url="http://h:8000/walker/search"),
    ]);
    path = _write_har(har);
    entries = parse_har(path, target_url="http://t:9000");
    assert entries[0].is_login is True;
    assert entries[1].is_login is False;
}

test "login detection custom path" {
    har = make_har(entries=[
        _entry(url="http://h:8000/api/auth"),
        _entry(url="http://h:8000/user/login"),
    ]);
    path = _write_har(har);
    entries = parse_har(path, target_url="http://t:9000", login_path="/api/auth");
    assert entries[0].is_login is True;
    assert entries[1].is_login is False;
}

test "think time extraction" {
    har = make_har(entries=[_entry(wait_s=123)]);
    path = _write_har(har);
    entries = parse_har(path, target_url="http://t:9000");
    assert entries[0].think_time_ms == 123.0;
}

test "security warning emitted" {
    src = os.path.join(_FIXTURES_DIR, "minimal.har");
    tmp = tempfile.NamedTemporaryFile(mode="w", suffix=".har", delete=False);
    tmp.close();
    shutil.copy(src, tmp.name);

    def _run() {
        parse_har(tmp.name, target_url="http://t:9000");
    }
    captured = _capture_stderr(_run);
    assert "Authorization" in captured or "Cookie" in captured or "sensitive" in captured;
}

test "security warning suppressed when no sensitive headers" {
    har = make_har(entries=[
        _entry(url="http://h:8000/walker/search", headers=[
            {"name": "Content-Type", "value": "application/json"}
        ])
    ]);
    path = _write_har(har);

    def _run() {
        parse_har(path, target_url="http://t:9000");
    }
    captured = _capture_stderr(_run);
    assert "Warning" not in captured;
}

test "har 1.1 compat" {
    entry = {
        "request": {
            "method": "GET",
            "url": "http://h:8000/ping",
            "headers": [],
            "queryString": [],
        },
        "response": {"status": 200, "content": {"mimeType": "application/json"}},
        "timings": {"send": 1, "wait": 10, "receive": 2},
    };
    har = {"log": {"version": "1.1", "entries": [entry]}};
    path = _write_har(har);
    entries = parse_har(path, target_url="http://t:9000");
    assert len(entries) == 1;
    assert entries[0].think_time_ms == 10.0;
}

test "entry order preserved" {
    har = make_har(entries=[
        _entry(url="http://h:8000/a"),
        _entry(url="http://h:8000/b"),
        _entry(url="http://h:8000/c"),
    ]);
    path = _write_har(har);
    entries = parse_har(path, target_url="http://t:9000");
    paths = [e.original_url for e in entries];
    assert paths == [
