"""SchemaForm – auto-generate form inputs from a JSON Schema (MCP inputSchema).

Handles: string, number, integer, boolean, array (simple), object (nested keys).
"""

cl import from "react" { useState, useEffect }
cl import from .primitives { Input, Btn, Textarea, Select }
cl import from "@monaco-editor/react" { default as MonacoEditor }

def RenderFieldForSchema(schema: Any, path: Any, value: Any, onChange: Any) -> Any {
    safeSchema = schema or {};
    schemaType = safeSchema.type or "string";
    description = safeSchema.description or "";
    enumValues = safeSchema.enum;

    if enumValues and len(enumValues) > 0 {
        opts = enumValues.map(lambda(v: Any) -> Any { return {"value": v, "label": String(v)}; });
        return <Select
            value={value or ""}
            onChange={lambda(e: Any) -> None { onChange(path, e.target.value); }}
            options={opts}
        />;
    }

    if schemaType == "boolean" {
        return <label className="flex items-center gap-2 cursor-pointer">
            <input
                type="checkbox"
                checked={Boolean(value)}
                onChange={lambda(e: Any) -> None { onChange(path, e.target.checked); }}
                className="w-4 h-4 rounded border-border bg-card text-primary focus:ring-primary accent-primary"
            />
            <span className="text-sm text-foreground">{description or path}</span>
        </label>;
    }

    if schemaType == "number" or schemaType == "integer" {
        return <Input
            inputType="number"
            value={value or ""}
            onChange={lambda(e: Any) -> None {
                onChange(path, Number(e.target.value));
            }}
            placeholder={description or f"Enter {path}"}
        />;
    }

    if schemaType == "object" {
        subProps = safeSchema.properties or {};
        return <div className="pl-3 border-l border-border flex flex-col gap-3">
            {Object.keys(subProps).map(lambda(key: Any) -> Any {
                subSchema = subProps[key] or {};
                subValue = (value or {})[key];
                    return <div key={key}>
                    <label className="block text-xs font-medium text-muted-foreground mb-1">{key}</label>
                    <RenderFieldForSchema schema={subSchema} path={f"{path}.{key}"} value={subValue} onChange={onChange}/>
                </div>;
            })}
        </div>;
    }

    if schemaType == "array" {
        arrValue = value or [];
        itemSchema = safeSchema.items or {"type": "string"};

        def addItem -> None {
            newArr = arrValue.concat([""]);
            onChange(path, newArr);
        }

        def removeItem(idx: Any) -> None {
            newArr = arrValue.filter(lambda(_, i: Any) -> Any { return i != idx; });
            onChange(path, newArr);
        }

        def updateItem(idx: Any, val: Any) -> None {
            newArr = arrValue.map(lambda(item: Any, i: Any) -> Any {
                if i == idx { return val; }
                return item;
            });
            onChange(path, newArr);
        }

        return <div className="flex flex-col gap-2">
            {arrValue.map(lambda(item: Any, i: Any) -> Any {
                return <div key={i} className="flex items-center gap-2">
                    <div className="flex-1">
                        <RenderFieldForSchema schema={itemSchema} path={f"{path}[{i}]"} value={item} onChange={lambda(_, v: Any) -> None { updateItem(i, v); }}/>
                    </div>
                    <button
                        onClick={lambda -> None { removeItem(i); }}
                        className="text-destructive hover:text-destructive/80 text-xs px-1"
                    >✕</button>
                </div>;
            })}
            <button
                onClick={addItem}
                className="text-xs text-primary hover:text-primary/80 text-left cursor-pointer"
            >+ Add item</button>
        </div>;
    }

    # Code editor: detect by field name or schema format
    codeFieldNames = ["code", "source", "source_code", "jac_code", "python_code", "script", "snippet"];
    lowerPath = path.toLowerCase();
    isCodeField = codeFieldNames.includes(lowerPath) or safeSchema.format == "code";

    if isCodeField {
        has editorTheme: Any = "vs-dark";

        useEffect(lambda -> Any {
            `root = document.documentElement;
            isDark = `root.classList.contains("dark");
            editorTheme = "vs-dark" if isDark else "vs";

            observer = Reflect.construct(MutationObserver, [lambda(mutations: Any) -> None {
                editorTheme = "vs-dark" if document.documentElement.classList.contains("dark") else "vs";
            }]);
            observer.observe(`root, {"attributes": True, "attributeFilter": ["class"]});

            return lambda -> None { observer.disconnect(); };
        }, []);

        def handleEditorChange(val: Any) -> None {
            onChange(path, val or "");
        }

        return <div className="monaco-container">
            <MonacoEditor
                height="300px"
                defaultLanguage="python"
                theme={editorTheme}
                value={value or ""}
                onChange={handleEditorChange}
                options={{
                    "minimap": {"enabled": False},
                    "fontSize": 13,
                    "lineNumbers": "on",
                    "scrollBeyondLastLine": False,
                    "wordWrap": "on",
                    "tabSize": 4,
                    "insertSpaces": True,
                    "automaticLayout": True,
                    "padding": {"top": 12, "bottom": 12},
                    "renderLineHighlight": "line",
                    "scrollbar": {"verticalScrollbarSize": 6, "horizontalScrollbarSize": 6},
                    "overviewRulerBorder": False,
                    "hideCursorInOverviewRuler": True
                }}
            />
        </div>;
    }

    # Default: string (use textarea for long strings)
    if safeSchema.format == "textarea" or (description and len(description) > 50) {
        return <Textarea
            value={value or ""}
            onChange={lambda(e: Any) -> None { onChange(path, e.target.value); }}
            placeholder={description or f"Enter {path}"}
            rows={3}
        />;
    }

    return <Input
        inputType="text"
        value={value or ""}
        onChange={lambda(e: Any) -> None { onChange(path, e.target.value); }}
        placeholder={description or f"Enter {path}"}
    />;
}

def setNestedValue(source: Any, path: Any, value: Any) -> Any {
    parts = path.split(".");
    result = {**source};
    current = result;
    i = 0;
    while i < len(parts) - 1 {
        part = parts[i];
        if not current[part] {
            current[part] = {};
        }
        current = current[part];
        i = i + 1;
    }
    current[parts[len(parts) - 1]] = value;
    return result;
}

def:pub SchemaForm(props: Any) -> JsxElement {
    schema = props.schema or {};
    onSubmit = props.onSubmit;
    submitLabel = props.submitLabel or "Execute";
    loading = props.loading or False;

    has formValues: Any = {};

    properties = schema.properties or {};
    required = schema.required or [];
    propKeys = Object.keys(properties);

    def handleFieldChange(path: Any, value: Any) -> None {
        formValues = setNestedValue(formValues, path, value);
    }

    def handleSubmit -> None {
        if onSubmit {
            onSubmit(formValues);
        }
    }

    if len(propKeys) == 0 {
        return <div className="flex flex-col gap-3">
            <p className="text-xs text-muted-foreground italic">This tool takes no arguments.</p>
            <Btn variant="primary" onClick={handleSubmit} loading={loading}>
                {submitLabel}
            </Btn>
        </div>;
    }

    return <div className="flex flex-col gap-4">
        {propKeys.map(lambda(key: Any) -> Any {
            fieldSchema = properties[key] or {};
            isRequired = required.includes(key);
            return <div key={key} className="flex flex-col gap-1">
                <div className="flex items-center gap-1">
                    <label className="text-sm font-medium text-foreground">{key}</label>
                    {isRequired and <span className="text-destructive text-xs">*</span>}
                    {fieldSchema.description and
                        <span className="text-xs text-muted-foreground ml-1">– {fieldSchema.description}</span>
                    }
                </div>
                <RenderFieldForSchema schema={fieldSchema} path={key} value={formValues[key]} onChange={handleFieldChange}/>
            </div>;
        })}
        <div className="pt-2 border-t border-border">
            <Btn variant="primary" onClick={handleSubmit} loading={loading}>
                {submitLabel}
            </Btn>
        </div>
    </div>;
}

# path: jac-mcp-playground/hooks/useAgentLoop.cl.jac
"""useAgentLoop – thin frontend driver for the byllm-powered backend agent.

Fire-and-stream pattern:

  1. runAgentLoop  → POST /walker/agent_run
                     response is text/event-stream — each line is a JSON event
  2. stream reader  drains the response body in real-time (no polling)
  3. approveToolCall / denyToolCall → POST /function/confirm_tool_call

Every event the backend emits is forwarded directly to addAgentTraceEvent,
so the existing AgentTracePanel renders without any changes to its event
format.  The 'final_response' event drives addChatMessage for chat history.

Special event types added by byllm (visible in the trace view):
  thought        – LLM reasoning text emitted before a tool call
  steps_done     – ReAct loop finished, streamed final answer follows
  response_chunk – one streamed token of the final answer
  usage          – aggregated + per-call token counts
  pending_confirmation – agent waiting for user approval (confirm_mode only)
"""

cl import from "react" { useRef }
cl import from ..store.mcp_store { useMcpStore }
cl import from ..store.llm_store { useLlmStore }


# ── Auth header builder (mirrors useMcpClient) ────────────────────────────────
def _buildAuthHeaders(auth: Any) -> Any {
    h = {};
    if not auth {
        return h;
    }
    if auth.type == "bearer" and auth.value {
        h.Authorization = "Bearer " + auth.value;
    } elif auth.type == "apikey" and auth.value {
        key_name = auth.headerName or "X-API-Key";
        h[key_name] = auth.value;
    } elif auth.type == "basic" and auth.value {
        h.Authorization = "Basic " + auth.value;
    }
    return h;
}

# ── Session history helpers ───────────────────────────────────────────────────
def _buildHistoryEntry(
    cid: str, title: str, msgs: Any, trace: Any, tokenUsage: Any
) -> dict {
    return {
        "id": cid,
        "title": title,
        "createdAt": Date.now(),
        "messages": msgs,
        "trace": trace,
        "tokenUsage": tokenUsage
    };
}

def _prependHistory(hist: list, newEntry: dict, cid: str) -> Any {
    return hist.filter(lambda (s: dict) -> bool { return s.id != cid; }).concat(
        [newEntry]
    ).slice(
        0, 5
    );
}

def _removeFromHistory(hist: list, cid: str) -> Any {
    return hist.filter(lambda (s: dict) -> bool { return s.id != cid; });
}


