# path: jasketch/components/canvas/TextInput.cl.jac
def:pub TextInput(props: dict) -> JsxElement {
    textInput = props.textInput;
    textInputRef = props.textInputRef;
    currentColor = props.currentColor or "#000000";
    currentFontSize = props.currentFontSize or 24;
    currentFontFamily = props.currentFontFamily or "Virgil";
    zoom = props.zoom or 1;
    panOffset = props.panOffset or {"x": 0, "y": 0};
    onTextChange = props.onTextChange;
    onKeyDown = props.onKeyDown;
    onBlur = props.onBlur;

    if not textInput {
        return None;
    }

    # Transform world coordinates to screen coordinates
    screenX = textInput.x * zoom + panOffset.x;
    screenY = textInput.y * zoom + panOffset.y;
    scaledFontSize = currentFontSize * zoom;

    isShapeEdit = textInput.editingShapeId != None and textInput.editingShapeId != undefined;

    baseStyle = {
        "left": screenX + "px",
        "top": screenY + "px",
        "color": currentColor,
        "fontSize": scaledFontSize + "px",
        "fontFamily": currentFontFamily,
        "lineHeight": "1.2",
        "background": "transparent",
        "border": "none",
        "padding": "0",
        "margin": "0",
        "minWidth": "4px",
        "minHeight": scaledFontSize * 1.2 + "px",
        "zIndex": "20",
        "caretColor": currentColor,
        "whiteSpace": "pre",
        "wordBreak": "keep-all"
    };

    if isShapeEdit {
        baseStyle.transform = "translate(-50%, -50%)";
        baseStyle.textAlign = "center";
    }

    return <textarea
        ref={textInputRef}
        value={textInput.text or ""}
        onChange={onTextChange}
        onKeyDown={onKeyDown}
        onBlur={onBlur}
        autoFocus={True}
        className="absolute outline-none resize-none overflow-hidden canvas-text-input"
        style={baseStyle}
    />;
}

# path: jasketch/components/canvas/collaborator_cursors.cl.jac
"""CollaboratorCursors — Render other collaborators' cursors and usernames on the canvas."""

def:pub CollaboratorCursors(cursor_states: dict, zoom: float, pan_x: float, pan_y: float) -> any {
    if not cursor_states {
        return None;
    }

    cursor_sids: list = Object.keys(cursor_states);
    if not cursor_sids or cursor_sids.length == 0 {
        return None;
    }

    return <div className="absolute inset-0 pointer-events-none overflow-hidden z-30">
        {[<div
            key={csid}
            className="absolute flex flex-col items-start"
            style={{
                "left": (cursor_states[csid].x * zoom + pan_x) + "px",
                "top": (cursor_states[csid].y * zoom + pan_y) + "px",
                "transform": "translate(-4px, -4px)"
            }}
        >
            <svg width="14" height="14" viewBox="0 0 14 14">
                <path
                    d="M0 0 L0 14 L4 10 L7 13 L9 12 L6 9 L10 9 Z"
                    fill={cursor_states[csid].color or "#666"}
                    stroke="white"
                    strokeWidth="0.8"
                />
            </svg>
            <div
                className="text-xs font-medium px-1.5 py-0.5 rounded-sm whitespace-nowrap mt-0.5"
                style={{"backgroundColor": cursor_states[csid].color or "#666", "color": "white", "fontSize": "11px"}}
            >
                {cursor_states[csid].username or "Anonymous"}
            </div>
        </div> for csid in Object.keys(cursor_states)]}
    </div>;
}

