# path: jasketch/components/layout/Sidebar.cl.jac
import from "...constants.colors" { PRESET_COLORS }
import from "...constants.fonts" { FONTS, FONT_SIZES }
import from "...constants.tools" { LINE_STYLES, CURVE_STYLES }

def:pub Sidebar(props: dict) -> JsxElement {
    currentTool = props.currentTool or "select";
    currentColor = props.currentColor or "#000000";
    currentStrokeWidth = props.currentStrokeWidth or 2;
    currentOpacity = props.currentOpacity or 1.0;
    currentFontSize = props.currentFontSize or 24;
    currentFontFamily = props.currentFontFamily or "Virgil";
    currentLineStyle = props.currentLineStyle or "solid";
    currentCurveStyle = props.currentCurveStyle or "curved";
    currentFillColor = props.currentFillColor or "transparent";

    selectedElement = props.selectedElement;
    onColorChange = props.onColorChange;
    onStrokeWidthChange = props.onStrokeWidthChange;
    onOpacityChange = props.onOpacityChange;
    onFontSizeChange = props.onFontSizeChange;
    onFontFamilyChange = props.onFontFamilyChange;
    onLineStyleChange = props.onLineStyleChange;
    onCurveStyleChange = props.onCurveStyleChange;
    onFillColorChange = props.onFillColorChange;
    onUpdateElement = props.onUpdateElement;

    presetColors = PRESET_COLORS();
    fontSizes = FONT_SIZES();
    fonts = FONTS();
    lineStyles = LINE_STYLES();
    curveStyles = CURVE_STYLES();

    # Determine if we're editing an existing element or setting defaults for new ones
    hasSelection = selectedElement and selectedElement.element;
    sel = None;
    if hasSelection {
        sel = selectedElement.element;
    }

    # Determine what to show based on selection or tool
    showColor = False;
    showStroke = False;
    showOpacity = False;
    showFont = False;
    showFontSize = False;
    showLineStyle = False;
    showCurveStyle = False;
    showFillColor = False;
    showShapeTextColor = False;

    activeColor = currentColor;
    activeStrokeWidth = currentStrokeWidth;
    activeOpacity = currentOpacity;
    activeFontSize = currentFontSize;
    activeFontFamily = currentFontFamily;
    activeLineStyle = currentLineStyle;
    activeCurveStyle = currentCurveStyle;
    activeFillColor = currentFillColor;
    activeShapeTextColor = currentColor;

    # Track whether selected element is a shape (for font/color handler routing)
    isShapeWithText = False;

    if hasSelection {
        # Editing a selected element - show its properties
        elType = sel.type;
        if elType == "text" {
            showColor = True;
            showOpacity = True;
            showFont = True;
            showFontSize = True;
            activeColor = sel.color;
            activeOpacity = sel.opacity or 1.0;
            activeFontSize = sel.fontSize;
            activeFontFamily = sel.fontFamily;
        } elif elType == "freehand" or elType == "line" or elType == "arrow" or elType == "rectangle" or elType == "circle" or elType == "diamond" {
            showColor = True;
            showStroke = True;
            showOpacity = True;
            if elType != "freehand" {
                showLineStyle = True;
            }
            if elType == "line" or elType == "arrow" {
                showCurveStyle = True;
                selRawCurve = sel.curveStyle or "curved";
                # Map legacy "straight" to "sharp" for display
                activeCurveStyle = (selRawCurve == "straight") and "sharp" or selRawCurve;
            }
            activeColor = sel.color;
            activeStrokeWidth = sel.strokeWidth;
            activeOpacity = sel.opacity or 1.0;
            activeLineStyle = sel.lineStyle or "solid";
            if elType == "rectangle" or elType == "circle" or elType == "diamond" {
                showFillColor = True;
                activeFillColor = sel.fillColor or "transparent";
                # Show text controls if shape has text
                if sel.shapeText {
                    isShapeWithText = True;
                    showFont = True;
                    showFontSize = True;
                    showShapeTextColor = True;
                    activeFontSize = sel.shapeTextFontSize or currentFontSize;
                    activeFontFamily = sel.shapeTextFontFamily or currentFontFamily;
                    activeShapeTextColor = sel.shapeTextColor or sel.color;
                }
            }
        } elif elType == "image" {
            showOpacity = True;
            activeOpacity = sel.opacity or 1.0;
        }
    } else {
        # Setting defaults for new elements based on tool
        if currentTool == "text" {
            showColor = True;
            showOpacity = True;
            showFont = True;
            showFontSize = True;
        } elif currentTool != "select" {
            showColor = True;
            showStroke = True;
            showOpacity = True;
            if currentTool != "freehand" {
                showLineStyle = True;
            }
            if currentTool == "line" or currentTool == "arrow" {
                showCurveStyle = True;
            }
            if currentTool == "rectangle" or currentTool == "circle" or currentTool == "diamond" {
                showFillColor = True;
            }
        }
    }

    # Hide sidebar entirely when nothing to show
    hasContent = showColor or showStroke or showOpacity or showFont or showFontSize or showLineStyle or showCurveStyle or showFillColor or hasSelection;
    if not hasContent {
        return None;
    }

    # Handlers: update element if selected, or update tool defaults
    def handleColorChange(color: str) -> None {
        onColorChange(color);
        if hasSelection {
            onUpdateElement({"color": color});
        }
    }

    def handleStrokeWidthChange(width: int) -> None {
        onStrokeWidthChange(width);
        if hasSelection {
            onUpdateElement({"strokeWidth": width});
        }
    }

    def handleOpacityChange(opacity: float) -> None {
        onOpacityChange(opacity);
        if hasSelection {
            onUpdateElement({"opacity": opacity});
        }
    }

    def handleFontFamilyChange(font: str) -> None {
        onFontFamilyChange(font);
        if hasSelection {
            if isShapeWithText {
                onUpdateElement({"shapeTextFontFamily": font});
            } else {
                onUpdateElement({"fontFamily": font});
            }
        }
    }

    def handleFontSizeChange(size: int) -> None {
        onFontSizeChange(size);
        if hasSelection {
            if isShapeWithText {
                onUpdateElement({"shapeTextFontSize": size});
            } else {
                onUpdateElement({"fontSize": size});
            }
        }
    }

    def handleShapeTextColorChange(color: str) -> None {
        onColorChange(color);
        if hasSelection {
            onUpdateElement({"shapeTextColor": color});
        }
    }

    def handleLineStyleChange(style: str) -> None {
        onLineStyleChange(style);
        if hasSelection {
            onUpdateElement({"lineStyle": style});
        }
    }

    def handleCurveStyleChange(style: str) -> None {
        onCurveStyleChange(style);
        if hasSelection {
            onUpdateElement({"curveStyle": style});
        }
    }

    def handleFillColorChange(color: str) -> None {
        onFillColorChange(color);
        if hasSelection {
            onUpdateElement({"fillColor": color});
        }
    }

    return <div className="sidebar bg-white/95 backdrop-blur-xl rounded-xl shadow-md border border-gray-200/60 w-[200px] py-2.5 px-2.5 flex flex-col gap-2.5 animate-slide-in overflow-y-auto max-h-[calc(100vh-140px)]">

        {hasSelection and <div className="flex items-center gap-2 pb-1">
            <div className="w-2 h-2 rounded-full bg-orange-500"></div>
            <span className="text-[10px] font-semibold text-orange-600 uppercase tracking-wider">{sel.type + " selected"}</span>
        </div> or None}

        {showColor and <div>
            <span className="sidebar-label">Stroke</span>
            <div className="grid grid-cols-5 gap-1.5 mt-1.5">
                {[
                    <button
                        key={color}
                        onClick={lambda -> None { handleColorChange(color); }}
                        title={color}
                        className={"w-7 h-7 rounded-full transition-all duration-150 border border-gray-200/60 " + (activeColor == color and "ring-2 ring-orange-500 ring-offset-1 scale-110" or "hover:scale-110")}
                        style={{"backgroundColor": color}}
                    />
                    for color in presetColors
                ]}
            </div>
            <input
                type="color"
                value={activeColor}
                onChange={lambda e: any -> None { handleColorChange(e.target.value); }}
                title="Custom color"
                className="color-input w-full h-7 rounded-md cursor-pointer border border-gray-200 p-0 mt-1.5"
            />
        </div> or None}

        {showColor and <div className="h-px bg-gray-100"></div> or None}

        {showFillColor and <div>
            <span className="sidebar-label">Fill</span>
            <div className="flex items-center gap-1.5 mt-1.5">
