                    />
                </div>
            </div>
        </div> or None}

        {showFillColor and <div className="h-px bg-gray-100"></div> or None}

        {showShapeTextColor and <div>
            <span className="sidebar-label">Text Color</span>
            <div className="grid grid-cols-5 gap-1.5 mt-1.5">
                {[
                    <button
