# path: jasketch/hooks/useCanvas.cl.jac
import from react { useRef }
import from "..services.canvas" { drawElement, applyViewportTransform, drawSelectionBox, drawGroupSelectionBox, drawBoxSelectionRect }
import from "..constants.canvas" { CANVAS_DEFAULTS }

def:pub useCanvas() -> dict {
    canvasRef = useRef(None);
    containerRef = useRef(None);
    canvasDefaults = CANVAS_DEFAULTS();
    has canvasSize: dict = {
        "width": canvasDefaults.width,
        "height": canvasDefaults.height
    };

    def updateCanvasSize(val: dict) -> None {
        canvasSize = val;
    }

    def redrawCanvas(elements: list, zoom: float, panOffset: dict, selectedElement: any = None, selectedElements: list = [], isBoxSelecting: bool = False, boxStart: any = None, boxEnd: any = None, editingShapeId: any = None) -> None {
        canvas = canvasRef.current;
        if not canvas {
            return;
        }

        ctx = canvas.getContext("2d");

        # HiDPI fix: scale canvas for sharp rendering
        dpr = window.devicePixelRatio or 1;
        canvas.width = Math.round(canvasSize.width * dpr);
        canvas.height = Math.round(canvasSize.height * dpr);
        ctx.scale(dpr, dpr);

        ctx.save();
        applyViewportTransform(ctx, zoom, panOffset);

        # Callback to redraw canvas when an image finishes loading
        imgLoadRedraw = lambda -> None {
            redrawCanvas(elements, zoom, panOffset, selectedElement, selectedElements, isBoxSelecting, boxStart, boxEnd, editingShapeId);
        };

        drIdx = 0;
        while drIdx < elements.length {
            drEl = elements[drIdx];
            if editingShapeId != None and editingShapeId != undefined and drEl.id == editingShapeId and drEl.shapeText {
                # Temporarily hide shapeText while editing this shape
                drCopy = Object.assign({}, drEl);
                drCopy.shapeText = None;
                drawElement(ctx, drCopy, imgLoadRedraw);
            } else {
                drawElement(ctx, drEl, imgLoadRedraw);
            }
            drIdx = drIdx + 1;
        }

        if selectedElement and selectedElement.element {
            drawSelectionBox(ctx, selectedElement.element);
        }

        if selectedElements and selectedElements.length > 0 {
            # Check if all selected elements share the same groupId
            allGrouped = True;
            sharedGroupId = None;
            if selectedElements[0].element and selectedElements[0].element.groupId {
                sharedGroupId = selectedElements[0].element.groupId;
            } else {
                allGrouped = False;
            }
            if allGrouped {
                gci = 1;
                while gci < selectedElements.length {
                    if not selectedElements[gci].element or selectedElements[gci].element.groupId != sharedGroupId {
                        allGrouped = False;
                    }
                    gci = gci + 1;
                }
            }
            if allGrouped and sharedGroupId {
                # Draw single combined selection box for group
                groupEls = [];
                gei = 0;
                while gei < selectedElements.length {
                    if selectedElements[gei].element {
                        groupEls.push(selectedElements[gei].element);
                    }
                    gei = gei + 1;
                }
                drawGroupSelectionBox(ctx, groupEls);
            } else {
                # Draw individual selection boxes
                selBoxIdx = 0;
                while selBoxIdx < selectedElements.length {
                    if selectedElements[selBoxIdx].element {
                        drawSelectionBox(ctx, selectedElements[selBoxIdx].element);
                    }
                    selBoxIdx = selBoxIdx + 1;
                }
            }
        }

        if isBoxSelecting and boxStart and boxEnd {
            drawBoxSelectionRect(ctx, boxStart, boxEnd);
        }

        ctx.restore();
    }

    def initializeCanvas() -> None {
        if containerRef.current {
            rect = containerRef.current.getBoundingClientRect();
            canvasSize = {
                "width": Math.round(rect.width),
                "height": Math.round(rect.height)
            };
        }
    }

    can with entry {
        def handleResize() -> None {
            initializeCanvas();
        }

        handleResize();
        window.addEventListener("resize", handleResize);
        return lambda -> None {
            window.removeEventListener("resize", handleResize);
        };
    }

    return {
        "canvasRef": canvasRef,
        "containerRef": containerRef,
        "canvasSize": canvasSize,
        "setCanvasSize": updateCanvasSize,
        "redrawCanvas": redrawCanvas,
        "initializeCanvas": initializeCanvas
    };
}

# path: jasketch/hooks/useChatSocket.cl.jac
import from react { useRef }

def:pub useChatSocket() -> dict {
    has messages: list = [];
    has isLoading: bool = False;
    has isConnected: bool = False;
    has pendingConfirm: dict = {};
    has currentPhase: str = "";

    wsRef = useRef(None);
    connectedRef = useRef(False);
    reconnectTimerRef = useRef(None);
    messageIdRef = useRef(0);
    messagesRef = useRef([]);
    loadingRef = useRef(False);
    currentAssistantRef = useRef("");
    pendingConfirmRef = useRef({});

    messagesRef.current = messages;
    loadingRef.current = isLoading;
    pendingConfirmRef.current = pendingConfirm;

    def nextId() -> int {
        messageIdRef.current = messageIdRef.current + 1;
        return messageIdRef.current;
    }

    def getChatUrl() -> str {
        host = window.location.hostname;
        protocol = window.location.protocol;
        if host == "localhost" or host == "127.0.0.1" {
            return "ws://" + host + ":9602";
        }
        wsProtocol = "ws:";
        if protocol == "https:" {
            wsProtocol = "wss:";
        }
        return wsProtocol + "//" + host + "/chat-ws";
    }

    def handleWsMessage(event: any) -> None {
        data = JSON.parse(event.data);

        if data.type == "confirm" {
            pendingConfirm = {"confirmId": data.confirmId or "", "message": data.message or ""};
            pendingConfirmRef.current = pendingConfirm;
        } elif data.type == "message" {
            msgContent = data["content"] or "";
            messagesRef.current = messagesRef.current.concat([{"id": nextId(), "role": "assistant", "content": msgContent}]);
            messages = messagesRef.current;
        } elif data.type == "done" {
            loadingRef.current = False;
            isLoading = False;
            currentAssistantRef.current = "";
            currentPhase = "";
        } elif data.type == "error" {
            messagesRef.current = messagesRef.current.concat([{"id": nextId(), "role": "error", "content": data.message or "Unknown error"}]);
            messages = messagesRef.current;
            loadingRef.current = False;
            isLoading = False;
            currentAssistantRef.current = "";
            currentPhase = "";
        } elif data.type == "agent_start" {
            currentPhase = data.agent or "";
        } elif data.type == "agent_done" {
            currentPhase = "";
        }
    }

    def connect() -> None {
        url = getChatUrl();
        ws = Reflect.construct(WebSocket, [url]);

        ws.onopen = lambda -> None {
            connectedRef.current = True;
            isConnected = True;
        };

        ws.onmessage = lambda event: any -> None {
            handleWsMessage(event);
        };

        ws.onclose = lambda -> None {
            connectedRef.current = False;
            isConnected = False;
            wsRef.current = None;
            reconnectTimerRef.current = setTimeout(lambda -> None {
                connect();
            }, 3000);
        };

        ws.onerror = lambda -> None {
            x = 0;
        };

        wsRef.current = ws;
    }

    def getSessionId() -> Any {
        # Same key as useWebSocket — both hooks read the same stable per-tab ID
        key = "jasketch_session_id";
        sid = sessionStorage.getItem(key);
        if not sid {
            sid = crypto.randomUUID();
            sessionStorage.setItem(key, sid);
        }
        return sid;
    }

    def sendMessage(apiKey: str, model: str, message: str) -> None {
        if not wsRef.current or not connectedRef.current {
            return;
        }

        history = [];
        for m in messagesRef.current {
            if m.role == "user" or m.role == "assistant" {
                history.push({"role": m.role, "content": m.content});
            }
        }

        messagesRef.current = messagesRef.current.concat([{"id": nextId(), "role": "user", "content": message}]);
        messages = messagesRef.current;
        loadingRef.current = True;
        isLoading = True;
        currentAssistantRef.current = "";

        wsRef.current.send(JSON.stringify({
            "type": "chat",
            "apiKey": apiKey,
            "model": model,
            "message": message,
            "history": history,
            "sessionId": getSessionId()
        }));
    }

    def clearMessages() -> None {
        messagesRef.current = [];
        messages = [];
        currentAssistantRef.current = "";
        messageIdRef.current = 0;
    }

    def respondConfirm(result: str) -> None {
        cid = pendingConfirmRef.current.confirmId or "";
        if wsRef.current and connectedRef.current and cid {
            wsRef.current.send(JSON.stringify({
                "type": "confirm_response",
                "confirmId": cid,
                "result": result
            }));
        }
        pendingConfirm = {};
        pendingConfirmRef.current = {};
    }

    can with entry {
        connect();

        return lambda -> None {
            if reconnectTimerRef.current {
                clearTimeout(reconnectTimerRef.current);
            }
            if wsRef.current {
                wsRef.current.close();
            }
        };
    }

    return {
        "messages": messages,
        "isLoading": isLoading,
        "isConnected": isConnected,
        "sendMessage": sendMessage,
        "clearMessages": clearMessages,
        "pendingConfirm": pendingConfirm,
        "respondConfirm": respondConfirm,
        "currentPhase": currentPhase
    };
}

