# path: jasketch/hooks/useElements.cl.jac
import from react { useRef }

def:pub useElements() -> dict {
    has elements: list = [];
    historyRef = useRef([]);
    historyIndexRef = useRef(-1);
    loadedRef = useRef(False);
    elementsRef = useRef([]);

    STORAGE_KEY = "jasketch_elements";

    def setElementsInternal(newElements: list) -> None {
        elements = newElements;
        elementsRef.current = newElements;
        # Strip non-serializable imageObj before saving to localStorage
        toStore = [
            el.type == "image" and el.imageObj and {
                "type": el.type, "x": el.x, "y": el.y,
                "width": el.width, "height": el.height,
                "src": el.src, "opacity": el.opacity, "groupId": el.groupId
            } or el
            for el in newElements
        ];
        localStorage.setItem(STORAGE_KEY, JSON.stringify(toStore));
    }

    # Load from localStorage on mount
    can with entry {
        stored = localStorage.getItem(STORAGE_KEY);
        if stored {
            parsed = JSON.parse(stored);
            if parsed and parsed.length > 0 {
                mi = 0;
                while mi < parsed.length {
                    if not parsed[mi].id {
                        parsed[mi].id = crypto.randomUUID();
                    }
                    mi = mi + 1;
                }
                elements = parsed;
                elementsRef.current = parsed;
                pushHistory(parsed);
            }
        }
        loadedRef.current = True;
    }

    def pushHistory(newElements: list) -> None {
        history = historyRef.current;
        idx = historyIndexRef.current;
        newHistory = history.slice(0, idx + 1);
        newHistory.push(newElements);
        if newHistory.length > 50 {
            newHistory = newHistory.slice(newHistory.length - 50);
        }
        historyRef.current = newHistory;
        historyIndexRef.current = newHistory.length - 1;
    }

    def setElementsWithHistory(newElements: list) -> None {
        pushHistory(newElements);
        setElementsInternal(newElements);
    }

    def addElement(element: dict) -> None {
        if not element.id {
            element.id = crypto.randomUUID();
        }
        newElements = elements.concat([element]);
        setElementsWithHistory(newElements);
    }

    def addMultipleElements(newItems: list) -> None {
        ni = 0;
        while ni < newItems.length {
            if not newItems[ni].id {
                newItems[ni].id = crypto.randomUUID();
            }
            ni = ni + 1;
        }
        newElements = elements.concat(newItems);
        setElementsWithHistory(newElements);
    }

    def _findIndex(id: str) -> int {
        fi = 0;
        while fi < elements.length {
            if elements[fi] and elements[fi].id == id {
                return fi;
            }
            fi = fi + 1;
        }
        return -1;
    }

    def updateElement(id: str, newElement: dict) -> None {
        idx = _findIndex(id);
        if idx >= 0 {
            newElements = elements.slice();
            newElements[idx] = newElement;
            setElementsWithHistory(newElements);
        }
    }

    def updateElementSilent(id: str, newElement: dict) -> None {
        idx = _findIndex(id);
        if idx >= 0 {
            newElements = elements.slice();
            newElements[idx] = newElement;
            setElementsInternal(newElements);
        }
    }

    def updateMultipleElements(updates: list) -> None {
        newElements = elements.slice();
        i = 0;
        while i < updates.length {
            idx = _findIndex(updates[i].id);
            if idx >= 0 {
                newElements[idx] = updates[i].element;
            }
            i = i + 1;
        }
        setElementsWithHistory(newElements);
    }

    def updateMultipleElementsSilent(updates: list) -> None {
        newElements = elements.slice();
        i = 0;
        while i < updates.length {
            idx = _findIndex(updates[i].id);
            if idx >= 0 {
                newElements[idx] = updates[i].element;
            }
            i = i + 1;
        }
        setElementsInternal(newElements);
    }

    def commitToHistory() -> None {
        pushHistory(elements);
    }

    def removeElement(id: str) -> None {
        newElements = [];
        ri = 0;
        while ri < elements.length {
            if elements[ri] and elements[ri].id != id {
                newElements.push(elements[ri]);
            }
            ri = ri + 1;
        }
        setElementsWithHistory(newElements);
    }

    def removeMultipleElements(ids: list) -> None {
        idSet = {};
        i = 0;
        while i < ids.length {
            idSet[ids[i]] = True;
            i = i + 1;
        }
        newElements = [];
        rmi = 0;
        while rmi < elements.length {
            if elements[rmi] and not idSet[elements[rmi].id] {
                newElements.push(elements[rmi]);
            }
            rmi = rmi + 1;
        }
        setElementsWithHistory(newElements);
    }

    def clearElements() -> None {
        setElementsWithHistory([]);
    }

    def setElementsReplaceAll(newElements: list) -> None {
        # Add IDs to any elements missing them
        i = 0;
        while i < newElements.length {
            if not newElements[i].id {
                newElements[i].id = crypto.randomUUID();
            }
            i = i + 1;
        }
        # Replace all elements and push to history
        setElementsWithHistory(newElements);
    }

    def undo() -> None {
        idx = historyIndexRef.current;
        if idx > 0 {
            historyIndexRef.current = idx - 1;
            setElementsInternal(historyRef.current[idx - 1]);
        } elif idx == 0 {
            historyIndexRef.current = -1;
            setElementsInternal([]);
        }
    }

    def redo() -> None {
        idx = historyIndexRef.current;
        history = historyRef.current;
        if idx < history.length - 1 {
            historyIndexRef.current = idx + 1;
            setElementsInternal(history[idx + 1]);
        }
    }

    return {
        "elements": elements,
        "elementsRef": elementsRef,
        "setElements": setElementsWithHistory,
        "addElement": addElement,
        "addMultipleElements": addMultipleElements,
        "updateElement": updateElement,
        "updateElementSilent": updateElementSilent,
        "updateMultipleElements": updateMultipleElements,
        "updateMultipleElementsSilent": updateMultipleElementsSilent,
        "commitToHistory": commitToHistory,
        "removeElement": removeElement,
        "removeMultipleElements": removeMultipleElements,
        "clearElements": clearElements,
        "setElementsReplaceAll": setElementsReplaceAll,
        "undo": undo,
        "redo": redo
    };
}

# path: jasketch/hooks/useSelection.cl.jac
import from "..services.collision" { isPointInElement }

def:pub useSelection() -> dict {
    has selectedElement: any = None;
    has selectedElements: list = [];
    has isDragging: bool = False;
    has dragOffset: dict = {"x": 0, "y": 0};
    has dragStartPos: any = None;
    has isBoxSelecting: bool = False;
    has boxStart: any = None;
    has boxEnd: any = None;
    has isResizing: bool = False;
    has resizeHandle: any = None;
    has resizeStartElement: any = None;

    def updateSelectedElement(val: any) -> None {
        selectedElement = val;
    }

    def updateSelectedElements(val: list) -> None {
        selectedElements = val;
    }

    def updateIsDragging(val: bool) -> None {
        isDragging = val;
    }

    def updateDragStartPos(val: any) -> None {
        dragStartPos = val;
    }

    def updateIsResizing(val: bool) -> None {
        isResizing = val;
    }

    def updateResizeHandle(val: any) -> None {
        resizeHandle = val;
    }

    def updateResizeStartElement(val: any) -> None {
        resizeStartElement = val;
    }

    def findElementAtPoint(point: dict, elems: list) -> dict {
        i = elems.length - 1;
        while i >= 0 {
            if isPointInElement(point, elems[i]) {
                return {"element": elems[i], "id": elems[i].id};
            }
            i = i - 1;
        }
        return None;
    }

    def startDragging(elementInfo: dict, mousePos: dict) -> None {
        selectedElement = elementInfo;
        selectedElements = [];
        isDragging = True;
        dragStartPos = mousePos;

        element = elementInfo.element;

        elementX = 0;
        elementY = 0;

        if element.type == "freehand" and element.points and element.points.length > 0 {
            elementX = element.points[0].x;
            elementY = element.points[0].y;
        } elif element.type == "line" or element.type == "arrow" {
            elementX = element.x1;
            elementY = element.y1;
        } else {
            elementX = element.x;
            elementY = element.y;
        }

        offsetX = mousePos.x - elementX;
        offsetY = mousePos.y - elementY;

        dragOffset = {"x": offsetX, "y": offsetY};
    }

    def stopDragging() -> None {
        isDragging = False;
    }

    def stopResizing() -> None {
        isResizing = False;
        resizeHandle = None;
        resizeStartElement = None;
    }

    def clearSelection() -> None {
        selectedElement = None;
        selectedElements = [];
        isDragging = False;
        stopResizing();
    }

    def removeFromSelection(id: str) -> None {
        newList = [sel for sel in selectedElements if sel.id != id];
        selectedElements = newList;
        if newList.length == 1 {
            selectedElement = newList[0];
        } elif newList.length == 0 {
            selectedElement = None;
        }
    }

    def startBoxSelection(point: dict) -> None {
        isBoxSelecting = True;
        boxStart = point;
        boxEnd = point;
    }

    def updateBoxSelection(point: dict) -> None {
        boxEnd = point;
    }

    def finishBoxSelection(elems: list) -> None {
        if boxStart and boxEnd {
            minX = Math.min(boxStart.x, boxEnd.x);
            minY = Math.min(boxStart.y, boxEnd.y);
            maxX = Math.max(boxStart.x, boxEnd.x);
            maxY = Math.max(boxStart.y, boxEnd.y);

            selected = [];
            i = 0;
            while i < elems.length {
                element = elems[i];
                if isElementInBox(element, minX, minY, maxX, maxY) {
                    selected.push({"element": element, "id": element.id});
                }
                i = i + 1;
            }

            selectedElements = selected;
            if selected.length == 1 {
                selectedElement = selected[0];
            } else {
                selectedElement = None;
            }
        }

        isBoxSelecting = False;
        boxStart = None;
        boxEnd = None;
    }

    def isElementInBox(element: dict, boxMinX: float, boxMinY: float, boxMaxX: float, boxMaxY: float) -> bool {
        # Check if element's bounding box overlaps with selection box
        if element.type == "text" or element.type == "rectangle" or element.type == "circle" or element.type == "diamond" or element.type == "image" {
            shL = Math.min(element.x, element.x + (element.width or 0));
            shR = Math.max(element.x, element.x + (element.width or 0));
            shT = Math.min(element.y, element.y + (element.height or 0));
            shB = Math.max(element.y, element.y + (element.height or 0));
            return shL <= boxMaxX and shR >= boxMinX and shT <= boxMaxY and shB >= boxMinY;
        } elif element.type == "line" or element.type == "arrow" {
            lnL = Math.min(element.x1, element.x2);
            lnR = Math.max(element.x1, element.x2);
            lnT = Math.min(element.y1, element.y2);
            lnB = Math.max(element.y1, element.y2);
            return lnL <= boxMaxX and lnR >= boxMinX and lnT <= boxMaxY and lnB >= boxMinY;
        } elif element.type == "freehand" {
            if not element.points or element.points.length == 0 {
                return False;
            }
            fhL = element.points[0].x;
            fhR = element.points[0].x;
            fhT = element.points[0].y;
            fhB = element.points[0].y;
            fi = 1;
            while fi < element.points.length {
                pt = element.points[fi];
                if pt.x < fhL { fhL = pt.x; }
                if pt.x > fhR { fhR = pt.x; }
                if pt.y < fhT { fhT = pt.y; }
                if pt.y > fhB { fhB = pt.y; }
                fi = fi + 1;
            }
            return fhL <= boxMaxX and fhR >= boxMinX and fhT <= boxMaxY and fhB >= boxMinY;
        }
        return False;
    }

    return {
        "selectedElement": selectedElement,
        "selectedElements": selectedElements,
        "isDragging": isDragging,
        "dragOffset": dragOffset,
        "dragStartPos": dragStartPos,
        "isBoxSelecting": isBoxSelecting,
        "boxStart": boxStart,
        "boxEnd": boxEnd,
        "isResizing": isResizing,
        "resizeHandle": resizeHandle,
        "resizeStartElement": resizeStartElement,
        "setSelectedElement": updateSelectedElement,
        "setSelectedElements": updateSelectedElements,
        "setIsDragging": updateIsDragging,
        "setDragStartPos": updateDragStartPos,
        "setIsResizing": updateIsResizing,
        "setResizeHandle": updateResizeHandle,
        "setResizeStartElement": updateResizeStartElement,
        "findElementAtPoint": findElementAtPoint,
        "startDragging": startDragging,
        "stopDragging": stopDragging,
        "stopResizing": stopResizing,
        "clearSelection": clearSelection,
        "removeFromSelection": removeFromSelection,
        "startBoxSelection": startBoxSelection,
        "updateBoxSelection": updateBoxSelection,
        "finishBoxSelection": finishBoxSelection
    };
}

