                        </span>
                        <button
                            onClick={lambda -> None { isExpanded = false; }}
                            className="p-1 rounded-full hover:bg-background transition-colors"
                            aria-label="Collapse"
                        >
                            <X className="w-4 h-4 text-text-secondary" />
                        </button>
                    </div>

                    <div className="grid grid-cols-3 gap-2">
                        <button
                            onClick={onPlay}
                            disabled={isRunning}
                            className="flex flex-col items-center gap-1 p-2 rounded-lg bg-primary/10 hover:bg-primary/20 transition-colors disabled:opacity-50"
                            aria-label="Continue"
                        >
                            <Play className="w-5 h-5 text-primary" />
                            <span className="text-[10px] text-primary font-medium">Continue</span>
                        </button>

                        <button
                            onClick={onStepOver}
                            className="flex flex-col items-center gap-1 p-2 rounded-lg bg-background hover:bg-surface-hover transition-colors"
                            aria-label="Step Over"
                        >
                            <StepForward className="w-5 h-5 text-text-secondary" />
                            <span className="text-[10px] text-text-secondary font-medium">Over</span>
                        </button>

                        <button
                            onClick={onStepIn}
                            className="flex flex-col items-center gap-1 p-2 rounded-lg bg-background hover:bg-surface-hover transition-colors"
                            aria-label="Step Into"
                        >
                            <StepBack className="w-5 h-5 text-text-secondary" />
                            <span className="text-[10px] text-text-secondary font-medium">Into</span>
                        </button>

                        <button
                            onClick={onStepOut}
                            className="flex flex-col items-center gap-1 p-2 rounded-lg bg-background hover:bg-surface-hover transition-colors"
                            aria-label="Step Out"
                        >
                            <ArrowUp className="w-5 h-5 text-text-secondary" />
                            <span className="text-[10px] text-text-secondary font-medium">Out</span>
                        </button>

                        <button
                            onClick={onRestart}
                            className="flex flex-col items-center gap-1 p-2 rounded-lg bg-warning/10 hover:bg-warning/20 transition-colors"
                            aria-label="Restart"
                        >
                            <RotateCw className="w-5 h-5 text-warning" />
                            <span className="text-[10px] text-warning font-medium">Restart</span>
                        </button>

                        <button
                            onClick={onStop}
                            className="flex flex-col items-center gap-1 p-2 rounded-lg bg-error/10 hover:bg-error/20 transition-colors"
                            aria-label="Stop"
                        >
                            <Square className="w-5 h-5 text-error" />
                            <span className="text-[10px] text-error font-medium">Stop</span>
                        </button>
                    </div>

                    <button
                        onClick={onToggleDebug}
                        className="w-full py-2 text-xs text-text-secondary hover:text-text-primary transition-colors"
                    >
                        Exit Debug Mode
                    </button>
                </div>
            )}

            {(not isExpanded) and (
                <button
                    onClick={lambda -> None { isExpanded = true; }}
                    className="w-10 h-10 rounded-xl bg-warning/20 flex items-center justify-center"
                    aria-label="Expand Debug Controls"
                >
                    <Bug className="w-5 h-5 text-warning" />
                </button>
            )}
        </div>
    );
}

# path: jac-client-playground/jac_playground/components/Mobile/MobileFAB.cl.jac
import from "lucide-react" { Play, ArrowRightLeft, Loader2 }
import from "...lib.utils" { cn }

def: pub MobileFAB(props: dict) -> JsxElement {
    mode = props.mode or "jac";
    activePanel = props.activePanel or "code";
    onRun = props.onRun;
    onConvert = props.onConvert;
    isRunning = props.isRunning or false;
    isConverting = props.isConverting or false;
    envReady = props.envReady or false;

    # Only show FAB on code panel or mode panel (where actions are needed)
    shouldShow = activePanel == "code" or activePanel == "mode";
    if not shouldShow {
        return None;
    }

    isJacMode = mode == "jac";
    isConversionMode = mode == "jac2py" or mode == "py2jac";
    isLoading = isRunning or isConverting;
    isDisabled = isLoading or not envReady;

    def handlePress() -> None {
        if isDisabled {
            return None;
        }
        if isJacMode and onRun {
            onRun();
        } elif isConversionMode and onConvert {
            onConvert();
        }
    }

    Icon = isJacMode and Play or ArrowRightLeft;
    label = isJacMode and "Run Code" or "Convert";

    return (
        <button
            onClick={handlePress}
            disabled={isDisabled}
            className={cn(
                "fixed bottom-20 right-4 w-14 h-14 rounded-full shadow-lg",
                "flex items-center justify-center z-[1000]",
                "transition-all duration-200 active:scale-95",
                (not envReady) and "bg-border cursor-not-allowed opacity-50"
                    or (isLoading and "bg-primary/70 cursor-wait" or "bg-primary hover:bg-primary/90"),
                "focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2"
            )}
            aria-label={envReady and label or "Environment loading..."}
            aria-pressed={isLoading}
        >
            {isLoading and (
                <Loader2 className="w-6 h-6 text-primary-foreground animate-spin" />
            )}
            {(not isLoading) and (
                <Icon className={cn("w-6 h-6", (not envReady) and "text-text-secondary" or "text-primary-foreground")} />
            )}
        </button>
    );
}

