# path: jac-client-playground/jac_playground/components/Mobile/MobileModeSwitcher.cl.jac
import from "lucide-react" { Code2, Braces, FileCode, ChevronDown, X, Check }
import from "...lib.utils" { cn }

def: pub MobileModeSwitcher(props: dict) -> JsxElement {
    mode = props.mode or "jac";
    onModeChange = props.onModeChange;
    className = props.className or "";

    has isOpen: bool = false;

    modes = [
        { "id": "jac", "icon": Code2, "label": "Jac", "shortLabel": "Jac" },
        { "id": "jac2py", "icon": Braces, "label": "Jac → Python", "shortLabel": "jac2py" },
        { "id": "py2jac", "icon": FileCode, "label": "Python → Jac", "shortLabel": "py2jac" }
    ];

    currentMode = modes.find(lambda m: dict -> bool { return m["id"] == mode; });
    CurrentIcon = currentMode and currentMode["icon"] or Code2;

    def handleModeSelect(modeId: str) -> None {
        if onModeChange {
            onModeChange(modeId);
        }
        isOpen = false;
    }

    return (
        <div className={cn("relative", className)}>
            <button
                onClick={lambda -> None { isOpen = not isOpen; }}
                className={cn(
                    "flex items-center gap-1.5 px-2.5 py-1.5 rounded-full",
                    "bg-primary/10 border border-primary/20",
                    "text-primary text-xs font-medium",
                    "transition-all active:scale-95"
                )}
                aria-label="Switch mode"
                aria-expanded={isOpen}
            >
                <CurrentIcon className="w-3.5 h-3.5" />
                <span>{currentMode and currentMode["shortLabel"] or "Jac"}</span>
                <ChevronDown className={cn(
                    "w-3 h-3 transition-transform",
                    isOpen and "rotate-180"
                )} />
            </button>

            {isOpen and (
                <>
                    <div 
                        className="fixed inset-0 z-[100]" 
                        onClick={lambda -> None { isOpen = false; }}
                    />

                    <div className="absolute top-full right-0 mt-2 z-[101] w-48 bg-surface border border-border rounded-xl shadow-xl overflow-hidden">
                        <div className="p-2 border-b border-border bg-surface-hover">
                            <span className="text-[10px] font-semibold text-text-secondary uppercase tracking-wider">
                                Switch Mode
                            </span>
                        </div>

                        {modes.map(lambda modeItem: dict -> any {
                            Icon = modeItem["icon"];
                            isActive = mode == modeItem["id"];

                            return (
                                <button
                                    key={modeItem["id"]}
                                    onClick={lambda -> None { handleModeSelect(modeItem["id"]); }}
                                    className={cn(
                                        "w-full flex items-center gap-3 px-3 py-2.5 transition-colors",
                                        isActive and "bg-primary/10 text-primary" or "hover:bg-surface-hover text-text-primary"
                                    )}
                                >
                                    <Icon className="w-4 h-4" />
                                    <span className="text-sm font-medium flex-1 text-left">
                                        {modeItem["label"]}
                                    </span>
                                    {isActive and (
                                        <Check className="w-4 h-4 text-primary" />
                                    )}
                                </button>
                            );
                        })}
                    </div>
                </>
            )}
        </div>
    );
}

# path: jac-client-playground/jac_playground/components/Mobile/MobilePanelRouter.cl.jac
import from ".MobilePanels.CodePanel" { CodePanel }
import from ".MobilePanels.GraphPanel" { GraphPanel }
import from ".MobilePanels.OutputPanel" { OutputPanel }
import from ".MobilePanels.ExamplesPanel" { ExamplesPanel }

def: pub MobilePanelRouter(props: dict) -> JsxElement {
    activePanel = props.activePanel or "code";
    mode = props.mode or "jac";
    editorTheme = props.editorTheme or "vs-light";
    isDarkMode = props.isDarkMode or false;

    # Code panel props
    codeValue = props.codeValue or "";
    onCodeChange = props.onCodeChange;
    outputCode = props.outputCode or "";
    onRun = props.onRun;
    isRunning = props.isRunning or false;
    envReady = props.envReady or false;

    # Graph panel props
    graphData = props.graphData;

    # Output panel props
    output = props.output or "";
    errors = props.errors or "";
    logs = props.logs or "";
    onClearOutput = props.onClearOutput;
    onClearErrors = props.onClearErrors;
    onClearLogs = props.onClearLogs;

    # Examples panel props
    examples = props.examples or [];
    onSelectExample = props.onSelectExample;

    # Render only the active panel for performance
    if activePanel == "code" {
        return (
            <CodePanel
                mode={mode}
                value={codeValue}
                onChange={onCodeChange}
                outputValue={outputCode}
                onRun={onRun}
                isRunning={isRunning}
                editorTheme={editorTheme}
                envReady={envReady}
            />
        );
    }

    if activePanel == "graph" {
        return (
            <GraphPanel graphData={graphData} isDarkMode={isDarkMode} />
        );
    }

    if activePanel == "output" {
        return (
            <OutputPanel
                output={output}
                errors={errors}
                logs={logs}
                onClearOutput={onClearOutput}
                onClearErrors={onClearErrors}
                onClearLogs={onClearLogs}
            />
        );
    }

    if activePanel == "examples" {
        return (
            <ExamplesPanel
                examples={examples}
                onSelectExample={onSelectExample}
            />
        );
    }

    return None;
}

