                "background": "#3b82f6",
                "border": isDarkMode and "#4b5563" or "#374151",
                "highlight": {
                    "background": "#f59e0b",
                    "border": "#f59e0b"
                }
            }
        },
        "edges": {
            "width": 2,
            "color": {
                "color": isDarkMode and "#9ca3af" or "#6b7280",
                "opacity": 0.8
            },
            "smooth": {
                "type": "continuous",
                "forceDirection": "none"
            },
            "arrows": {
                "to": {
                    "enabled": true,
                    "scaleFactor": 0.5
                }
            },
            "font": {
                "size": 12,
                "align": "top",
                "color": isDarkMode and "#e5e7eb" or "#374151",
                "strokeWidth": isDarkMode and 2 or 0,
                "strokeColor": isDarkMode and "#1f2937" or "#ffffff"
            }
        },
        "physics": {
            "enabled": true,
            "solver": "forceAtlas2Based",
            "forceAtlas2Based": {
                "gravitationalConstant": -50,
                "centralGravity": 0.01,
                "springLength": 120,
                "springConstant": 0.08,
                "damping": 0.4,
