# useAudioControls Hook
# Custom hook for managing audio, microphone, and push-to-talk controls
import from react { useRef }

def:pub useAudioControls(sessionRef: any, sessionStatus: str) -> dict {
    # Audio element ref
    audioElementRef = useRef(None);

    # Reactive state using has variables
    has isPTTActive: bool = False;
    has isPTTUserSpeaking: bool = False;
    has isAudioPlaybackEnabled: bool = True;
    has isMicMuted: bool = False;

    # Toggle mic mute state
    def toggleMicMute() -> None {
        isMicMuted = not isMicMuted;
    }

    # Push-to-Talk: Button down handler
    def handleTalkButtonDown() -> None {
        if sessionStatus != "CONNECTED" {
            return;
        }
        isPTTUserSpeaking = True;

        if sessionRef.current {
            try {
                sessionRef.current.interrupt();
            } except Exception as e {
                console.error("PTT error:", e);
            }
        }
    }

    # Push-to-Talk: Button up handler
    def handleTalkButtonUp() -> None {
        if sessionStatus != "CONNECTED" or not isPTTUserSpeaking {
            return;
        }
        isPTTUserSpeaking = False;
    }

    # Reset PTT state (called on disconnect)
    def resetPTTState() -> None {
        isPTTUserSpeaking = False;
    }

    # Setter wrapper functions for parent components
    def updatePTTActive(value: bool) -> None {
        isPTTActive = value;
    }

    def updateAudioPlaybackEnabled(value: bool) -> None {
        isAudioPlaybackEnabled = value;
    }

    # Create audio element on mount - using new can with entry syntax
    can with entry {
        el = document.createElement('audio');
        el.autoplay = True;
        el.style.display = 'none';
        document.body.appendChild(el);
        audioElementRef.current = el;
    }

    # Handle mic mute/unmute - using new can with (deps) entry syntax
    can with (isMicMuted, sessionStatus) entry {
        if sessionRef.current {
            try {
                sessionRef.current.mute(isMicMuted);
            } except Exception as e {
                console.error("Error toggling mic:", e);
            }
        }
    }

    # Audio playback toggle - using new can with [dep] entry syntax
    can with [isAudioPlaybackEnabled] entry {
        if audioElementRef.current {
            audioElementRef.current.muted = not isAudioPlaybackEnabled;
        }
    }

    return {
        # State
        "isPTTActive": isPTTActive,
        "setIsPTTActive": updatePTTActive,
        "isPTTUserSpeaking": isPTTUserSpeaking,
        "isAudioPlaybackEnabled": isAudioPlaybackEnabled,
        "setIsAudioPlaybackEnabled": updateAudioPlaybackEnabled,
        "isMicMuted": isMicMuted,
        # Refs
        "audioElementRef": audioElementRef,
        # Handlers
        "toggleMicMute": toggleMicMute,
        "handleTalkButtonDown": handleTalkButtonDown,
        "handleTalkButtonUp": handleTalkButtonUp,
        "resetPTTState": resetPTTState
    };
}

# path: Algo/hooks/useAuth.cl.jac
import from "@jac/runtime" { jacLogin, jacSignup, useNavigate }

def:pub useAuth() -> dict {
    navigate = useNavigate();

    # Reactive state using has variables
    # Shared State
    has username: str = "";
    has password: str = "";
    has error: str = "";
    has loading: bool = False;

    # Register-Specific State
    has confirmPassword: str = "";

    # Shared Input Handlers
    def handleUsernameChange(e: any) -> None {
        username = e.target.value;
    }

    def handlePasswordChange(e: any) -> None {
        password = e.target.value;
    }

    def handleConfirmPasswordChange(e: any) -> None {
        confirmPassword = e.target.value;
    }

    # Login Handler
    async def handleLogin(e: any) -> None {
        e.preventDefault();
        error = "";

        # Validation
        if not username or not password {
            error = "Please fill in all fields";
            return;
        }

        loading = True;

        try {
            success = await jacLogin(username, password);
            if success {
                navigate("/");
            } else {
                error = "Invalid username or password";
            }
        } except Exception as ex {
            console.error("Login error:", ex);
            if ex.message {
                error = ex.message;
            } else {
                error = "An error occurred during login";
            }
        } finally {
            loading = False;
        }
    }

    # Register Handler
    async def handleRegister(e: any) -> None {
        e.preventDefault();
        error = "";

        # Validation
        if not username or not password or not confirmPassword {
            error = "Please fill in all fields";
            return;
        }

        if password != confirmPassword {
            error = "Passwords do not match";
            return;
        }

        if password.length < 6 {
            error = "Password must be at least 6 characters";
            return;
        }

        loading = True;

        try {
            result = await jacSignup(username, password);
            if result["success"] {
                # Auto-login after successful registration
                navigate("/");
            } else {
                # Extract message from error object
                errorData = result["error"];
                if errorData and errorData.message {
                    error = errorData.message;
                } else {
                    error = "Registration failed";
                }
            }
        } except Exception as ex {
            console.error("Registration error:", ex);
            if ex.message {
                error = ex.message;
            } else {
                error = "An error occurred during registration";
            }
        } finally {
            loading = False;
        }
    }

    # Return Hook Interface
    return {
        "username": username,
        "password": password,
        "error": error,
        "loading": loading,
        "confirmPassword": confirmPassword,
        "handleUsernameChange": handleUsernameChange,
        "handlePasswordChange": handlePasswordChange,
        "handleConfirmPasswordChange": handleConfirmPasswordChange,
        "handleLogin": handleLogin,
        "handleRegister": handleRegister
    };
}

