# path: llvm-slice/lib/impl/classify.impl.jac
"""Implementations for lib/classify.jac."""

impl normalize_llvm_triple(os_tok: str, arch_tok: str) -> str {
    arch: str = _ARCH_MAP[arch_tok] if arch_tok in _ARCH_MAP else arch_tok.lower();
    os_part: str = _OS_MAP[os_tok] if os_tok in _OS_MAP else os_tok.lower();
    # macOS/Windows conventions read <arch>-<os>; keep that order uniformly.
    return f"{arch}-{os_part}";
}


impl _strip_ext(name: str) -> str | None {
    if name.endswith(".tar.xz") {
        return "tar.xz";
    }
    if name.endswith(".tar.gz") {
        return "tar.gz";
    }
    return None;
}


impl classify_asset(name: str, version: str) -> AssetKind | None {
    ext: str | None = _strip_ext(name);
    if ext is None {
        return None;
    }
    base: str = name[: len(name) - (len(ext) + 1)];  # drop ".tar.xz" / ".tar.gz"

    if base.endswith(".src") {
        return None;   # source distribution, not a binary dev surface
    }

    clang_prefix: str = f"clang+llvm-{version}-";
    if base.startswith(clang_prefix) {
        triple: str = base[len(clang_prefix):];
        if triple == "" {
            return None;
        }
        return AssetKind(triple=triple, family="clang+llvm", ext=ext);
    }

    llvm_prefix: str = f"LLVM-{version}-";
    if base.startswith(llvm_prefix) {
        rest: str = base[len(llvm_prefix):];
        parts: list[str] = rest.split("-");
        if len(parts) < 2 {
            return None;
        }
        os_tok: str = parts[0];
        arch_tok: str = "-".join(parts[1:]);
        return AssetKind(
            triple=normalize_llvm_triple(os_tok, arch_tok),
            family="LLVM",
            ext=ext,
        );
    }

    return None;
}

# path: llvm-slice/lib/impl/cmake_parse.impl.jac
"""Implementations for lib/cmake_parse.jac (sees its `re`, `os`, LibEntry imports)."""

impl _split_semicolon_list(raw: str) -> list[str] {
    out: list[str] = [];
    for piece in re.split(r"[;\s]+", raw.strip()) {
        p: str = str(piece).strip();
        if p != "" {
            out.append(p);
        }
    }
    return out;
}


impl parse_version(text: str) -> str {
    m = re.search(r"set\(LLVM_PACKAGE_VERSION\s+([^)\s]+)\)", text);
    if m is None {
        return "";
    }
    return str(m.group(1)).strip();
}


impl parse_available_libs(text: str) -> list[str] {
    m = re.search(r"set\(LLVM_AVAILABLE_LIBS\s+([^)]*)\)", text);
    if m is None {
        return [];
    }
    return _split_semicolon_list(str(m.group(1)));
}


impl parse_targets(text: str) -> list[str] {
    m = re.search(r"set\(LLVM_TARGETS_TO_BUILD\s+([^)]*)\)", text);
    if m is None {
        return [];
    }
    return _split_semicolon_list(str(m.group(1)));
}


impl parse_link_libraries(text: str) -> dict {
    out: dict = {};
    # `\s+` already spans the newline between PROPERTIES and the property, so no
    # DOTALL flag is needed (and passing one trips Jac's overload resolution).
    pat: str = r'set_target_properties\((\S+)\s+PROPERTIES\s+INTERFACE_LINK_LIBRARIES\s+"([^"]*)"';
    for m in re.finditer(pat, text) {
        target: str = str(m.group(1));
        entries: list[str] = [];
        for e in str(m.group(2)).split(";") {
            v: str = e.strip();
            if v != "" {
                entries.append(v);
            }
        }
        out[target] = entries;
    }
    return out;
}


impl _normalize_location(raw: str) -> str {
    # Normalize Windows backslashes FIRST, then drop a leading ${VAR}/ prefix --
    # otherwise a `${_IMPORT_PREFIX}\lib\X.lib` path would not match the stripper.
    p: str = raw.replace("\\", "/");
    return re.sub(r"^\$\{[^}]*\}/", "", p);
}


impl parse_imported_locations(text: str) -> dict {
    out: dict = {};
    # `[^)]` matches newlines, keeping the match inside one block; no DOTALL flag.
    # The config suffix is optional: match IMPORTED_LOCATION_RELEASE/_DEBUG/... AND
    # the plain config-independent IMPORTED_LOCATION.
    pat: str = r'set_target_properties\((\S+)\s+PROPERTIES[^)]*?IMPORTED_LOCATION(?:_\w+)?\s+"([^"]*)"';
    for m in re.finditer(pat, text) {
        out[str(m.group(1))] = _normalize_location(str(m.group(2)));
    }
    return out;
}


impl _unwrap_dep(raw: str) -> str {
    s: str = raw;
    if s.startswith("\\") {
        s = s[1:];
    }
    m = re.search(r"^\$<[A-Za-z_]+:(.+)>$", s);
    if m is not None {
        return str(m.group(1)).strip();
    }
    return raw;
}


impl build_lib_entries(available: list[str], links: dict, locations: dict) -> dict {
    avail_set: set = set(available);
    out: dict = {};
    for name in available {
        raw_deps = links[name] if name in links else [];
        deps: list[str] = [];
        external: list[str] = [];
        for d_any in raw_deps {
            d: str = _unwrap_dep(str(d_any));
            if d in avail_set {
                if d not in deps {
                    deps.append(d);
                }
            } else {
                if d not in external {
                    external.append(d);
                }
            }
        }
        loc_v = locations[name] if name in locations else None;
        file_val: str | None = str(loc_v) if loc_v is not None else None;
        out[name] = LibEntry(name=name, file=file_val, deps=deps, external=external);
    }
    return out;
}


impl _read(path: str) -> str {
    f = open(path, "r");
    data = f.read();
    f.close();
    return str(data);
}


impl has_dev_surface(cmake_llvm_dir: str) -> bool {
    cfg: bool = os.path.isfile(os.path.join(cmake_llvm_dir, "LLVMConfig.cmake"));
    exp: bool = os.path.isfile(os.path.join(cmake_llvm_dir, "LLVMExports.cmake"));
    return cfg and exp;
}


impl parse_cmake_dir(cmake_llvm_dir: str) -> ParsedPackage {
    config_text: str = _read(os.path.join(cmake_llvm_dir, "LLVMConfig.cmake"));
    exports_text: str = _read(os.path.join(cmake_llvm_dir, "LLVMExports.cmake"));

    available: list[str] = parse_available_libs(config_text);
    links: dict = parse_link_libraries(exports_text);

    locations: dict = {};
    for fn in sorted(os.listdir(cmake_llvm_dir)) {
        if fn.startswith("LLVMExports-") and fn.endswith(".cmake") {
            loc: dict = parse_imported_locations(_read(os.path.join(cmake_llvm_dir, fn)));
            for k in loc.keys() {
                if k not in locations {
                    locations[k] = loc[k];
                }
            }
        }
    }

    return ParsedPackage(
        version=parse_version(config_text),
        targets=parse_targets(config_text),
        available=available,
        libs=build_lib_entries(available, links, locations),
    );
}

# path: llvm-slice/lib/impl/pack.impl.jac
"""Implementations for lib/pack.jac (sees its os/hashlib/zipfile imports)."""

impl sha256_file(path: str) -> str {
    h = hashlib.sha256();
    f = open(path, "rb");
    while True {
        chunk: bytes = f.read(1048576);
        if len(chunk) == 0 {
            break;
        }
        h.update(chunk);
    }
    f.close();
    return str(h.hexdigest());
}


impl measure(work_dir: str, rel_paths: list[str]) -> dict {
    out: dict = {};
    for rp in rel_paths {
        full: str = os.path.join(work_dir, rp);
        if os.path.isfile(full) {
            out[rp] = {"size": os.path.getsize(full), "sha256": sha256_file(full), "missing": False};
        } else {
            out[rp] = {"size": 0, "sha256": "", "missing": True};
        }
    }
    return out;
}


impl build_dev_zip(work_dir: str, out_zip: str, manifest_text: str) -> dict {
    workroot: str = os.path.realpath(work_dir);
    skipped: int = 0;
    # Collect (rel, full); sorting by the tuple sorts by rel for a stable order.
    entries: list[tuple] = [];
    for walked in os.walk(work_dir) {
        dir_root: str = str(walked[0]);
        files = walked[2];
        for fn in files {
            full: str = os.path.join(dir_root, str(fn));
            # Some LLVM packages ship symlinks (e.g. lib/python*/lldb/* -> bin/*)
            # whose targets we don't extract. Skip dangling symlinks, and skip
            # symlinks resolving outside the tree so we never capture host files.
            if os.path.islink(full) {
                real: str = os.path.realpath(full);
                if not (real == workroot or real.startswith(workroot + os.sep)) {
                    skipped += 1;
                    continue;
                }
            }
            if not os.path.isfile(full) {
                skipped += 1;
                continue;
            }
            rel: str = os.path.relpath(full, work_dir).replace(os.sep, "/");
            entries.append((rel, full));
        }
    }
    entries.sort();

    zf = zipfile.ZipFile(out_zip, "w", zipfile.ZIP_DEFLATED, compresslevel=6);
    for e in entries {
        rel_e: str = str(e[0]);
        full_e: str = str(e[1]);
        zi = zipfile.ZipInfo(rel_e, date_time=_FIXED_TIME);
        zi.compress_type = int(zipfile.ZIP_DEFLATED);
        rf = open(full_e, "rb");
        zf.writestr(zi, rf.read());
        rf.close();
    }
    mzi = zipfile.ZipInfo("manifest.json", date_time=_FIXED_TIME);
    mzi.compress_type = int(zipfile.ZIP_DEFLATED);
    zf.writestr(mzi, manifest_text);
    zf.close();

    return {"size": os.path.getsize(out_zip), "sha256": sha256_file(out_zip), "skipped_symlinks": skipped};
}

