# path: llvm-slice/llvm_slice/impl/cli.impl.jac
"""Implementations for llvm_slice/cli.jac."""

impl _split_libs(s: str) -> list[str] {
    out: list[str] = [];
    for p in s.split(",") {
        v: str = p.strip();
        if v != "" {
            out.append(v);
        }
    }
    return out;
}


impl _pct(part: int, whole: int) -> str {
    if whole <= 0 {
        return "n/a";
    }
    val: float = 100.0 * float(part) / float(whole);
    return f"{val:.2f}%";
}


impl parse_args(argv: list[str]) -> Args {
    a: Args = Args();
    if len(argv) == 0 {
        a.ok = False;
        a.error = "no subcommand given";
        return a;
    }
    a.cmd = argv[0];
    i: int = 1;
    while i < len(argv) {
        tok: str = argv[i];
        has_next: bool = (i + 1) < len(argv);
        nxt: str = argv[i + 1] if has_next else "";
        if tok == "--version" {
            a.version = nxt; i += 1;
        } elif tok == "--triple" {
            a.triple = nxt; i += 1;
        } elif tok == "--repo" {
            a.repo = nxt; i += 1;
        } elif tok == "--base-url" {
            a.base_url = nxt; i += 1;
        } elif tok == "--libs" {
            a.libs = nxt; i += 1;
        } elif tok == "-o" or tok == "--out" {
            a.out = nxt; i += 1;
        } elif tok == "--headers" {
            a.headers = True;
        } elif tok == "--cmake" {
            a.cmake = True;
        } else {
            a.ok = False;
            a.error = "unknown argument: " + tok;
            return a;
        }
        i += 1;
    }
    return a;
}


impl _require_common(a: Args) -> bool {
    if a.version == "" or a.triple == "" {
        print("error: --version and --triple are required");
        return False;
    }
    return True;
}


impl cmd_list(a: Args) -> int {
    if not _require_common(a) {
        return 2;
    }
    fm = load_manifest(a.version, a.triple, a.repo, a.base_url);
    print(f"LLVM {fm.version}  {fm.triple}  ({len(fm.libs)} libraries)");
    for name in sorted(fm.libs.keys()) {
        e = fm.libs[name];
        marker: str = e.file if e.file is not None else "(header-only)";
        print(f"  {name}  ->  {marker}");
    }
    return 0;
}


impl cmd_resolve(a: Args) -> int {
    if not _require_common(a) {
        return 2;
    }
    if a.libs == "" {
        print("error: --libs is required for resolve");
        return 2;
    }
    fm = load_manifest(a.version, a.triple, a.repo, a.base_url);
    roots: list[str] = _split_libs(a.libs);
    res = resolve_closure(fm.libs, roots);
    if len(res.missing) > 0 {
        print("WARNING: requested libs not in manifest: " + ", ".join(res.missing));
    }
    print(f"closure: {len(res.closure)} libraries (static link order, dependents first)");
    print("  " + " ".join(res.closure));
    print(f"external link requirements: {len(res.external)}");
    print("  " + " ".join(res.external));
    return 0;
}


impl cmd_fetch(a: Args) -> int {
    if not _require_common(a) {
        return 2;
    }
    if a.libs == "" {
        print("error: --libs is required for fetch");
        return 2;
    }
    roots: list[str] = _split_libs(a.libs);
    rep = fetch_slice(
        a.version, a.triple, a.repo, a.base_url,
        roots, a.headers, a.cmake, a.out
    );
    if len(rep.missing) > 0 {
        print("WARNING: requested libs not in manifest: " + ", ".join(rep.missing));
    }
    if not rep.range_supported {
        print("WARNING: server did not support range requests; downloaded the full zip. " + rep.warning);
    }
    print(f"fetched {rep.members} members ({len(rep.closure)} libs in closure) -> {a.out}");
    print(f"transferred {rep.bytes_fetched} of {rep.full_size} bytes ({_pct(rep.bytes_fetched, rep.full_size)} of the full zip)");
    if len(rep.external) > 0 {
        print("external link requirements: " + " ".join(rep.external));
    }
    return 0;
}


impl usage() -> None {
    print("usage: llvm-slice <list|resolve|fetch> --version V --triple T [options]");
    print("  list     --version V --triple T");
    print("  resolve  --version V --triple T --libs A,B,C");
    print("  fetch    --version V --triple T --libs A,B,C [--headers] [--cmake] -o DIR");
    print("options: --repo owner/name | --base-url URL");
}


impl main() -> int {
    a: Args = parse_args(sys.argv[1:]);
    if not a.ok {
        print("error: " + a.error);
        usage();
        return 2;
    }
    if a.cmd == "list" {
        return cmd_list(a);
    }
    if a.cmd == "resolve" {
        return cmd_resolve(a);
    }
    if a.cmd == "fetch" {
        return cmd_fetch(a);
    }
    usage();
    return 2;
}

# path: llvm-slice/llvm_slice/impl/fetcher.impl.jac
"""Implementations for client/llvm_slice/fetcher.jac."""

impl resolve_repo(repo: str) -> str {
    if repo != "" {
        return repo;
    }
    env = os.environ.get("LLVM_SLICE_REPO");
    return str(env) if env is not None else DEFAULT_REPO;
}


impl asset_base(version: str, repo: str, base_override: str) -> str {
    if base_override != "" {
        return base_override[:-1] if base_override.endswith("/") else base_override;
    }
    return f"https://github.com/{repo}/releases/download/v{version}";
}


impl manifest_asset(version: str, triple: str) -> str {
    return f"llvm-{version}-{triple}-manifest.json";
}


impl zip_asset(version: str, triple: str) -> str {
    return f"llvm-{version}-{triple}-dev.zip";
}


impl http_get(url: str) -> bytes {
    r = urlopen(url);
    data = r.read();
    r.close();
    return bytes(data);
}


impl load_manifest(version: str, triple: str, repo: str, base_override: str) -> FetchedManifest {
    base: str = asset_base(version, resolve_repo(repo), base_override);
    url: str = f"{base}/{manifest_asset(version, triple)}";
    raw: bytes = http_get(url);
    data: dict = dict(json.loads(raw));
    if "libs" not in data {
        raise RuntimeError(f"manifest at {url} is missing the required 'libs' field");
    }
    libs = lib_entries_from_json(dict(data["libs"]));
    zip_a: str = str(data["zip_asset"]) if ("zip_asset" in data and data["zip_asset"] is not None) else zip_asset(version, triple);
    inc: str = str(data["include_prefix"]) if ("include_prefix" in data and data["include_prefix"] is not None) else "include/";
    cm: str = str(data["cmake_prefix"]) if ("cmake_prefix" in data and data["cmake_prefix"] is not None) else "lib/cmake/";
    ver: str = str(data["llvm_version"]) if ("llvm_version" in data and data["llvm_version"] is not None) else version;
    trip: str = str(data["triple"]) if ("triple" in data and data["triple"] is not None) else triple;
    return FetchedManifest(
        version=ver,
        triple=trip,
        zip_asset=zip_a,
        include_prefix=inc,
        cmake_prefix=cm,
        libs=libs,
    );
}


impl fetch_slice(
    version: str, triple: str, repo: str, base_override: str,
    roots: list[str], want_headers: bool, want_cmake: bool, out_dir: str
) -> FetchReport {
    fm: FetchedManifest = load_manifest(version, triple, repo, base_override);
    res = resolve_closure(fm.libs, roots);

    base: str = asset_base(version, resolve_repo(repo), base_override);
    # Use the manifest's recorded zip asset name (falling back to the default
    # pattern), so a manifest with a non-standard zip_asset still resolves.
    zname: str = fm.zip_asset if fm.zip_asset != "" else zip_asset(version, triple);
    zurl: str = f"{base}/{zname}";

    # The library members to pull are exactly the closure entries that have a file.
    lib_members: list[str] = [];
    for name in res.closure {
        fpath: str | None = fm.libs[name].file;
        if fpath is not None {
            lib_members.append(fpath);
        }
    }

    rep: dict = fetch_members(
        zurl, lib_members, fm.include_prefix, fm.cmake_prefix, want_headers, want_cmake, out_dir
    );

    return FetchReport(
        members=int(rep["members"]),
        bytes_fetched=int(rep["bytes_fetched"]),
        full_size=int(rep["full_size"]),
        closure=res.closure,
        external=res.external,
        missing=res.missing,
        range_supported=bool(rep["range_supported"]),
        warning=str(rep["warning"]),
    );
}

