# path: llvm-slice/llvm_slice/impl/rangezip.impl.jac
"""Implementations for client/llvm_slice/rangezip.jac."""

impl HTTPRangeReader.postinit() -> None {
    self.final_url = self.url;
    try {
        req = Request(self.url, method="HEAD");
        r = urlopen(req, timeout=self.timeout);
        self.final_url = str(r.geturl());
        cl = r.headers.get("Content-Length", "0");
        self.size = int(cl) if cl is not None else 0;
        ar = r.headers.get("Accept-Ranges", "");
        self.range_supported = str(ar).lower() == "bytes" if ar is not None else False;
        r.close();
    } except Exception as e {
        self.size = 0;
        self.range_supported = False;
        self.warning = "HEAD request failed: " + str(e);
    }
    if self.size <= 0 {
        self.range_supported = False;
        if self.warning == "" {
            self.warning = "server did not report Content-Length";
        }
    }
}


impl HTTPRangeReader.seekable() -> bool {
    return True;
}


impl HTTPRangeReader.tell() -> int {
    return self.pos;
}


impl HTTPRangeReader.seek(offset: int, whence: int = 0) -> int {
    if whence == 0 {
        self.pos = offset;
    } elif whence == 1 {
        self.pos = self.pos + offset;
    } else {
        self.pos = self.size + offset;
    }
    return self.pos;
}


impl HTTPRangeReader._ensure_full() -> None {
    if self.buf is None {
        r = urlopen(self.final_url, timeout=self.timeout);
        data: bytes = bytes(r.read());
        r.close();
        self.buf = data;
        self.size = len(data);
        self.bytes_fetched = self.bytes_fetched + len(data);
    }
}


impl HTTPRangeReader.read(n: int = -1) -> bytes {
    if not self.range_supported {
        self._ensure_full();
        b: bytes = self.buf if self.buf is not None else b"";
        chunk: bytes = b[self.pos:] if n < 0 else b[self.pos: self.pos + n];
        self.pos = self.pos + len(chunk);
        return chunk;
    }
    end: int = self.size - 1 if n < 0 else min(self.pos + n - 1, self.size - 1);
    if self.size <= 0 or end < self.pos {
        return b"";
    }
    # Accumulate until the full requested range is satisfied: a server may
    # legitimately return a 206 shorter than requested, which would otherwise
    # misalign zipfile's view of the stream.
    parts: list[bytes] = [];
    cur: int = self.pos;
    while cur <= end {
        req = Request(self.final_url, headers={"Range": f"bytes={cur}-{end}"});
        r = urlopen(req, timeout=self.timeout);
        part: bytes = bytes(r.read());
        r.close();
        if len(part) == 0 {
            break;
        }
        parts.append(part);
        self.bytes_fetched = self.bytes_fetched + len(part);
        cur = cur + len(part);
    }
    data: bytes = b"".join(parts);
    self.pos = self.pos + len(data);
    return data;
}


impl fetch_members(
    url: str, lib_members: list[str], include_prefix: str, cmake_prefix: str,
    want_headers: bool, want_cmake: bool, out_dir: str
) -> dict {
    reader = HTTPRangeReader(url=url);
    zf = zipfile.ZipFile(reader);
    names = zf.namelist();

    selected: list[str] = [];
    seen: set = set();
    for m in lib_members {
        if m != "" and m not in seen {
            selected.append(m);
            seen.add(m);
        }
    }
    if want_headers or want_cmake {
        for nm in names {
            n: str = str(nm);
            if n.endswith("/") {
                continue;
            }
            hit: bool = (want_headers and n.startswith(include_prefix)) or (want_cmake and n.startswith(cmake_prefix));
            if hit and n not in seen {
                selected.append(n);
                seen.add(n);
            }
        }
    }

    os.makedirs(out_dir, exist_ok=True);
    out_root: str = os.path.realpath(out_dir);
    written: int = 0;
    missing: list[str] = [];
    unsafe: list[str] = [];
    for m in selected {
        # Guard against zip-slip: a member like "../../etc/x" must not escape out_dir.
        native: str = m.replace("/", os.sep);
        dest: str = os.path.normpath(os.path.join(out_dir, native));
        real_dest: str = os.path.realpath(dest);
        if real_dest != out_root and not real_dest.startswith(out_root + os.sep) {
            unsafe.append(m);
            continue;
        }
        try {
            data: bytes = zf.read(m);
        } except KeyError {
            missing.append(m);
            continue;
        }
        parent: str = os.path.dirname(dest);
        if parent != "" {
            os.makedirs(parent, exist_ok=True);
        }
        wf = open(dest, "wb");
        wf.write(data);
        wf.close();
        written += 1;
    }

    return {
        "members": written,
        "missing_members": missing,
        "unsafe_members": unsafe,
        "bytes_fetched": reader.bytes_fetched,
        "full_size": reader.size,
        "range_supported": reader.range_supported,
        "warning": reader.warning,
    };
}

# path: llvm-slice/llvm_slice/impl/resolve.impl.jac
"""Implementations for client/llvm_slice/resolve.jac."""

impl Closure.start {
    visit [-->];
}


impl Closure.on_lib {
    if here.name in self.seen {
        skip;
    }
    self.seen.append(here.name);
    for e in here.external {
        if e not in self.external {
            self.external.append(e);
        }
    }
    visit [here ->:DependsOn:->];
}


impl _dfs_post(name: str, deps_map: dict[str, list[str]], visited: list[str], post: list[str]) -> None {
    if name in visited {
        return;
    }
    visited.append(name);
    deps: list[str] = deps_map[name] if name in deps_map else [];
    for d in deps {
        _dfs_post(d, deps_map, visited, post);
    }
    post.append(name);
}


impl _link_order(roots: list[str], deps_map: dict[str, list[str]]) -> list[str] {
    visited: list[str] = [];
    post: list[str] = [];
    for r in roots {
        _dfs_post(r, deps_map, visited, post);
    }
    post.reverse();
    return post;
}


impl resolve_closure(libs: dict[str, LibEntry], roots: list[str]) -> ClosureResult {
    # 1. Build the off-root graph.
    nodes: dict[str, LibNode] = {};
    for name in libs.keys() {
        entry: LibEntry = libs[name];
        nodes[name] = LibNode(name=name, file=entry.file, deps=entry.deps, external=entry.external);
    }
    for name in nodes.keys() {
        src: LibNode = nodes[name];
        for d in src.deps {
            if d in nodes {
                src +>:DependsOn:+> nodes[d];
            }
        }
    }

    # 2. Wire an Origin to the requested roots and walk.
    origin = Origin();
    present_roots: list[str] = [];
    missing: list[str] = [];
    for r in roots {
        if r in nodes {
            origin ++> nodes[r];
            present_roots.append(r);
        } else {
            missing.append(r);
        }
    }
    res = origin spawn Closure();
    closure_set: list[str] = res.seen;

    # 3. Order the closure for a correct static link line.
    cset: list[str] = closure_set;
    deps_map: dict[str, list[str]] = {};
    for name in closure_set {
        in_closure: list[str] = [d for d in nodes[name].deps if d in cset];
        deps_map[name] = in_closure;
    }
    order: list[str] = _link_order(present_roots, deps_map);

    total: int = 0;
    for name in closure_set {
        total += libs[name].size;
    }

    return ClosureResult(
        roots=present_roots,
        missing=missing,
        closure=order,
        external=res.external,
        total_size=total,
    );
}

