            "backgroundColor": "#9ca3af" if disabled else "#3b82f6",
            "color": "#ffffff"
        },
        "secondary": {
            "backgroundColor": "#e5e7eb" if disabled else "#6b7280",
            "color": "#ffffff"
        }
    };

    return <button
        style={{**base_styles, **variant_styles[variant]}}
        onClick={onClick}
        disabled={disabled}
    >
        {label}
    </button>;
}

# path: littleX/littleX_FULLSTACK/components/Composer.cl.jac
"""Reusable post composer for Little X (feed + channels)."""

def:pub Composer(
    avatar: str,
    avatarAlt: str,
    placeholder: str,
    value: str,
    onChange: any,
    onPost: any,
    rows: int = 3,
    buttonLabel: str = "Post",
    showCharRing: bool = False,
) -> JsxElement {
    changeFn = onChange;
    postFn = onPost;

    charsLeft = 280 - len(value);
    ring_progress = min(1.0, (280 - charsLeft) / 280.0);
    ring_offset = str(62.83 * (1.0 - ring_progress));
    ring_color = "#ef4444" if charsLeft < 0 else ("#f97316" if charsLeft < 50 else ("#fb923c" if charsLeft < 100 else "#2a2a35"));
    over_limit = showCharRing and charsLeft < 0;

    return <div className="lx-composer">
        <img className="lx-avatar" src={avatar} alt={avatarAlt} />
        <div className="lx-composer-body">
            <textarea
                className="lx-composer-textarea"
                placeholder={placeholder}
                value={value}
                onChange={lambda e: ChangeEvent { changeFn.call(None, e.target.value); }}
                rows={rows}
            />
            <div className="lx-composer-footer">
                {(
                    <div className="lx-char-ring-wrap">
                        <svg className="lx-char-ring" viewBox="0 0 24 24">
                            <circle className="lx-char-ring-bg" cx={12} cy={12} r={10} />
                            <circle
                                className="lx-char-ring-fill"
                                cx={12}
                                cy={12}
                                r={10}
                                strokeDasharray={"62.83"}
                                strokeDashoffset={ring_offset}
                                stroke={ring_color}
                            />
                        </svg>
                        {(
                            <span className={"lx-char-count-over" if charsLeft < 0 else "lx-char-count-warn"}>
                                {str(charsLeft)}
                            </span>
                        ) if charsLeft <= 20 else None}
                    </div>
                ) if showCharRing else <div />}
                <button
                    className="lx-post-btn"
                    disabled={not value.strip() or over_limit}
                    onClick={lambda { postFn.call(None); }}
                >
                    {buttonLabel}
                </button>
            </div>
        </div>
    </div>;
}

