# path: littleX/littleX_FULLSTACK/components/TweetCard.cl.jac
"""Tweet card component for Little X."""

import from "lucide-react" { Heart, MessageCircle, Trash2, Repeat2 }
sv import from ..server { TweetView }

def:pub TweetCard(
    tweet: TweetView,
    myUsername: str,
    onLike: any,
    onComment: any,
    onDelete: any,
    onRepost: any,
) -> JsxElement {
    has showComments: bool = False,
        commentText: str = "";

    likeFn = onLike;
    commentFn = onComment;
    deleteFn = onDelete;
    repostFn = onRepost;

    is_liked = myUsername in tweet.likes;
    like_count = str(len(tweet.likes));
    comment_count = str(len(tweet.comments));
    author_avatar = "https://i.pravatar.cc/150?u=fake@" + tweet.author_username;

    raw_name = tweet.author_username if tweet.author_username else "unknown";
    display_name = raw_name.split("@")[0] if "@" in raw_name else raw_name;

    diff_ms = Date.now() - new(Date, tweet.created_at).getTime() if tweet.created_at else 0;
    diff_min = int(diff_ms / 60000);
    diff_hr = int(diff_min / 60);
    diff_day = int(diff_hr / 24);
    date_str = (
        "now" if diff_min < 1 else (
            str(diff_min) + "m" if diff_hr < 1 else (
                str(diff_hr) + "h" if diff_day < 1 else (
                    str(diff_day) + "d" if diff_day < 30 else tweet.created_at[0:10]
                )
            )
        )
    ) if tweet.created_at else "";

    return <div className="lx-tweet">
        <img className="lx-avatar" src={author_avatar} alt={tweet.author_username} />
        <div className="lx-tweet-body">
            <div className="lx-tweet-header">
                <span className="lx-tweet-name">{display_name}</span>
                <span className="lx-tweet-handle">{"@" + display_name}</span>
                <span className="lx-tweet-dot">·</span>
                <span className="lx-tweet-time">{date_str}</span>
            </div>
            <div className="lx-tweet-text">{tweet.content}</div>
            <div className="lx-tweet-actions">
                <button
                    className="lx-act-btn lx-act-comment"
                    onClick={lambda { showComments = not showComments; }}
                >
                    <MessageCircle size={16} />
                    <span>{comment_count}</span>
                </button>
                <button
                    className="lx-act-btn lx-act-repost"
                    onClick={lambda { repostFn.call(None, tweet.id, tweet.content, tweet.author_username); }}
                    title="Repost"
                >
                    <Repeat2 size={16} />
                </button>
                <button
                    className={"lx-act-btn lx-act-liked" if is_liked else "lx-act-btn lx-act-like"}
                    onClick={lambda { likeFn.call(None, tweet.id); }}
                >
                    <Heart size={16} />
                    <span>{like_count}</span>
                </button>
                {(
                    <button
                        className="lx-act-btn lx-act-delete"
                        onClick={lambda { if confirm("Delete this post? This cannot be undone.") { deleteFn.call(None, tweet.id); } }}
                    >
                        <Trash2 size={16} />
                    </button>
                ) if tweet.is_mine else None}
            </div>
            {(
                <div className="lx-comments-section">
                    {[
                        <div className="lx-comment-item" key={c["created_at"]}>
                            <img className="lx-avatar-sm" src={"https://i.pravatar.cc/150?u=fake@" + c["username"]} alt={c["username"]} />
                            <div>
                                <div className="lx-comment-meta">
                                    <strong>{c["username"]}</strong>
                                </div>
                                <div className="lx-comment-text">{c["content"]}</div>
                            </div>
                        </div>
                        for c in tweet.comments
                    ]}
                    <div className="lx-comment-form">
                        <input
                            className="lx-comment-input"
                            placeholder="Reply..."
                            value={commentText}
                            onChange={lambda e: ChangeEvent { commentText = e.target.value; }}
                            onKeyDown={lambda e: KeyboardEvent {
                                if e.key == "Enter" and commentText.strip() {
                                    commentFn.call(None, tweet.id, commentText);
                                    commentText = "";
                                }
                            }}
                        />
                        <button
                            className="lx-comment-submit"
                            onClick={lambda {
                                if commentText.strip() {
                                    commentFn.call(None, tweet.id, commentText);
                                    commentText = "";
                                }
                            }}
                        >
                            Reply
                        </button>
                    </div>
                </div>
            ) if showComments else None}
        </div>
    </div>;
}

# path: littleX/littleX_FULLSTACK/frontend.impl.jac
"""Little X - Frontend function implementations."""

impl app.loadData -> None {
    result = root spawn setup_profile(
        username=localStorage.getItem("lx_username") or ""
    );
    myProfile = result.reports[0] if result.reports else None;

    feedResult = root spawn load_feed(search_query="");
    tweets = feedResult.reports[0] if feedResult.reports else [];
    feedLoading = False;

    profileResult = root spawn get_profile();
    myProfile = profileResult.reports[0] if profileResult.reports else myProfile;

    profilesResult = root spawn get_all_profiles();
    allProfiles = profilesResult.reports[0] if profilesResult.reports else [];

    trendResult = root spawn get_trending();
    trendingTags = trendResult.reports[0] if trendResult.reports else [];

    total_activity = sum(
        [
            len(t.likes) + len(t.comments)
            for t in (myProfile.tweets if myProfile and myProfile.tweets else [])
        ]
    );
    last_seen_str = localStorage.getItem("lx_activity_total");
    last_seen = int(last_seen_str) if last_seen_str else 0;
    notifCount = total_activity - last_seen if total_activity > last_seen else 0;
}

impl app.handleLogin -> None {
    authError = "";
    if not authUsername.strip() or not authPassword {
        authError = "Please fill in all fields";
        return;
    }
    authLoading = True;
    result: any = await jacLogin(authUsername, authPassword);
    authLoading = False;
    if result and (result["ok"] or result == True) {
        localStorage.setItem("lx_username", authUsername);
        isLoggedIn = True;
        authPassword = "";
        authError = "";
    } else {
        authError = str(
            result["error"]["message"]
                if result and result["error"] and result["error"]["message"]
                else "Invalid username or password"
        );
    }
}

impl app.handleSignup -> None {
    authError = "";
    if not authUsername.strip() or not authPassword {
        authError = "Please fill in all fields";
        return;
    }
    if len(authPassword) < 4 {
        authError = "Password must be at least 4 characters";
        return;
    }
    authLoading = True;
    result: any = await jacSignup(authUsername, authPassword);
    if result["ok"] or result["success"] {
        # jacSignup only registers the account; establish a session by
        # logging in so the first walker calls aren't rejected with 401.
        loginResult: any = await jacLogin(authUsername, authPassword);
        authLoading = False;
        if loginResult and (loginResult["ok"] or loginResult == True) {
            localStorage.setItem("lx_username", authUsername);
            isLoggedIn = True;
            authPassword = "";
            authError = "";
        } else {
            isSignup = False;
            authError = "Account created. Please log in.";
        }
    } else {
        authLoading = False;
        authError = str(
            result["error"]["message"]
                if result["error"] and result["error"]["message"]
                else (result["error"] if result["error"] else "Signup failed")
        );
    }
}

impl app.handleLogout -> None {
    jacLogout();
    localStorage.removeItem("lx_username");
    isLoggedIn = False;
    myProfile = None;
    tweets = [];
    allProfiles = [];
    activeTab = "feed";
    authUsername = "";
    authPassword = "";
}

impl app.postTweet -> None {
    if not composerText.strip() {
        return;
    }
    text = composerText;
    composerText = "";
    root spawn create_tweet(content=text);
    feedResult = root spawn load_feed(search_query="");
    tweets = feedResult.reports[0] if feedResult.reports else [];
    profileResult = root spawn get_profile();
    myProfile = profileResult.reports[0] if profileResult.reports else myProfile;
    trendResult = root spawn get_trending();
    trendingTags = trendResult.reports[0] if trendResult.reports else [];
}

impl app.handleLike(tweetId: str) -> None {
    root spawn like_tweet(tweet_id=tweetId);
    feedResult = root spawn load_feed(search_query=searchQuery);
    tweets = feedResult.reports[0] if feedResult.reports else [];
    if myProfile {
        profileResult = root spawn get_profile();
        myProfile = profileResult.reports[0] if profileResult.reports else myProfile;
    }
    if selectedChannel {
        detailResult = root spawn get_channel_detail(channel_id=selectedChannel.id);
        detail = detailResult.reports[0] if detailResult.reports else None;
        if detail {
            selectedChannel = detail;
            channelPosts = detail.posts if detail.posts else [];
        }
    }
}

impl app.handleComment(tweetId: str, content: str) -> None {
    root spawn add_comment(tweet_id=tweetId, content=content);
    feedResult = root spawn load_feed(search_query=searchQuery);
    tweets = feedResult.reports[0] if feedResult.reports else [];
    if selectedChannel {
        detailResult = root spawn get_channel_detail(channel_id=selectedChannel.id);
        detail = detailResult.reports[0] if detailResult.reports else None;
        if detail {
            selectedChannel = detail;
            channelPosts = detail.posts if detail.posts else [];
        }
    }
}

impl app.handleDelete(tweetId: str) -> None {
    root spawn delete_tweet(tweet_id=tweetId);
    feedResult = root spawn load_feed(search_query=searchQuery);
    tweets = feedResult.reports[0] if feedResult.reports else [];
    profileResult = root spawn get_profile();
    myProfile = profileResult.reports[0] if profileResult.reports else myProfile;
}

impl app.handleFollow(profileId: str) -> None {
    if profileId == "_load" {
        profilesResult = root spawn get_all_profiles();
        allProfiles = profilesResult.reports[0] if profilesResult.reports else [];
        return;
    }
    root spawn follow_user(target_id=profileId);
    profileResult = root spawn get_profile();
    myProfile = profileResult.reports[0] if profileResult.reports else myProfile;
    feedResult = root spawn load_feed(search_query=searchQuery);
    tweets = feedResult.reports[0] if feedResult.reports else [];
}

impl app.handleUnfollow(profileId: str) -> None {
    root spawn unfollow_user(target_id=profileId);
    profileResult = root spawn get_profile();
    myProfile = profileResult.reports[0] if profileResult.reports else myProfile;
    feedResult = root spawn load_feed(search_query=searchQuery);
    tweets = feedResult.reports[0] if feedResult.reports else [];
}

impl app.handleSaveBio -> None {
    uname = myProfile.username if myProfile else "";
    root spawn setup_profile(username=uname, bio=bioText);
    profileResult = root spawn get_profile();
    myProfile = profileResult.reports[0] if profileResult.reports else myProfile;
    editingBio = False;
}

impl app.handleSearch(query: str) -> None {
    feedResult = root spawn load_feed(search_query=query);
    tweets = feedResult.reports[0] if feedResult.reports else [];
}

impl app.handleRepost(tweetId: str, content: str, author: str) -> None {
    display_author = author.split("@")[0] if "@" in author else author;
    composerText = "RT @" + display_author + ": " + content;
    activeTab = "feed";
}

impl app.handleDismissWelcome -> None {
    localStorage.setItem("lx_welcomed", "1");
    showWelcome = False;
}

impl app.handleTrendClick(tag: str) -> None {
    searchQuery = tag;
    handleSearch(tag);
    activeTab = "feed";
}

# Single entry point for tab switching -- consolidates the per-tab side
# effects (search reset, channel load, profile activity bookkeeping) that
# used to be duplicated across the desktop and mobile nav bars.
impl app.navigate(tab: str) -> None {
    activeTab = tab;
    if tab == "feed" and searchQuery {
        searchQuery = "";
        handleSearch("");
    }
    if tab == "channels" {
        loadChannels();
    }
    if tab == "profile" {
        total_activity = sum(
            [
                len(t.likes) + len(t.comments)
                for t in (myProfile.tweets if myProfile and myProfile.tweets else [])
            ]
        );
        localStorage.setItem("lx_activity_total", str(total_activity));
        notifCount = 0;
    }
}

impl app.loadChannels -> None {
