# path: jaseci-blogs/components/PostBody.cl.jac
"""PostBody — renders post HTML and progressively enhances code blocks.

The server emits HTML via python-markdown. After mount we walk the DOM and:
  - Add a copy button + language label to <pre><code class="language-x"> blocks
  - Add a collapse toggle for code blocks > 14 lines
  - Render Mermaid diagrams in code blocks tagged .language-mermaid
  - Upgrade <div class="code-block"> wrappers into <RunnableJacBlock> via dynamic mount

External libraries (Mermaid, Monaco, Pyodide) are loaded lazily — only when
the page actually contains a block that needs them.
"""

import from react { useRef }
import from "./RunnableJacBlock.cl.jac" { register_upgrade_hook }


def:pub PostBody(html: str) -> JsxElement {
        ref = useRef(None);
        has html_version: int = 0;

        can with [html] entry {
            html_version = html_version + 1;
        }

        async can with [html_version] entry {
            if not ref.current {
                return;
            }
            container = ref.current;

            try {
                enhance_code_blocks(container);
            } except Exception {
                _ignore = None;
            }

            try {
                await render_mermaid_blocks(container);
            } except Exception {
                _ignore = None;
            }

            try {
                await mount_runnable_blocks(container);
            } except Exception {
                _ignore = None;
            }
        }

        return <div
            ref={ref}
            className="prose"
            dangerouslySetInnerHTML={{"__html": html}}
        />;
    }


    def enhance_code_blocks(container: any) -> None {
        # Add copy button + language tag + collapse toggle to every <pre><code>.
        blocks = container.querySelectorAll("pre > code");
        for code_el in blocks {
            pre = code_el.parentElement;
            if pre.dataset.enhanced {
                continue;
            }
            pre.dataset.enhanced = "true";

            # Extract language from class="language-foo" or class="highlight foo"
            lang = "";
            classes = code_el.className.split(" ");
            for cls in classes {
                if cls.startswith("language-") {
                    lang = cls[len("language-"):];
                    break;
                }
            }
            if lang == "mermaid" {
                # Skip — handled by render_mermaid_blocks.
                continue;
            }

            # Wrap pre in a figure-like shell to host chrome.
            shell = document.createElement("div");
            shell.className = "code-shell";
            pre.parentNode.insertBefore(shell, pre);
            shell.appendChild(pre);

            # Header row: language label + copy button.
            header = document.createElement("div");
            header.className = "code-shell-header";
            if lang {
                tag = document.createElement("span");
                tag.className = "code-lang";
                tag.textContent = lang;
                header.appendChild(tag);
            }
            copy_btn = document.createElement("button");
            copy_btn.type = "button";
            copy_btn.className = "code-copy";
            copy_btn.textContent = "Copy";
            copy_btn.addEventListener("click", lambda -> None {
                try {
                    navigator.clipboard.writeText(code_el.textContent);
                    copy_btn.textContent = "Copied";
                    setTimeout(lambda -> None { copy_btn.textContent = "Copy"; }, 1500);
                } except Exception {
                    _ignore = None;
                }
            });
            header.appendChild(copy_btn);
            shell.insertBefore(header, pre);

            # Collapse if > 14 lines.
            line_count = len(code_el.textContent.split("\n"));
            if line_count > 14 {
                shell.classList.add("code-shell-collapsible");
                shell.classList.add("code-shell-collapsed");
                toggle = document.createElement("button");
                toggle.type = "button";
                toggle.className = "code-shell-toggle";
                toggle.textContent = f"Show all {line_count} lines";
                toggle.addEventListener("click", lambda -> None {
                    is_collapsed = shell.classList.contains("code-shell-collapsed");
                    if is_collapsed {
                        shell.classList.remove("code-shell-collapsed");
                        toggle.textContent = "Collapse";
                    } else {
                        shell.classList.add("code-shell-collapsed");
                        toggle.textContent = f"Show all {line_count} lines";
                    }
                });
                shell.appendChild(toggle);
            }
        }
    }


    async def render_mermaid_blocks(container: any) -> None {
        targets = container.querySelectorAll("code.language-mermaid");
        has_any = False;
        for _t in targets {
            has_any = True;
            break;
        }
        if not has_any {
            return;
        }
        # Lazy-load mermaid.
        if not window.mermaid {
            await load_script("https://cdn.jsdelivr.net/npm/mermaid@10/dist/mermaid.min.js");
            try {
                theme = document.documentElement.getAttribute("data-theme") or "light";
                window.mermaid.initialize({
                    "startOnLoad": False,
                    "theme": "dark" if theme == "dark" else "default",
                    "fontFamily": "Inter, system-ui, sans-serif",
                });
            } except Exception {
                _ignore = None;
            }
        }
        for (i, code_el) in enumerate(targets) {
            pre = code_el.parentElement;
            wrapper = document.createElement("div");
            wrapper.className = "mermaid-block";
            wrapper.id = f"mermaid-{Date.now()}-{i}";
            wrapper.textContent = code_el.textContent;
            pre.parentNode.replaceChild(wrapper, pre);
        }
        try {
            await window.mermaid.run({"querySelector": ".mermaid-block"});
        } except Exception {
            _ignore = None;
        }
    }


    async def mount_runnable_blocks(container: any) -> None {
        # Ensure the upgrade hook is registered before we look for blocks.
        register_upgrade_hook();
        blocks = container.querySelectorAll("div.code-block");
        has_blocks = False;
        for _b in blocks {
            has_blocks = True;
            break;
        }
        if not has_blocks {
            return;
        }
        # Lazy-load the runnable bundle.
        if not window.__jac_runnable_loaded {
            await Promise.all([
                load_script("https://cdn.jsdelivr.net/pyodide/v0.27.0/full/pyodide.js"),
                load_script("https://cdnjs.cloudflare.com/ajax/libs/monaco-editor/0.52.2/min/vs/loader.min.js"),
            ]);
            window.__jac_runnable_loaded = True;
        }
        # The actual upgrade is handled by the imperative JS exposed at
        # window.__jac_runnable_upgrade — wired up by RunnableJacBlock module.
        if window.__jac_runnable_upgrade {
            window.__jac_runnable_upgrade(blocks);
        }
    }


    async def load_script(src: str) -> None {
        existing = document.querySelector(f"script[src='{src}']");
        if existing {
            return;
        }
        promise = Promise(lambda resolve, reject -> None {
            script = document.createElement("script");
            script.src = src;
            script.onload = lambda -> None { resolve(None); };
            script.onerror = lambda -> None { reject(None); };
            document.head.appendChild(script);
        });
        await promise;
    }

# path: jaseci-blogs/components/RunnableJacBlock.cl.jac
"""RunnableJacBlock — interactive Jac code editor + runner.

Exposes window.__jac_runnable_upgrade(blocks) for PostBody to call after
the prose HTML mounts. Each <div class="code-block"> wrapper becomes a
Monaco editor + Run button + output pane.

Jac execution runs in Pyodide: jaclang is installed via micropip once, then
each Run pipes the editor contents through `jac run`-equivalent and captures
stdout/stderr. Loaded lazily — only when a page has a runnable block.
"""

glob:pub __pyodide: any = None;
glob:pub __pyodide_loading: any = None;


    async def boot_pyodide() -> any {
        py = await window.loadPyodide({
            "indexURL": "https://cdn.jsdelivr.net/pyodide/v0.27.0/full/",
        });
        await py.loadPackage(["micropip"]);
        micropip = py.pyimport("micropip");
        await micropip.install(["jaclang"]);
        return py;
    }


    async def ensure_pyodide() -> any {
        if __pyodide {
            return __pyodide;
        }
        if not __pyodide_loading {
            __pyodide_loading = boot_pyodide();
        }
        __pyodide = await __pyodide_loading;
        return __pyodide;
    }


    async def run_jac(code: str) -> dict {
        try {
            py = await ensure_pyodide();
            py.runPython("import sys, io; _stdout = io.StringIO(); _stderr = io.StringIO(); sys.stdout = _stdout; sys.stderr = _stderr;");
            py.globals.set("__jac_source", code);
            py.runPython(
                "from jaclang.runtimelib.machine import JacMachineInterface as Jac\n"
                "import tempfile, os, traceback\n"
                "with tempfile.NamedTemporaryFile(mode='w', suffix='.jac', delete=False) as f:\n"
                "    f.write(__jac_source)\n"
                "    __jac_path = f.name\n"
                "try:\n"
                "    Jac.jac_import(os.path.basename(__jac_path).replace('.jac',''), base_path=os.path.dirname(__jac_path))\n"
                "except Exception:\n"
                "    traceback.print_exc()\n"
            );
            stdout = py.runPython("_stdout.getvalue()");
            stderr = py.runPython("_stderr.getvalue()");
            return {"stdout": str(stdout), "stderr": str(stderr), "ok": True};
        } except Exception as e {
            return {"stdout": "", "stderr": str(e), "ok": False};
        }
    }


    def mount_monaco(host: any, initial: str, on_ready: any) -> None {
        try {
            window.require.config({
                "paths": {"vs": "https://cdnjs.cloudflare.com/ajax/libs/monaco-editor/0.52.2/min/vs"},
            });
            window.require(["vs/editor/editor.main"], lambda -> None {
                if not window.__jac_monaco_lang_registered {
                    window.monaco.languages.register({"id": "jac"});
                    window.monaco.languages.setMonarchTokensProvider("jac", {
                        "keywords": [
                            "walker", "node", "edge", "obj", "has", "can", "def", "with",
                            "entry", "exit", "report", "visit", "spawn", "root", "here",
                            "visitor", "if", "elif", "else", "for", "while", "return",
                            "import", "from", "glob", "True", "False", "None", "try",
                            "except", "finally", "raise", "and", "or", "not", "in", "is",
                            "async", "await", "lambda", "class", "self", "super", "pub",
                            "priv", "test",
                        ],
                        "tokenizer": {
                            "root": [
                                [r"[a-zA-Z_]\w*", {"cases": {"@keywords": "keyword", "@default": "identifier"}}],
                                [r"\"([^\"\\]|\\.)*\"", "string"],
                                [r"'([^'\\]|\\.)*'", "string"],
                                [r"#.*$", "comment"],
                                [r"\d+", "number"],
                            ],
                        },
                    });
                    window.__jac_monaco_lang_registered = True;
                }
                theme = document.documentElement.getAttribute("data-theme") or "light";
                editor = window.monaco.editor.create(host, {
                    "value": initial,
                    "language": "jac",
                    "theme": "vs-dark" if theme == "dark" else "vs",
                    "fontSize": 14,
                    "fontFamily": "JetBrains Mono, ui-monospace, monospace",
                    "minimap": {"enabled": False},
                    "scrollBeyondLastLine": False,
                    "automaticLayout": True,
                    "padding": {"top": 12, "bottom": 12},
                });
                line_height = 20;
                lines = max(len(initial.split("\n")), 6);
                host.style.height = f"{lines * line_height + 24}px";
                on_ready(editor);
            });
        } except Exception {
            ta = document.createElement("textarea");
            ta.className = "runnable-fallback";
            ta.value = initial;
            host.appendChild(ta);
            on_ready(ta);
        }
    }


    def make_run_handler(block: any, run_btn: any, output: any, original_code: str) -> any {
        async def handler() -> None {
            run_btn.disabled = True;
            run_btn.textContent = "Running…";
            output.textContent = "";
            output.dataset.kind = "running";
            editor = block.__jac_editor;
            code = original_code;
            if editor {
                try {
                    code = editor.getValue();
                } except Exception {
                    try {
                        code = editor.value;
                    } except Exception {
                        code = original_code;
                    }
                }
            }
            try {
                result = await run_jac(code);
                stdout = str(result["stdout"]);
                stderr = str(result["stderr"]);
                if stdout {
                    output.textContent = stdout;
                }
                if stderr {
                    sep = "\n" if output.textContent else "";
                    output.textContent = output.textContent + sep + stderr;
                    output.dataset.kind = "error";
                } else {
                    output.dataset.kind = "ok";
                }
            } except Exception as e {
                output.textContent = str(e);
                output.dataset.kind = "error";
            }
            run_btn.disabled = False;
            run_btn.textContent = "▶ Run";
        }
        return handler;
    }


    def upgrade_block(block: any) -> None {
        if block.dataset.runnable_mounted {
            return;
        }
        block.dataset.runnable_mounted = "true";

        original_code = "";
        code_el = block.querySelector("pre code") or block.querySelector("code");
        if code_el {
            original_code = code_el.textContent;
        }

        block.innerHTML = "";
        block.className = "runnable-jac";

        header = document.createElement("div");
        header.className = "runnable-header";
        lang_el = document.createElement("span");
        lang_el.className = "code-lang";
        lang_el.textContent = "jac";
        header.appendChild(lang_el);
        run_btn = document.createElement("button");
        run_btn.type = "button";
        run_btn.className = "runnable-run";
        run_btn.textContent = "▶ Run";
        header.appendChild(run_btn);
        block.appendChild(header);

        editor_host = document.createElement("div");
        editor_host.className = "runnable-editor";
        block.appendChild(editor_host);

        output = document.createElement("pre");
        output.className = "runnable-output";
        output.textContent = "";
        block.appendChild(output);

        mount_monaco(editor_host, original_code, lambda editor: any -> None {
            block.__jac_editor = editor;
        });

        run_btn.addEventListener("click", make_run_handler(block, run_btn, output, original_code));
    }


    def:pub register_upgrade_hook() -> None {
        if window.__jac_runnable_upgrade {
            return;
        }
        def upgrade_all(blocks: any) -> None {
            for block in blocks {
                upgrade_block(block);
            }
        }
        window.__jac_runnable_upgrade = upgrade_all;
    }

