def build_toc(container: any) -> list {
    # Collect h2/h3 headings (the markdown `toc` extension already gave them ids
    # + a .headerlink anchor) into a flat list the sidebar renders as jump links.
    items = [];
    heads = container.querySelectorAll("h2[id], h3[id]");
    for h in heads {
        raw = str(h.textContent or "");
        link_el = h.querySelector(".headerlink");
        if link_el {
            # Drop the trailing ¶ permalink glyph from the visible label.
            raw = raw.replace(str(link_el.textContent or ""), "");
        }
        text = raw.strip();
        if not text {
            continue;
        }
        level = 2 if str(h.tagName) == "H2" else 3;
        items.append({"id": str(h.getAttribute("id")), "text": text, "level": level});
    }
    return items;
}


def setup_toc_scrollspy() -> None {
    # Highlight the section currently in view. We toggle classes directly on the
    # DOM (not React state) so scrolling never triggers re-renders, and keep a
    # single handler on window so SPA re-navigations don't stack listeners. The
    # handler queries .post-toc live, so it's a harmless no-op on non-post pages.
    if window.__tocScroll {
        window.removeEventListener("scroll", window.__tocScroll);
    }
    def on_scroll() -> None {
        toc_el = document.querySelector(".post-toc");
        if not toc_el {
            return;
        }
        # Hide the TOC once the article body has scrolled out of view, so it
        # doesn't overlay the related-posts grid / prev-next nav / footer.
        prose_el = document.querySelector(".post-shell .prose");
        if prose_el {
            rect = prose_el.getBoundingClientRect();
            past_article = rect.bottom < 160;
            if past_article {
                toc_el.classList.add("post-toc-hidden");
            } else {
                toc_el.classList.remove("post-toc-hidden");
            }
        }
        links = toc_el.querySelectorAll("a[data-toc-id]");
        current = "";
        for ln in links {
            target = document.getElementById(str(ln.getAttribute("data-toc-id")));
            if target and target.getBoundingClientRect().top <= 140 {
                current = str(ln.getAttribute("data-toc-id"));
            }
        }
        for ln in links {
            if current and str(ln.getAttribute("data-toc-id")) == current {
                ln.classList.add("is-active");
            } else {
                ln.classList.remove("is-active");
            }
        }
    }
    window.__tocScroll = on_scroll;
    window.addEventListener("scroll", on_scroll, {"passive": True});
    # Run once after the nav has painted so the first section highlights on load.
    setTimeout(on_scroll, 60);
}


# --- Reference rail ----------------------------------------------------------
# Posts link out to GitHub repos, YouTube videos and external sites. We surface
# those as a card timeline in the (otherwise empty) right gutter: a vertical
# spine with a favicon dot per link, and cards that expand as you scroll near
# the link. jaseci-owned and in-page links are skipped — they aren't references.

glob LINK_RAIL_SKIP = ["jaseci.org", "blogs.jaseci.org", "jac-lang.org", "jaclang.org"];


def classify_link(href: str) -> dict {
    # Returns {type, host}; type is "" for links that should not get a card.
    blank = {"type": "", "host": ""};
    # Parse via an anchor element: Jac emits a plain `URL(...)` call, but the
    # browser's URL is a constructor and throws without `new`. Setting an
    # anchor's href resolves relative links and exposes the parsed parts.
    parser = document.createElement("a") as any;
    parser.href = href;
    proto = str(parser.protocol or "");
    if (proto != "http:") and (proto != "https:") {
        return blank;
    }
    host = str(parser.hostname or "").lower();
    if host.startswith("www.") {
        host = host[4:];
    }
    cur = str(window.location.hostname or "").lower();
    if (host == cur) or (host in LINK_RAIL_SKIP) or host.endswith(".jaseci.org") {
        return blank;
    }
    segs = [s for s in str(parser.pathname or "").split("/") if s];
    if (host == "github.com") and (len(segs) >= 2) {
        return {"type": "github", "host": host};
    }
    if host in ["youtube.com", "m.youtube.com", "youtu.be"] {
        return {"type": "youtube", "host": host};
    }
    return {"type": "link", "host": host};
}


def build_link_rail(container: any) -> list {
    # Walk the rendered post in document order, tagging each card-worthy anchor
    # with an id the scrollspy can locate, and return the rail model.
    out = [];
    # Anchors AND embedded iframes (e.g. a YouTube <iframe> dropped into the
    # post), walked in document order.
    els = container.querySelectorAll("a[href], iframe[src]") as any;
    seen = {};
    i = 0;
    for el in els {
        is_iframe = (str(el.tagName or "").upper() == "IFRAME");
        if (not is_iframe) and el.classList.contains("headerlink") {
            continue;
        }
        raw = str((el.getAttribute("src") if is_iframe else el.getAttribute("href")) or "");
        if not raw {
            continue;
        }
        info = classify_link(raw);
        if not info["type"] {
            continue;
        }
        # Iframes only earn a card if they're a known embed (YouTube) — we don't
        # want arbitrary embedded frames in the reference rail.
        if is_iframe and (str(info["type"]) != "youtube") {
            continue;
        }
        # Only the first occurrence of a given link earns a dot on the timeline;
        # later repeats are skipped (keyed by the resolved URL).
        resolved = str((el.src if is_iframe else el.href) or raw);
        if resolved in seen {
            continue;
        }
        seen[resolved] = True;
        # Give the element an id so the scrollspy can locate it via
        # getElementById; reuse an existing id rather than clobber it.
        existing = str(el.getAttribute("id") or "");
        ref_id = existing if existing else ("lnk-" + str(i));
        if not existing {
            el.setAttribute("id", ref_id);
        }
        out.append({
            "id": ref_id,
            "type": str(info["type"]),
            "href": resolved,
            "host": str(info["host"]),
        });
        i = i + 1;
    }
    return out;
}


def setup_link_rail_scrollspy() -> None {
    # Mirror of the TOC scrollspy: toggle classes directly (no re-render). The
    # link whose anchor sits just above the 40% line is "active"; it and its two
    # neighbours expand into full cards (max 3), the rest collapse to dots.
    if window.__linkRailScroll {
        window.removeEventListener("scroll", window.__linkRailScroll);
    }
    def on_scroll() -> None {
        rail = document.querySelector(".link-rail") as any;
        if not rail {
            return;
        }
        # Hide the rail once the article body has scrolled out of view, so it
        # doesn't hang over the related-posts / footer area (mirrors the TOC).
        prose_el = document.querySelector(".post-shell .prose") as any;
        if prose_el {
            if prose_el.getBoundingClientRect().bottom < 160 {
                rail.classList.add("link-rail-hidden");
            } else {
                rail.classList.remove("link-rail-hidden");
            }
        }
        nodes = rail.querySelectorAll(".link-node") as any;
        line = window.innerHeight * 0.4;
        active = -1;
        best = -1000000.0;
        idx = 0;
        for el in nodes {
            ref = str(el.getAttribute("data-link-id") or "");
            target = document.getElementById(ref);
            if target {
                top = target.getBoundingClientRect().top;
                if (top <= line) and (top > best) {
                    best = top;
                    active = idx;
                }
            }
            idx = idx + 1;
        }
        # Before the first link scrolls into view, anchor the expansion on the
        # first card so the rail shows content (not just dots) at the top.
        focus = active if (active >= 0) else 0;
        idx2 = 0;
        for el in nodes {
            if idx2 == active {
                el.classList.add("is-active");
            } else {
                el.classList.remove("is-active");
            }
            if abs(idx2 - focus) <= 1 {
                el.classList.add("is-expanded");
            } else {
                el.classList.remove("is-expanded");
            }
            idx2 = idx2 + 1;
        }
    }
    window.__linkRailScroll = on_scroll;
    window.addEventListener("scroll", on_scroll, {"passive": True});
    setTimeout(on_scroll, 80);
}


def favicon_url(host: str) -> str {
    return "https://www.google.com/s2/favicons?domain=" + host + "&sz=64";
}


def render_link_card(item: any, meta: any) -> JsxElement {
    t = str(item["type"]);
    href = str(item["href"]);
    host = str(item["host"]);
    title = "";
    desc = "";
    vid = "";
    img = "";
    stars: any = 0;
    if meta {
        title = str(meta.get("title") or "");
        desc = str(meta.get("description") or "");
        vid = str(meta.get("video_id") or "");
        img = str(meta.get("image") or "");
        stars = meta.get("stars") or 0;
    }
    if t == "youtube" {
        # The video is already embedded inline in the post — the rail card is a
        # thumbnail + title that links out, not a second live player.
        watch = ("https://www.youtube.com/watch?v=" + vid) if vid else href;
        return <a className="link-card-link link-card-media" href={watch} target="_blank" rel="noopener noreferrer">
            {img and (
                <span className="link-thumb">
                    <img src={img} alt="" loading="lazy" />
                    <span className="link-thumb-play">▶</span>
                </span>
            )}
            <span className="link-card-host">YouTube</span>
            <span className="link-card-title">{title or "YouTube video"}</span>
        </a>;
    }
    label = "GitHub" if t == "github" else host;
    return <a className="link-card-link" href={href} target="_blank" rel="noopener noreferrer">
        <span className="link-card-host">{label}</span>
        <span className="link-card-title">{title or host}</span>
        {desc and <span className="link-card-desc">{desc}</span>}
        {(t == "github") and (stars > 0) and (
            <span className="link-card-meta">{"★ " + str(stars)}</span>
        )}
    </a>;
}


def render_repost_card(post: any, fallback_img: str = "") -> JsxElement {
    # The prominent "Originally published elsewhere" card shown at the top of a
    # repost. Metadata (title/description/image) is fetched server-side in
    # GetPost via link_meta; we fall back gracefully when it's missing.
    # fallback_img is a client-side unfurl result used when the server couldn't
    # resolve the og:image (see the microlink fallback in the route effect).
    url = str(post["repost_url"]);
    meta: any = post["repost_meta"] or {};
    host = str(meta.get("host") or "");
    if not host {
        # link_meta drops the host when the og fetch fails (e.g. 404). Recover
        # it from the URL via an anchor element (URL() needs `new`, which the
        # Jac→JS compiler doesn't emit) so the card always shows a source.
        parser = document.createElement("a") as any;
        parser.href = url;
        host = str(parser.hostname or "").lower();
        if host.startswith("www.") {
            host = host[4:];
        }
    }
    source = str(post["repost_source"]) or host or "the original site";
    ext_title = str(meta.get("title") or "");
    ext_desc = str(meta.get("description") or "");
    img = str(meta.get("image") or "") or fallback_img;
    return <aside className="repost-card">
        <a className="repost-card-link" href={url} target="_blank" rel="noopener noreferrer">
            {img and (
                <span className="repost-card-thumb">
                    <img src={img} alt="" loading="lazy" />
                </span>
            )}
            <span className="repost-card-body">
                <span className="repost-card-eyebrow">
                    {host and (
                        <img className="repost-card-favicon" src={favicon_url(host)} alt="" width={16} height={16} loading="lazy" />
                    )}
                    <span>{"Reposted from " + source}</span>
                </span>
                {ext_title and (<span className="repost-card-title">{ext_title}</span>)}
                {ext_desc and (<span className="repost-card-desc">{ext_desc}</span>)}
                <span className="repost-card-cta">{"Read the original on " + (host or source) + " →"}</span>
            </span>
        </a>
    </aside>;
}


# ── Reading analytics (client) ───────────────────────────────────────────────
# Anonymous, no-PII tracking that feeds the reviewer-only /analytics dashboard:
#   • a random visitor id in localStorage (unique vs repeat opens)
#   • active reading time (paused while the tab is hidden)
#   • deepest scroll % reached through the article body
# View is recorded on mount; the engagement sample is flushed once per visit on
# SPA navigation to another post (next mount) or on pagehide (tab close).

def analytics_visitor_id() -> str {
    # Stable random id; not tied to any account and never leaves the browser in
    # raw form (the server only ever stores a one-way hash of it). "" if storage
    # is blocked (private mode) — the open still counts toward the total.
    try {
        existing = window.localStorage.getItem("jaseci-blog-vid");
        if existing {
            return str(existing);
        }
        fresh = "";
        try {
            fresh = str(window.crypto.randomUUID());
        } except Exception {
            fresh = "v-" + str(int(Date.now()));
        }
        window.localStorage.setItem("jaseci-blog-vid", fresh);
        return fresh;
    } except Exception {
        return "";
    }
}


async def record_view(slug: str) -> None {
    try {
        root spawn RecordView(slug=str(slug), visitor=analytics_visitor_id());
    } except Exception {
        _ignore = None;
    }
}


async def record_link_click(slug: str, href: str) -> None {
    try {
        root spawn RecordLinkClick(slug=str(slug), href=str(href));
    } except Exception {
        _ignore = None;
    }
}


async def flush_engagement() -> None {
    # Send the current visit's reading sample exactly once.
    try {
        st = window.__blogTrack;
        if not st or st["sent"] or not st["slug"] {
            return;
        }
        now = int(Date.now());
        if st["resume"] > 0 {
            st["active"] = st["active"] + (now - st["resume"]);
            st["resume"] = 0;
        }
        # Skip non-reads. This filters genuine sub-second bounces AND, crucially,
        # the phantom unmount React Strict Mode fires immediately after mount in
        # dev (mount → unmount → remount), which would otherwise log a 0-time,
        # top-of-page sample on every open and pin every scroll metric to the
        # lowest bucket. We don't set `sent` here, so the real flush on actual
        # navigation away still records once engagement is meaningful.
        if (st["active"] < 1000) and (st["maxScroll"] < 25) {
            return;
        }
        st["sent"] = True;
        root spawn RecordEngagement(
            slug=str(st["slug"]),
            dwell_ms=float(st["active"]),
            scroll_pct=int(st["maxScroll"]),
        );
    } except Exception {
        _ignore = None;
    }
}


def compute_scroll_pct(container: any) -> int {
    # How far through the article body the viewport bottom has reached, 0..100.
    try {
        rect = container.getBoundingClientRect();
        height = container.offsetHeight;
        if height <= 0 {
            return 0;
        }
        abs_top = rect.top + window.scrollY;
        reached = (window.scrollY + window.innerHeight) - abs_top;
        pct = (reached / height) * 100.0;
        if pct < 0 {
            return 0;
        }
        if pct > 100 {
            return 100;
        }
        return int(pct);
    } except Exception {
        return 0;
    }
}


def setup_engagement_tracking(container: any, slug: str) -> None {
    # This effect runs twice per post mount: an [html] watcher bumps html_version
    # to force the enhancement pass to re-run after paint. On that second run the
    # tracker for THIS post already exists and hasn't been flushed — keep it as-is
    # rather than re-initializing, which would emit a spurious top-of-page,
    # zero-time sample (the bug that pinned every median scroll to the lowest
    # bucket). Only re-init when this is genuinely a different post.
    try {
        prev = window.__blogTrack;
        if prev and (prev["slug"] == slug) and (not prev["sent"]) {
            return;
        }
    } except Exception {
        _ignore = None;
    }
    # Flush the previous (different) post's pending sample first, in case it
    # wasn't already sent by the unmount/pagehide handlers.
    flush_engagement();

    visible = True;
    try {
        visible = (document.visibilityState != "hidden");
    } except Exception {
        _ignore = None;
    }
    window.__blogTrack = {
        "slug": slug,
        "active": 0,                              # accumulated active ms
        "resume": int(Date.now()) if visible else 0,  # ts the current visible segment began (0 = paused)
        "maxScroll": 0,                           # deepest scroll % reached
        "sent": False,
    };

    # Scroll depth (replace any prior listener, same idiom as the TOC scrollspy).
    try {
        if window.__blogScrollTrack {
            window.removeEventListener("scroll", window.__blogScrollTrack);
        }
    } except Exception {
        _ignore = None;
    }
    def on_scroll() -> None {
        st = window.__blogTrack;
        if not st {
            return;
        }
        p = compute_scroll_pct(container);
        if p > st["maxScroll"] {
            st["maxScroll"] = p;
        }
    }
    window.__blogScrollTrack = on_scroll;
    window.addEventListener("scroll", on_scroll, {"passive": True});
    setTimeout(on_scroll, 60);

    # Pause/resume active time on tab visibility changes (don't count background time).
    try {
        if window.__blogVisTrack {
            document.removeEventListener("visibilitychange", window.__blogVisTrack);
        }
    } except Exception {
        _ignore = None;
    }
    def on_vis() -> None {
        st = window.__blogTrack;
        if not st {
            return;
        }
        now = int(Date.now());
        if document.visibilityState == "hidden" {
            if st["resume"] > 0 {
                st["active"] = st["active"] + (now - st["resume"]);
                st["resume"] = 0;
            }
        } elif st["resume"] == 0 {
            st["resume"] = now;
        }
    }
    window.__blogVisTrack = on_vis;
    document.addEventListener("visibilitychange", on_vis);

    # Final flush on tab close / hard navigation (best-effort).
    try {
        if window.__blogHideTrack {
            window.removeEventListener("pagehide", window.__blogHideTrack);
        }
    } except Exception {
        _ignore = None;
    }
    def on_hide() -> None {
        flush_engagement();
    }
    window.__blogHideTrack = on_hide;
    window.addEventListener("pagehide", on_hide);

    # Delegated click tracking for links inside the article body. Bound to the
    # fresh per-post container (which is discarded on unmount, so no leak), and
    # only here — past the same-post dedup early-return above — so it attaches
    # once per post. Skips pure in-page anchors (#toc jumps).
    def on_link_click(e: any) -> None {
        try {
            anchor = e.target.closest("a");
            if anchor {
                href = anchor.getAttribute("href");
                if href and not str(href).startswith("#") {
                    record_link_click(slug, str(href));
                }
            }
        } except Exception {
            _ignore = None;
        }
    }
    container.addEventListener("click", on_link_click);
}


def:pub PostBody(html: str, slug: str) -> JsxElement {
    ref = useRef(None);
    has html_version: int = 0;
    has toc: list = [];
    has links: list = [];
    has link_meta: dict = {};

    can with [html] entry {
        html_version = html_version + 1;
    }

    # Flush the reading sample when the reader navigates away from the post
    # (SPA route change, incl. to a non-post page like /analytics). This is the
    # reliable signal; pagehide only covers hard tab-close/reload.
    can with exit {
        flush_engagement();
    }

    async can with [html_version] entry {
        if not ref.current {
            return;
        }
        container = ref.current;
        try {
            await mount_runnable_blocks(container);
        } except Exception {
            _ignore = None;
        }
        try {
            await enhance_code_blocks(container);
        } except Exception {
            _ignore = None;
        }
        try {
            await render_mermaid_blocks(container);
        } except Exception {
            _ignore = None;
        }
        try {
            toc = build_toc(container);
            setup_toc_scrollspy();
        } except Exception {
            _ignore = None;
        }
        try {
            found = build_link_rail(container);
            links = found;
            setup_link_rail_scrollspy();
            # Fetch card metadata for the unique hrefs (favicon dots render
            # immediately; titles/descriptions fill in when this returns).
            urls = [];
            seen = {};
            for lk in found {
                href = str(lk["href"]);
                if not (href in seen) {
                    seen[href] = True;
                    urls.append(href);
                }
            }
            if urls {
                resp = root spawn FetchLinkMeta(urls=urls);
                if resp.reports and (len(resp.reports) > 0) {
                    rep = resp.reports[0];
                    metas = rep["meta"] if ("meta" in rep) else [];
                    mp = {};
                    for m in metas {
                        mp[str(m["url"])] = m;
                    }
                    link_meta = mp;
                }
            }
        } except Exception {
            _ignore = None;
        }
        # Reading analytics: track active time + scroll depth for this article.
        try {
            setup_engagement_tracking(container, str(slug));
        } except Exception {
            _ignore = None;
        }
    }

    return <>
        {len(toc) > 1 and (
            <nav className="post-toc" aria-label="On this page">
                <p className="post-toc-title">On this page</p>
                <ul className="post-toc-list">
                    {[
                        <li key={item["id"]} className={f"post-toc-item post-toc-l{item['level']}"}>
                            <a href={f"#{item['id']}"} data-toc-id={item["id"]} className="post-toc-link">
                                {item["text"]}
                            </a>
                        </li>
                        for item in toc
                    ]}
                </ul>
            </nav>
        )}
        <div
            ref={ref}
            className="prose"
            dangerouslySetInnerHTML={{"__html": html}}
        />
        {len(links) > 0 and (
            <nav className="link-rail" aria-label="References in this post">
                {[
                    <div
                        className={f"link-node link-node-{item['type']}"}
                        data-link-id={item["id"]}
                        key={item["id"]}
                    >
                        <span className="link-dot">
                            <img
                                className="link-dot-img"
                                src={favicon_url(str(item["host"]))}
                                alt=""
                                loading="lazy"
                            />
                        </span>
                        <div className="link-card">
                            {render_link_card(item, link_meta.get(item["href"]))}
                        </div>
                    </div>
                    for item in links
                ]}
            </nav>
        )}
    </>;
}


def:pub page() -> JsxElement {
    params = useParams();
    slug = params["slug"];

    has loading: bool = True;
    has post: any = None;
    has error: str = "";
    has status: str = "";
    has pending_title: str = "";
    has share_copied: bool = False;
    has share_open: bool = False;
    has repost_img: str = "";

    async can with [slug] entry {
        window.scrollTo(0, 0);
        loading = True;
        error = "";
        status = "";
        pending_title = "";
        post = None;
        repost_img = "";
        unfurl_url = "";
        start: int = int(Date.now());
        # Optional draft-preview token from the URL (?preview=<token>): lets an
        # unpublished post render in full via a shared, persisted snapshot.
        preview_token = "";
        try {
            search = str(window.location.search or "");
            if search.startswith("?") {
                search = search[1:];
            }
            for pair in search.split("&") {
                if pair.startswith("preview=") {
                    preview_token = pair.split("=", 1)[1];
                }
            }
        } except Exception {
            _ignore = None;
        }
        try {
            result = root spawn GetPost(slug=str(slug), preview=preview_token);
            if result.reports and len(result.reports) > 0 {
                data = result.reports[0];
                if data["ok"] {
                    post = data;
                    # Count this open (anonymous; fire-and-forget).
                    try {
                        record_view(str(data["slug"]));
                    } except Exception {
                        _ignore = None;
                    }
                    document.title = f"{data['title']} · Jaseci Blogs";
                    meta_desc = str(data["description"]) or f"{data['reading_minutes']} min read on Jaseci Blogs.";
                    meta_url = "";
                    try {
                        meta_url = str(window.location.href);
                    } except Exception {
                        _ignore = None;
                    }
                    set_social_meta(str(data["title"]), meta_desc, meta_url, str(data["cover"]));
                    # Note whether the repost card needs a client-side image
                    # unfurl. Read the local `data`, not the reactive `post`
                    # (which is stale within this same effect block).
                    if bool(data["is_repost"]) {
                        rmeta_l: any = data["repost_meta"] or {};
                        if not str(rmeta_l.get("image") or "") {
                            unfurl_url = str(data["repost_url"] or "");
                        }
                    }
                } else {
                    error = str(data["error"]);
                    # Read into a local first: reading the reactive `has` back in
                    # this same effect block returns the stale pre-update value.
                    new_status = str(data["status"]);
                    status = new_status;
                    if new_status == "coming_soon" {
                        pending_title = str(data["title"]);
                    }
                }
            } else {
                error = "No response from server.";
            }
        } except Exception {
            error = "Network error.";
        }
        min_ms: int = 750;
        try {
            min_ms = int(window.__BLOG_CONFIG["minLoadingMs"]);
        } except Exception {
            _ignore = None;
        }
        remaining: int = min_ms - (int(Date.now()) - start);
        if remaining > 0 {
            setTimeout(lambda -> None { loading = False; }, remaining);
        } else {
            loading = False;
        }

        # Client-side unfurl fallback for the repost card image. The server's
        # link_meta() runs from the EKS pod, whose datacenter IP some sources'
        # WAFs 403 (e.g. cse.engin.umich.edu) — so the og:image comes back empty
        # in prod even though it resolves fine in local dev. Here we re-fetch it
        # from the reader's browser via microlink: microlink fetches the page
        # from its own infra (passes the WAF) and returns JSON with CORS headers
        # (Access-Control-Allow-Origin: *), so the browser can read it; the
        # resulting <img> then loads cross-origin normally. Fires only when the
        # server left the image blank (unfurl_url set above), so non-blocked
        # sources pay nothing.
        if unfurl_url {
            try {
                api = f"https://api.microlink.io/?url={encodeURIComponent(unfurl_url)}";
                resp: any = await fetch(api);
                jd: any = await resp.json();
                if str(jd["status"]) == "success" {
                    d: any = jd["data"];
                    im: any = d["image"];
                    got = str(im["url"]) if im else "";
                    if got {
                        repost_img = got;
                    }
                }
            } except Exception {
                _ignore = None;
            }
        }
    }

    if loading {
        return <>
            <div className="route-progress" />
            <article className="post-shell">
                <header className="post-header">
                    <div className="container narrow">
                        <span className="skeleton skeleton-line short" />
                        <span className="skeleton skeleton-title" style={{"height": "3.5rem", "width": "95%"}} />
                        <span className="skeleton skeleton-line long" />
                        <span className="skeleton skeleton-line medium" />
                        <div className="post-byline" style={{"borderColor": "var(--rule)"}}>
                            <span className="skeleton skeleton-avatar round" />
                            <span className="skeleton skeleton-line short" />
                        </div>
                    </div>
                </header>
                <div className="container narrow">
                    <span className="skeleton skeleton-line full" />
                    <span className="skeleton skeleton-line full" />
                    <span className="skeleton skeleton-line long" />
                    <span className="skeleton skeleton-line medium" />
                    <span className="skeleton skeleton-block" />
                    <span className="skeleton skeleton-line full" />
                    <span className="skeleton skeleton-line full" />
                    <span className="skeleton skeleton-line long" />
                </div>
            </article>
        </>;
    }
    if status == "coming_soon" {
        return <article className="post-shell">
            <div className="container narrow" style={{"padding": "4rem 0"}}>
                <p className="eyebrow">Coming soon</p>
                <h1 className="display">{pending_title or "This post isn't live yet"}</h1>
                <p className="post-deck">This post is in the editorial pipeline and hasn't been published yet. This link is permanent — it'll open the full article once the post goes live.</p>
                <p style={{"marginTop": "2rem"}}>
                    <Link className="cta-pill" to="/blog">← Back to latest</Link>
                </p>
            </div>
        </article>;
