    async def do_submit() -> None {
        submit_error = "";
        result = None;
        if not title.strip() {
            submit_error = "Title is required.";
            return;
        }
        if not slug.strip() {
            submit_error = "Slug is required.";
            return;
        }
        if not cats {
            submit_error = "Pick at least one category.";
            return;
        }
        if is_repost and not repost_url.strip() {
            submit_error = "Add the original article URL, or uncheck \"repost\".";
            return;
        }
        if len(body.strip()) < 50 {
            submit_error = "Post body is too short.";
            return;
