# path: jaseci-studio/pages/index.jac
cl import from "@jac/runtime" { Link }

cl {
    sv import from ..main { init_studio, get_dashboard, get_health, get_run_history, load_example_app }

    def:pub page -> JsxElement {
        has stats: dict = {},
            health: dict = {},
            recent_runs: list = [],
            loading: bool = true,
            loading_example: bool = false,
            example_loaded: bool = false;

        async can with entry {
            try {
                root spawn init_studio();
            } except Exception as e {
                print("Init error:", e);
            }

            try {
                dash_result = root spawn get_dashboard();
                if dash_result.reports and len(dash_result.reports) > 0 {
                    stats = dash_result.reports[0];
                }
            } except Exception as e {
                print("Dashboard error:", e);
            }

            try {
                health_result = root spawn get_health();
                if health_result.reports and len(health_result.reports) > 0 {
                    health = health_result.reports[0];
                }
            } except Exception as e {
                print("Health error:", e);
            }

            try {
                runs_result = root spawn get_run_history(limit=8);
                if runs_result.reports and len(runs_result.reports) > 0 {
                    recent_runs = runs_result.reports[0];
                }
            } except Exception as e {
                print("Runs error:", e);
            }

            loading = false;
        }

        async def handle_load_example -> None {
            loading_example = true;
            try {
                ex_result = root spawn load_example_app();
                if ex_result.reports and len(ex_result.reports) > 0 {
                    example_loaded = true;
                }
            } except Exception as e {
                print("Example load error:", e);
            }
            loading_example = false;
        }

        if loading {
            return
                <div className="page-loading">
                    <div className="spinner"></div>
                    <div className="loading-text">Loading dashboard...</div>
                </div>;
        }

        total = stats["total_runs"] or 0;
        successes = stats["success_runs"] or 0;
        errors = stats["error_runs"] or 0;
        models = stats["model_count"] or 0;
        h_status = health["status"] or "unknown";

        return
            <div className="page">
                <div className="page-header">
                    <div className="page-header-left">
                        <h1>Dashboard</h1>
                        <div className="subtitle">Overview of your Jac application runtime</div>
                    </div>
                    <div className="page-header-actions">
                        <span className={"badge " + ("badge-success" if h_status == "healthy" else "badge-warning")}>
                            <span className="badge-dot"></span>
                            {h_status}
                        </span>
                    </div>
                </div>

                <div className="stats-grid">
                    <div className="stat-card accent-stripe">
                        <div className="stat-icon">{"▶"}</div>
                        <div className="stat-value accent">{total}</div>
                        <div className="stat-label">Total Runs</div>
                    </div>
                    <div className="stat-card success-stripe">
                        <div className="stat-icon">{"✓"}</div>
                        <div className="stat-value success">{successes}</div>
                        <div className="stat-label">Successful</div>
                    </div>
                    <div className="stat-card error-stripe">
                        <div className="stat-icon">{"✗"}</div>
                        <div className="stat-value error">{errors}</div>
                        <div className="stat-label">Errors</div>
                    </div>
                    <div className="stat-card info-stripe">
                        <div className="stat-icon">{"⬣"}</div>
                        <div className="stat-value info">{models}</div>
                        <div className="stat-label">AI Models</div>
                    </div>
                </div>

                <div className="section-title">Quick Actions</div>
                <div className="quick-actions" style={{"marginBottom": "24px"}}>
                    <Link to="/workbench" className="quick-action">
                        <span className="qa-icon">{"⚙"}</span>
                        <div className="qa-text">
                            <div className="qa-title">Run a Walker</div>
                            <div className="qa-desc">Test and debug walkers interactively</div>
                        </div>
                    </Link>
                    <Link to="/graph" className="quick-action">
                        <span className="qa-icon">{"⬡"}</span>
                        <div className="qa-text">
                            <div className="qa-title">Explore Graph</div>
                            <div className="qa-desc">Browse nodes and edges visually</div>
                        </div>
                    </Link>
                    <div className="quick-action" onClick={lambda -> None { handle_load_example(); }} style={{"cursor": "pointer"}}>
                        <span className="qa-icon">{"📦"}</span>
                        <div className="qa-text">
                            <div className="qa-title">{loading_example and "Loading..." or (example_loaded and "Example Loaded!" or "Load Example App")}</div>
                            <div className="qa-desc">{example_loaded and "Todo tasks added to your graph" or "Add sample tasks to explore Studio features"}</div>
                        </div>
                    </div>
                </div>

                <div className="row">
                    <div className="col-2">
                        <div className="card">
                            <div className="card-header">
                                <div className="card-title">Recent Activity</div>
                                <Link to="/workbench" className="btn btn-ghost btn-sm">View all</Link>
                            </div>
                            {len(recent_runs) == 0
                            and <div className="empty-state">
                                <div className="empty-icon">{"▶"}</div>
                                <div className="empty-title">No runs yet</div>
                                <div className="empty-desc">Head to the Workbench to test your first walker</div>
                            </div>
                            or <div>
                                {[
                                    <div key={r["walker_name"] + r["executed_at"]} className="history-item">
                                        <div className={"history-dot " + r["status"]}>
                                        </div>
                                        <div className="history-info">
                                            <div className="history-name">{r["walker_name"]}</div>
                                            <div className="history-meta">{r["duration_ms"]}ms</div>
                                        </div>
                                        <div className="history-time">
                                            <span className={"badge badge-" + r["status"]}>{r["status"]}</span>
                                        </div>
                                    </div>
                                    for r in recent_runs
                                ]}
                            </div>}
                        </div>
                    </div>

                    <div className="col">
                        <div className="card">
                            <div className="card-header">
                                <div className="card-title">System Info</div>
                            </div>
                            <div style={{"display": "flex", "flexDirection": "column", "gap": "12px"}}>
                                <div style={{"display": "flex", "justifyContent": "space-between", "fontSize": "13px"}}>
                                    <span className="text-secondary">Status</span>
                                    <span className={"badge " + ("badge-success" if h_status == "healthy" else "badge-warning")}>
                                        <span className="badge-dot"></span>
                                        {h_status}
                                    </span>
                                </div>
                                <div style={{"display": "flex", "justifyContent": "space-between", "fontSize": "13px"}}>
                                    <span className="text-secondary">Uptime</span>
                                    <span className="mono">{health["uptime_seconds"] or 0}s</span>
                                </div>
                                <div style={{"display": "flex", "justifyContent": "space-between", "fontSize": "13px"}}>
                                    <span className="text-secondary">PID</span>
                                    <span className="mono">{health["pid"] or "-"}</span>
                                </div>
                                <div style={{"display": "flex", "justifyContent": "space-between", "fontSize": "13px"}}>
                                    <span className="text-secondary">Python</span>
                                    <span className="mono">{health["python_version"] or "-"}</span>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>;
    }
}

# path: jaseci-studio/pages/logs.jac
cl {
    sv import from ..main { get_server_logs }

    def:pub page -> JsxElement {
        has entries: list = [],
            loading: bool = true,
            level_filter: str = "",
            auto_refresh: bool = false,
            refresh_count: int = 0;

        async can with entry {
            try {
                r = root spawn get_server_logs(limit=200);
                if r.reports and len(r.reports) > 0 {
                    entries = r.reports[0];
                }
            } except Exception as e {
                print("Logs error:", e);
            }
            loading = false;
        }

        async def refresh_logs -> None {
            try {
                r = root spawn get_server_logs(limit=200, level=level_filter);
                if r.reports and len(r.reports) > 0 {
                    entries = r.reports[0];
                }
            } except Exception as e {
                print("Refresh error:", e);
            }
            refresh_count = refresh_count + 1;
        }

        def set_level(lvl: str) -> None {
            if level_filter == lvl {
                level_filter = "";
            } else {
                level_filter = lvl;
            }
            refresh_logs();
        }

        def level_color(lvl: str) -> str {
            if lvl == "ERROR" or lvl == "CRITICAL" { return "#ef4444"; }
            if lvl == "WARNING" { return "#f59e0b"; }
            if lvl == "INFO" { return "#10b981"; }
            if lvl == "DEBUG" { return "#6366f1"; }
            return "var(--text-secondary)";
        }

        def format_time(ts: any) -> str {
            d = Date(ts * 1000);
            h = d.getHours();
            m = d.getMinutes();
            s = d.getSeconds();
            return ("" + h + ":" + m + ":" + s);
        }

        if loading {
            return
                <div className="page-loading">
                    <div className="spinner"></div>
                    <div className="loading-text">Loading logs...</div>
                </div>;
        }

        return
            <div className="page">
                <div className="page-header">
                    <div className="page-header-left">
                        <h1>Server Logs</h1>
                        <div className="subtitle">Real-time server log output for debugging</div>
                    </div>
                    <div className="page-header-actions">
                        <button
                            className="btn btn-sm"
                            onClick={lambda -> None { refresh_logs(); }}
                            style={{"fontSize": "12px"}}
                        >
                            {"Refresh"}
                        </button>
                        <span className="badge badge-info" style={{"marginLeft": "6px"}}>
                            {len(entries)} entries
                        </span>
                    </div>
                </div>

                <div className="card" style={{"marginBottom": "16px", "padding": "10px 16px"}}>
                    <div style={{"display": "flex", "alignItems": "center", "gap": "8px"}}>
                        <span style={{"fontSize": "12px", "color": "var(--text-muted)", "marginRight": "4px"}}>Filter:</span>
                        {[
                            <div
                                key={lvl}
                                onClick={lambda -> None { set_level(lvl); }}
                                style={{
                                    "padding": "3px 10px",
                                    "borderRadius": "12px",
                                    "fontSize": "11px",
                                    "fontWeight": "600",
                                    "cursor": "pointer",
                                    "border": "1px solid " + level_color(lvl),
                                    "background": level_filter == lvl and (level_color(lvl) + "30") or "transparent",
                                    "color": level_color(lvl),
                                    "opacity": (not level_filter or level_filter == lvl) and "1" or "0.4"
                                }}
                            >
                                {lvl}
                            </div>
                            for lvl in ["DEBUG", "INFO", "WARNING", "ERROR"]
                        ]}
                        {level_filter and <div
                            onClick={lambda -> None { level_filter = ""; refresh_logs(); }}
                            style={{
                                "padding": "3px 10px",
                                "borderRadius": "12px",
                                "fontSize": "11px",
                                "cursor": "pointer",
                                "color": "var(--text-muted)",
                                "border": "1px solid var(--border)"
                            }}
                        >
                            {"Clear"}
                        </div>}
                    </div>
                </div>

                <div className="card">
                    {len(entries) == 0
                    and <div className="empty-state">
                        <div className="empty-icon">{">"}</div>
                        <div className="empty-title">No log entries</div>
                        <div className="empty-desc">
                            {level_filter and ("No " + level_filter + " entries found. Try clearing the filter.") or "Log entries will appear here as your app runs."}
                        </div>
                    </div>
                    or <div style={{"fontFamily": "var(--mono)", "fontSize": "12px", "lineHeight": "1.8"}}>
                        {[
                            <div
                                key={entry["timestamp"]}
                                style={{
                                    "display": "flex",
                                    "gap": "10px",
                                    "padding": "3px 0",
                                    "borderBottom": "1px solid var(--border)",
                                    "alignItems": "flex-start"
                                }}
                            >
                                <span style={{"color": "var(--text-muted)", "flexShrink": "0", "width": "60px"}}>
                                    {format_time(entry["timestamp"])}
                                </span>
                                <span style={{
                                    "flexShrink": "0",
                                    "width": "55px",
                                    "fontWeight": "700",
                                    "color": level_color(entry["level"]),
                                    "fontSize": "10px",
                                    "padding": "2px 0"
                                }}>
                                    {entry["level"]}
                                </span>
                                <span style={{
                                    "color": "var(--text-muted)",
                                    "flexShrink": "0",
                                    "width": "120px",
                                    "overflow": "hidden",
                                    "textOverflow": "ellipsis",
                                    "whiteSpace": "nowrap",
                                    "fontSize": "11px"
                                }}>
                                    {entry["logger"]}
                                </span>
                                <span style={{
                                    "flex": "1",
                                    "color": entry["level"] == "ERROR" and "#ef4444" or (entry["level"] == "WARNING" and "#f59e0b" or "var(--text-primary)"),
                                    "whiteSpace": "pre-wrap",
                                    "wordBreak": "break-all"
                                }}>
                                    {entry["message"]}
                                </span>
                            </div>
                            for entry in entries
                        ]}
                    </div>}
                </div>
            </div>;
    }
}

# path: jaseci-studio/pages/packages.jac
cl {
    sv import from ..main { list_packages, get_package_detail, install_package }

    def:pub page -> JsxElement {
        has packs: list = [],
            loading: bool = true,
            selected: any = None,
            installing: str = "",
            install_result: any = None,
            filter_category: str = "",
            search_query: str = "",
            copied_cmd: str = "";

        async can with entry {
            try {
                result = root spawn list_packages();
                if result.reports and len(result.reports) > 0 {
                    packs = result.reports[0];
                }
            } except Exception as e {
                print("Package list error:", e);
            }
            loading = false;
        }

        async def do_search -> None {
            loading = true;
            try {
                result = root spawn list_packages(category=filter_category, search=search_query);
                if result.reports and len(result.reports) > 0 {
                    packs = result.reports[0];
                }
            } except Exception as e {
                print("Search error:", e);
            }
            loading = false;
        }

        async def handle_install(pack_name: str) -> None {
            installing = pack_name;
            install_result = None;
            try {
                r = root spawn install_package(name=pack_name);
                if r.reports and len(r.reports) > 0 {
                    install_result = r.reports[0];
                }
            } except Exception as e {
                install_result = {"status": "error", "message": str(e)};
            }
            installing = "";
        }

        def copy_command(cmd: str) -> None {
            navigator.clipboard.writeText(cmd);
            copied_cmd = cmd;
            setTimeout(lambda -> None { copied_cmd = ""; }, 2000);
        }

        def get_difficulty_color(diff: str) -> str {
            if diff == "beginner" { return "#10b981"; }
            if diff == "intermediate" { return "#f59e0b"; }
            return "#ef4444";
        }

        def get_category_icon(cat: str) -> str {
            if cat == "AI" { return "⬣"; }
            if cat == "Starter" { return "▶"; }
            return "⚙";
        }

        if loading {
            return
                <div className="page-loading">
                    <div className="spinner"></div>
                    <div className="loading-text">Loading packages...</div>
                </div>;
        }

        return
            <div className="page">
                <div className="page-header">
                    <div className="page-header-left">
                        <h1>Packages</h1>
                        <div className="subtitle">Browse and install Jac application templates from jacpacks</div>
                    </div>
                    <div className="page-header-actions">
                        <span className="badge badge-info">{len(packs)} available</span>
                    </div>
                </div>

                <div style={{"display": "flex", "gap": "12px", "marginBottom": "20px"}}>
                    <input
                        type="text"
                        placeholder="Search packages..."
                        value={search_query}
                        onChange={lambda e: any -> None { search_query = e.target.value; do_search(); }}
                        style={{
                            "flex": "1",
                            "padding": "10px 14px",
                            "background": "var(--bg-secondary)",
                            "border": "1px solid var(--border)",
                            "borderRadius": "var(--radius)",
                            "color": "var(--text-primary)",
                            "fontSize": "14px"
                        }}
                    />
                    <div style={{"display": "flex", "gap": "6px"}}>
                        {[
                            <button
                                key={cat}
                                className={"btn " + ("btn-primary" if filter_category == cat else "btn-ghost")}
                                onClick={lambda -> None {
                                    filter_category = (filter_category == cat) and "" or cat;
                                    do_search();
                                }}
                                style={{"fontSize": "13px"}}
                            >
                                {cat or "All"}
                            </button>
                            for cat in ["", "Starter", "AI", "Developer Tools"]
                        ]}
                    </div>
                </div>

                {install_result and <div style={{
                    "padding": "16px",
                    "marginBottom": "20px",
                    "background": install_result["status"] == "error" and "#ef444418" or (install_result["status"] == "success" and "#10b98118" or "var(--bg-secondary)"),
                    "border": "1px solid " + (install_result["status"] == "error" and "#ef4444" or (install_result["status"] == "success" and "#10b981" or "var(--accent)")),
                    "borderRadius": "var(--radius)"
                }}>
                    <div style={{"display": "flex", "alignItems": "center", "gap": "8px", "marginBottom": "8px"}}>
                        <span style={{"fontSize": "18px"}}>
                            {install_result["status"] == "success" and "✓" or (install_result["status"] == "error" and "✗" or "ℹ")}
                        </span>
                        <div style={{"fontWeight": "600", "color": "var(--text-primary)"}}>
                            {install_result["status"] == "error" and "Installation Failed" or (install_result["status"] == "success" and "Installed Successfully" or install_result["package"])}
                        </div>
                        <button
                            className="btn btn-ghost btn-sm"
                            onClick={lambda -> None { install_result = None; }}
                            style={{"marginLeft": "auto", "fontSize": "11px"}}
                        >
                            Dismiss
                        </button>
                    </div>
                    <div style={{"fontSize": "13px", "color": "var(--text-secondary)", "marginBottom": "4px"}}>
                        {install_result["message"]}
                    </div>
                    {install_result["project_dir"] and <div style={{"fontSize": "12px", "color": "var(--text-muted)", "fontFamily": "var(--mono)"}}>
                        {install_result["project_dir"]}
                    </div>}
                    {install_result["command"] and <div style={{"marginTop": "8px"}}>
                        <div style={{"fontSize": "12px", "color": "var(--text-muted)", "marginBottom": "4px"}}>Or run manually:</div>
                        <div style={{"display": "flex", "gap": "8px", "alignItems": "center"}}>
                            <code style={{
                                "flex": "1",
                                "padding": "8px 12px",
                                "background": "var(--bg-primary)",
                                "border": "1px solid var(--border)",
                                "borderRadius": "var(--radius)",
                                "fontSize": "12px",
                                "fontFamily": "var(--mono)",
                                "color": "var(--accent)",
                                "overflowX": "auto"
                            }}>
                                {install_result["command"]}
                            </code>
                            <button
                                className="btn btn-ghost btn-sm"
                                onClick={lambda -> None { copy_command(install_result["command"]); }}
                            >
                                {copied_cmd == install_result["command"] and "Copied!" or "Copy"}
                            </button>
                        </div>
                    </div>}
                </div>}

                <div style={{
                    "display": "grid",
                    "gridTemplateColumns": "repeat(auto-fill, minmax(340px, 1fr))",
                    "gap": "16px"
                }}>
                    {[
                        <div key={p["name"]} className="card" style={{"cursor": "pointer", "transition": "border-color 0.2s", "border": selected and selected["name"] == p["name"] and "1px solid var(--accent)" or "1px solid var(--border)"}}>
                            <div style={{"display": "flex", "alignItems": "flex-start", "gap": "12px", "marginBottom": "12px"}}>
                                <div style={{
                                    "width": "40px",
                                    "height": "40px",
                                    "borderRadius": "10px",
                                    "background": "var(--accent)" + "18",
                                    "border": "1px solid var(--accent)" + "40",
                                    "display": "flex",
                                    "alignItems": "center",
                                    "justifyContent": "center",
                                    "fontSize": "18px",
                                    "flexShrink": "0"
                                }}>
                                    {get_category_icon(p["category"])}
                                </div>
                                <div style={{"flex": "1", "minWidth": "0"}}>
                                    <div style={{"fontWeight": "700", "fontSize": "15px", "color": "var(--text-primary)", "marginBottom": "2px"}}>{p["title"]}</div>
                                    <div style={{"display": "flex", "gap": "6px", "alignItems": "center"}}>
                                        <span className="badge" style={{"fontSize": "11px"}}>{p["category"]}</span>
                                        <span style={{"fontSize": "11px", "color": get_difficulty_color(p["difficulty"])}}>{p["difficulty"]}</span>
                                    </div>
                                </div>
                            </div>
                            <div style={{"fontSize": "13px", "color": "var(--text-secondary)", "lineHeight": "1.5", "marginBottom": "12px"}}>
                                {p["description"]}
                            </div>
                            <div style={{"display": "flex", "flexWrap": "wrap", "gap": "4px", "marginBottom": "12px"}}>
                                {[
                                    <span key={tag} style={{
                                        "fontSize": "11px",
                                        "padding": "2px 8px",
                                        "borderRadius": "10px",
                                        "background": "var(--bg-secondary)",
                                        "color": "var(--text-muted)"
                                    }}>
                                        {tag}
                                    </span>
                                    for tag in p["tags"]
                                ]}
                            </div>
                            <div style={{"display": "flex", "gap": "8px"}}>
                                <button
                                    className="btn btn-primary btn-sm"
                                    onClick={lambda -> None { handle_install(p["name"]); }}
                                    disabled={installing == p["name"]}
                                    style={{"flex": "1"}}
                                >
                                    {installing == p["name"] and "Installing..." or "Install"}
                                </button>
                                <a
                                    href={"https://github.com/jaseci-labs/jacpacks/tree/main/" + p["repo_path"]}
                                    target="_blank"
                                    className="btn btn-ghost btn-sm"
                                    style={{"textDecoration": "none"}}
                                >
                                    Source
                                </a>
                            </div>
                        </div>
                        for p in packs
                    ]}
                </div>

                {len(packs) == 0 and <div className="empty-state">
                    <div className="empty-icon">{"📦"}</div>
                    <div className="empty-title">No packages found</div>
                    <div className="empty-desc">{search_query and "Try a different search term" or "No packages match the selected filter"}</div>
                </div>}
            </div>;
    }
}

# path: jaseci-studio/pages/scheduler.jac
cl {
    sv import from ..main { list_schedules, create_schedule, toggle_schedule, delete_schedule }

    def:pub page -> JsxElement {
        has schedules: list = [],
            show_form: bool = false,
            walker_name: str = "",
            cron_expr: str = "*/5 * * * *",
            loading: bool = true,
            creating: bool = false;

        async can with entry {
            try {
                result = root spawn list_schedules();
                if result.reports and len(result.reports) > 0 {
                    schedules = result.reports[0];
                }
            } except Exception as e {
                print("Schedules error:", e);
            }
            loading = false;
        }

        async def handle_create -> None {
            if not walker_name {
                return;
            }
            creating = true;
            try {
                root spawn create_schedule(
                    walker_name=walker_name,
                    cron_expr=cron_expr
                );
                result = root spawn list_schedules();
                if result.reports and len(result.reports) > 0 {
                    schedules = result.reports[0];
                }
                walker_name = "";
                cron_expr = "*/5 * * * *";
                show_form = false;
            } except Exception as e {
                print("Create error:", e);
            }
            creating = false;
        }

        async def handle_toggle(schedule_id: str) -> None {
            try {
                root spawn toggle_schedule(schedule_id=schedule_id);
                result = root spawn list_schedules();
                if result.reports and len(result.reports) > 0 {
                    schedules = result.reports[0];
                }
            } except Exception as e {
                print("Toggle error:", e);
            }
        }

        async def handle_delete(schedule_id: str) -> None {
            try {
                root spawn delete_schedule(schedule_id=schedule_id);
                schedules = [s for s in schedules if s["id"] != schedule_id];
            } except Exception as e {
                print("Delete error:", e);
            }
        }

        active_count = len([s for s in schedules if s["enabled"]]);

        if loading {
            return
                <div className="page-loading">
                    <div className="spinner"></div>
                    <div className="loading-text">Loading schedules...</div>
                </div>;
        }

        return
            <div className="page">
                <div className="page-header">
                    <div className="page-header-left">
                        <h1>Scheduler</h1>
                        <div className="subtitle">Manage automated cron jobs and webhook triggers</div>
                    </div>
                    <div className="page-header-actions">
                        <button
                            className="btn btn-primary"
                            onClick={lambda -> None { show_form = not show_form; }}
                        >
                            {show_form and "Cancel" or "+ New Schedule"}
                        </button>
                    </div>
                </div>

                <div className="stats-grid" style={{"marginBottom": "24px"}}>
                    <div className="stat-card accent-stripe">
                        <div className="stat-value accent">{len(schedules)}</div>
                        <div className="stat-label">Total Schedules</div>
                    </div>
                    <div className="stat-card success-stripe">
                        <div className="stat-value success">{active_count}</div>
                        <div className="stat-label">Active</div>
                    </div>
                    <div className="stat-card warning-stripe">
                        <div className="stat-value warning">{len(schedules) - active_count}</div>
                        <div className="stat-label">Paused</div>
                    </div>
                </div>

                {show_form and <div className="card" style={{"marginBottom": "16px"}}>
                    <div className="card-header">
                        <div className="card-title">New Schedule</div>
                    </div>
                    <div className="row">
                        <div className="col">
                            <div className="form-group">
                                <label>Walker Name</label>
                                <input
                                    value={walker_name}
                                    onChange={lambda e: any -> None { walker_name = e.target.value; }}
                                    placeholder="get_dashboard"
                                />
                            </div>
                        </div>
                        <div className="col">
                            <div className="form-group">
                                <label>Cron Expression</label>
                                <input
                                    value={cron_expr}
                                    onChange={lambda e: any -> None { cron_expr = e.target.value; }}
                                    placeholder="*/5 * * * *"
                                />
                            </div>
                        </div>
                    </div>
                    <div style={{"fontSize": "11px", "color": "var(--text-muted)", "marginBottom": "12px"}}>
                        Examples: */5 * * * * (every 5 min) | 0 * * * * (hourly) | 0 0 * * * (daily)
                    </div>
                    <button
                        className="btn btn-primary"
                        onClick={lambda -> None { handle_create(); }}
                        disabled={creating or not walker_name}
                    >
                        {creating and "Creating..." or "Create Schedule"}
                    </button>
                </div>}

                {len(schedules) == 0
                and <div className="card">
                    <div className="empty-state">
                        <div className="empty-icon">{"⏰"}</div>
                        <div className="empty-title">No schedules configured</div>
                        <div className="empty-desc">Create a schedule to automatically run walkers on a cron timer</div>
                    </div>
                </div>
                or <div>
                    {[
                        <div key={s["id"]} className="schedule-item">
                            <div className="schedule-icon" style={{"color": (s["enabled"] and "var(--success)" or "var(--text-muted)")}}>
                                {s["enabled"] and "▶" or "⏸"}
                            </div>
                            <div className="schedule-info">
                                <div className="schedule-name">{s["walker_name"]}</div>
                                <div className="schedule-meta">
                                    <span className="mono">{s["cron_expr"]}</span>
                                    <span className={"badge " + ("badge-success" if s["enabled"] else "badge-warning")}>
                                        <span className="badge-dot"></span>
                                        {s["enabled"] and "active" or "paused"}
                                    </span>
                                </div>
                            </div>
                            <div className="schedule-actions">
                                <button
                                    className="btn btn-sm"
                                    onClick={lambda -> None { handle_toggle(s["id"]); }}
                                >
                                    {s["enabled"] and "Pause" or "Enable"}
                                </button>
                                <button
                                    className="btn btn-danger btn-sm"
                                    onClick={lambda -> None { handle_delete(s["id"]); }}
                                >
                                    Delete
                                </button>
                            </div>
                        </div>
                        for s in schedules
                    ]}
                </div>}
            </div>;
    }
}

# path: jaseci-studio/pages/workbench.jac
cl {
    sv import from ..main { list_walkers, run_walker_test, get_run_history }

    def:pub page -> JsxElement {
        has walkers: list = [],
            selected: str = "",
            selected_walker: any = None,
            payload: str = "{}",
            result: any = None,
            history: list = [],
            running: bool = false,
            loading: bool = true,
            tab: str = "result",
            copied: bool = false;

        async can with entry {
            try {
                w_result = root spawn list_walkers();
                if w_result.reports and len(w_result.reports) > 0 {
                    walkers = w_result.reports[0];
                }
            } except Exception as e {
                print("Walker list error:", e);
            }

            try {
                h_result = root spawn get_run_history(limit=15);
                if h_result.reports and len(h_result.reports) > 0 {
                    history = h_result.reports[0];
                }
            } except Exception as e {
                print("History error:", e);
            }

            loading = false;
        }

        def select_walker(name: str) -> None {
            selected = name;
            selected_walker = None;
            for w in walkers {
                if w["name"] == name {
                    selected_walker = w;
                    # Auto-generate payload template from walker params
                    params = w["params"] or [];
                    if len(params) > 0 {
                        template = {};
                        for p in params {
                            if p["default"] is not None and p["default"] != "None" {
                                template[p["name"]] = p["default"];
                            } else {
                                template[p["name"]] = "";
                            }
                        }
                        payload = JSON.stringify(template, None, 2);
                    } else {
                        payload = "{}";
                    }
                    break;
                }
            }
        }

        async def handle_run -> None {
            if not selected {
                return;
            }
            running = true;
            result = None;
            try {
                parsed = JSON.parse(payload);
                run_result = root spawn run_walker_test(
                    walker_name=selected,
                    payload=parsed
                );
                if run_result.reports and len(run_result.reports) > 0 {
                    result = run_result.reports[0];
                }
                tab = "result";
                h_result = root spawn get_run_history(limit=15);
                if h_result.reports and len(h_result.reports) > 0 {
                    history = h_result.reports[0];
                }
            } except Exception as e {
                result = {"error": str(e)};
            }
            running = false;
        }

        def copy_result -> None {
            if result {
                text = JSON.stringify(result["reports"] or result["result"], None, 2);
                navigator.clipboard.writeText(text);
                copied = true;
                setTimeout(lambda -> None { copied = false; }, 2000);
            }
        }

        if loading {
            return
                <div className="page-loading">
                    <div className="spinner"></div>
                    <div className="loading-text">Loading workbench...</div>
                </div>;
        }

        return
            <div className="page">
                <div className="page-header">
                    <div className="page-header-left">
                        <h1>Walker Workbench</h1>
                        <div className="subtitle">Test, debug, and inspect walker execution in real time</div>
                    </div>
                    <div className="page-header-actions">
                        <span className="badge badge-info">
                            {len(walkers)} walkers discovered
                        </span>
                    </div>
                </div>

                <div className="row">
                    <div className="col">
                        <div className="card">
                            <div className="card-header">
                                <div className="card-title">Execute Walker</div>
                                {selected_walker and <span className="badge badge-info">{selected_walker["module"]}</span>}
                            </div>
                            <div className="form-group">
                                <label>Select Walker</label>
                                <select
                                    value={selected}
                                    onChange={lambda e: any -> None { select_walker(e.target.value); }}
                                >
                                    <option value="">Choose a walker...</option>
                                    {[
                                        <option key={w["name"]} value={w["name"]}>
                                            {w["name"]}
                                        </option>
                                        for w in walkers
                                    ]}
                                </select>
                            </div>

                            {selected_walker and selected_walker["description"] and <div style={{"padding": "8px 12px", "background": "var(--bg-secondary)", "borderRadius": "var(--radius)", "marginBottom": "12px", "fontSize": "13px", "color": "var(--text-secondary)"}}>
                                {selected_walker["description"]}
                            </div>}

                            {selected_walker and selected_walker["params"] and len(selected_walker["params"]) > 0 and <div style={{"marginBottom": "12px"}}>
                                <div className="section-title">Parameters</div>
                                <div style={{"display": "flex", "flexWrap": "wrap", "gap": "6px"}}>
                                    {[
                                        <span key={p["name"]} className="badge" style={{"background": "var(--bg-secondary)", "color": "var(--text-primary)", "fontSize": "12px"}}>
                                            {p["name"]}: {p["type"]} {p["default"] and ("= " + p["default"]) or ""}
                                        </span>
                                        for p in selected_walker["params"]
                                    ]}
                                </div>
                            </div>}

                            <div className="form-group">
                                <label>Payload (JSON)</label>
                                <textarea
                                    className="code-editor"
                                    value={payload}
                                    onChange={lambda e: any -> None { payload = e.target.value; }}
                                    placeholder='{"key": "value"}'
                                    style={{"minHeight": "160px"}}
                                />
                            </div>
                            <button
                                className={"btn btn-primary" + (" btn-lg" if selected else "")}
                                onClick={lambda -> None { handle_run(); }}
                                disabled={running or not selected}
                                style={{"width": "100%"}}
                            >
                                {running and "Spawning..." or ("Spawn " + selected if selected else "Select a walker")}
                            </button>
                        </div>

                        <div className="card">
                            <div className="tab-bar">
                                <div
                                    className={"tab-item" + (" active" if tab == "result" else "")}
                                    onClick={lambda -> None { tab = "result"; }}
                                >
                                    Result
                                </div>
                                <div
                                    className={"tab-item" + (" active" if tab == "graph" else "")}
                                    onClick={lambda -> None { tab = "graph"; }}
                                >
                                    Graph Diff
                                </div>
                                <div
                                    className={"tab-item" + (" active" if tab == "history" else "")}
                                    onClick={lambda -> None { tab = "history"; }}
                                >
                                    History ({len(history)})
                                </div>
                            </div>

                            {tab == "result" and (
                                result
                                and <div>
                                    <div style={{"display": "flex", "alignItems": "center", "gap": "8px", "marginBottom": "12px"}}>
                                        <span className={"badge " + ("badge-success" if result["status"] == "success" else "badge-error")}>
                                            {result["status"]}
                                        </span>
                                        <span style={{"fontSize": "12px", "color": "var(--text-muted)"}}>{result["duration_ms"]}ms</span>
                                        <button
                                            className="btn btn-ghost btn-sm"
                                            onClick={lambda -> None { copy_result(); }}
                                            style={{"marginLeft": "auto"}}
                                        >
                                            {copied and "Copied!" or "Copy"}
                                        </button>
                                    </div>
                                    {result["status"] == "success"
                                    and <div>
                                        <div className="section-title">Reports</div>
                                        <div className="code-output">{JSON.stringify(result["reports"] or result["result"], None, 2)}</div>
                                    </div>
                                    or <div>
                                        <div className="section-title">Error</div>
                                        <div className="code-output" style={{"color": "var(--error)"}}>{JSON.stringify(result["result"], None, 2)}</div>
                                    </div>}
                                </div>
                                or <div className="empty-state">
                                    <div className="empty-icon">{"⚙"}</div>
                                    <div className="empty-title">No result yet</div>
                                    <div className="empty-desc">Select a walker and click Spawn to execute it on root</div>
                                </div>
                            )}

                            {tab == "graph" and (
                                result and result["graph_diff"]
                                and <div>
                                    <div className="section-title">Nodes Created ({len(result["graph_diff"]["created"])})</div>
                                    {len(result["graph_diff"]["created"]) > 0
                                    and <div className="code-output">{JSON.stringify(result["graph_diff"]["created"], None, 2)}</div>
                                    or <div style={{"color": "var(--text-muted)", "fontSize": "13px", "marginBottom": "12px"}}>No new nodes</div>}
                                    <div className="section-title">Nodes Modified ({len(result["graph_diff"]["modified"])})</div>
                                    {len(result["graph_diff"]["modified"]) > 0
                                    and <div className="code-output">{JSON.stringify(result["graph_diff"]["modified"], None, 2)}</div>
                                    or <div style={{"color": "var(--text-muted)", "fontSize": "13px"}}>No modifications</div>}
                                </div>
                                or <div className="empty-state">
                                    <div className="empty-icon">{"⬡"}</div>
                                    <div className="empty-title">No graph diff</div>
                                    <div className="empty-desc">Run a walker to see what nodes were created or modified</div>
                                </div>
                            )}

                            {tab == "history" and (
                                len(history) == 0
                                and <div className="empty">No runs recorded</div>
                                or <div>
                                    {[
                                        <div key={r["walker_name"] + r["executed_at"]} className="history-item">
                                            <div className={"history-dot " + r["status"]}></div>
                                            <div className="history-info">
                                                <div className="history-name">{r["walker_name"]}</div>
                                                <div className="history-meta">{r["duration_ms"]}ms</div>
                                            </div>
                                            <div className="history-time">
                                                <span className={"badge badge-" + r["status"]}>{r["status"]}</span>
                                            </div>
                                        </div>
                                        for r in history
                                    ]}
                                </div>
                            )}
                        </div>
                    </div>

                    <div className="col">
                        <div className="card">
                            <div className="card-header">
                                <div className="card-title">Discovered Walkers</div>
                                <div className="card-badge">{len(walkers)}</div>
                            </div>
                            {len(walkers) == 0
                            and <div className="empty">No walkers found in runtime</div>
                            or <div>
                                {[
                                    <div
                                        key={w["name"]}
                                        className={"history-item" + (" selected" if selected == w["name"] else "")}
                                        onClick={lambda -> None { select_walker(w["name"]); }}
                                        style={{"cursor": "pointer"}}
                                    >
                                        <div style={{"width": "8px", "height": "8px", "borderRadius": "50%", "background": (selected == w["name"] and "var(--accent)" or "var(--border-light)"), "flexShrink": "0"}}></div>
                                        <div className="history-info">
                                            <div className="history-name">{w["name"]}</div>
                                            <div className="history-meta">{w["description"] or w["module"]}</div>
                                        </div>
                                        {w["params"] and len(w["params"]) > 0 and <div style={{"fontSize": "11px", "color": "var(--text-muted)"}}>
                                            {len(w["params"])} params
                                        </div>}
                                    </div>
                                    for w in walkers
                                ]}
                            </div>}
                        </div>
                    </div>
                </div>
            </div>;
    }
}

